import React, { useState, useEffect, useCallback } from 'react';
import { Header } from './components/Header';
import { InputForm } from './components/InputForm';
import { ResultSection, downloadPDFElement } from './components/ResultSection';
import { AdBanner } from './components/AdBanner';
import { ActionButtons } from './components/ActionButtons';
import { Toast } from './components/Toast';
import { AdminDashboard } from './components/AdminDashboard';
import { INITIAL_DB, GLOBAL_100, detectCountry, DEFAULT_TEMPLATES } from './constants';
import { UserInput, StoryResult, ScenarioDB, ScenarioData, ScenarioTemplate, ComparisonRow, EssayData, DownloadableResource } from './types';
import { GlassCard } from './components/GlassCard';

function App() {
  const [db, setDb] = useState<ScenarioDB>(() => {
    const saved = localStorage.getItem('app_db');
    return saved ? JSON.parse(saved) : INITIAL_DB;
  });
  const [templates, setTemplates] = useState<ScenarioTemplate[]>(() => {
    const saved = localStorage.getItem('app_templates');
    return saved ? JSON.parse(saved) : DEFAULT_TEMPLATES;
  });

  const [isAdmin, setIsAdmin] = useState(false);
  const [showAdminLogin, setShowAdminLogin] = useState(false);
  const [adminPassword, setAdminPassword] = useState('');

  const [input, setInput] = useState<UserInput>({
    age: '',
    job: '',
    start: '',
    goal: '',
    months: 24,
    country: '',
    forcedTemplateId: ''
  });
  const [result, setResult] = useState<StoryResult | null>(null);
  const [loading, setLoading] = useState(false);
  const [toastMessage, setToastMessage] = useState<string | null>(null);

  useEffect(() => {
    if (window.location.hash === '#admin') setShowAdminLogin(true);
  }, []);

  // Persist DB and Templates to LocalStorage
  useEffect(() => {
    localStorage.setItem('app_db', JSON.stringify(db));
  }, [db]);
  useEffect(() => {
    localStorage.setItem('app_templates', JSON.stringify(templates));
  }, [templates]);

  const handleAdminLogin = () => {
    if (adminPassword === '1234') {
      setIsAdmin(true);
      setShowAdminLogin(false);
      setToastMessage("🔓 관리자 모드로 접속했습니다.");
    } else {
      alert("비밀번호가 올바르지 않습니다.");
    }
  };

  const handleInputChange = (field: keyof UserInput, value: string | number) => {
    setInput(prev => ({ ...prev, [field]: value }));
  };

  const generateStory = useCallback((generationInput: UserInput) => {
    setLoading(true);
    setResult(null); 

    setTimeout(() => {
      // 1. Prepare Variables with clear fallbacks for missing info
      const age = generationInput.age || '미지정';
      const job = generationInput.job || '미지정';
      const start = generationInput.start || '미지정';
      const goal = generationInput.goal || '미지정';
      const months = generationInput.months || 24;
      const countryKey = generationInput.country || detectCountry(goal);
      const config = GLOBAL_100[countryKey] || GLOBAL_100['default'];
      const isDefaultScenario = countryKey === 'default' && !generationInput.forcedTemplateId;

      // 2. Select Template Logic (Exact Matching Priority)
      let selectedTemplate: ScenarioTemplate | null = null;

      // PRIORITY 0: Forced Template ID (from Random Sample)
      if (generationInput.forcedTemplateId) {
        selectedTemplate = templates.find(t => t.id === generationInput.forcedTemplateId) || null;
      }

      if (!selectedTemplate) {
          const jobLower = job.toLowerCase();
          const goalLower = goal.toLowerCase();
          const startLower = start.toLowerCase();

          // Priority 1: Singapore -> Portugal (Specific)
          if ((startLower.includes('싱가포르') || startLower.includes('싱가폴')) && (goalLower.includes('포르투갈') || goalLower.includes('리스본'))) {
             selectedTemplate = templates.find(t => t.id === 'template_sg_pt' || t.tags.includes('portugal')) || null;
          }
          // Priority 2: Bali (Specific)
          else if (goalLower.includes('발리') || goalLower.includes('인도네시아')) {
             selectedTemplate = templates.find(t => t.id === 'template_bali_report' || t.tags.includes('bali')) || null;
          }
          // Priority 3: Gangnam/Seoul (Specific)
          else if (goalLower.includes('강남') || goalLower.includes('서울') || startLower.includes('의정부') || goalLower.includes('아파트')) {
             selectedTemplate = templates.find(t => t.id === 'template_gangnam_report' || t.tags.includes('gangnam')) || null;
          }

          // Fallback: Try to find a generic matching tag
          if (!selectedTemplate) {
              const genericMatch = templates.find(t => 
                 t.tags.some(tag => goalLower.includes(tag) || jobLower.includes(tag) || startLower.includes(tag))
              );
              if (genericMatch) selectedTemplate = genericMatch;
          }
      }

      // Final Fallback: If still no specific template is found, use the dedicated default template.
      if (!selectedTemplate) {
        selectedTemplate = templates.find(t => t.id === 'template_default') || templates[0];
      }

      // 3. Inject Variables into Template
      const inject = (text?: string) => {
        if (!text) return "";
        return text
          .replace(/{age}/g, age)
          .replace(/{job}/g, job)
          .replace(/{start}/g, start)
          .replace(/{goal}/g, goal)
          .replace(/{months}/g, months.toString())
          .replace(/{currency}/g, config.currency)
          .replace(/{prop}/g, config.prop)
          .replace(/{bank}/g, config.bank)
          .replace(/{visa}/g, config.visaName);
      };

      const randInt = (min: number, max: number) => Math.floor(Math.random() * (max - min + 1)) + min;

      // 4. Generate Result Table (Dynamic or from Template)
      let resultTable: ComparisonRow[] = [];

      if (selectedTemplate.resultTable) {
        // Use template-specific table if available
        resultTable = selectedTemplate.resultTable.map(row => ({
          item: inject(row.item),
          before: inject(row.before),
          after: inject(row.after),
          diff: inject(row.diff)
        }));
      } else {
        // Fallback Default Logic
        resultTable = [
            { item: '월 생활비', before: `${config.currency} 4,500`, after: `${config.currency} 3,200`, diff: `-1,300` },
            { item: '자산', before: '유동성 부족', after: '환차익 발생', diff: `+${randInt(1, 15)}%` },
            { item: '의료비', before: '보험 적용', after: '사립 병원', diff: '+200%' },
            { item: '순 저축', before: '100', after: '350', diff: '+250' }
        ];
      }

      // 5. Generate Essay (Dynamic)
      const defaultEssay: EssayData = {
        title: `${goal}의 현실: 숫자가 말해주지 않는 것들`,
        intro: `${start}를 떠나 ${goal}로 향하는 당신의 발걸음은 가볍겠지만, 현실의 무게는 결코 가볍지 않습니다.`,
        body: "우리는 종종 장소만 바뀌면 삶이 바뀔 것이라 착각합니다. 하지만 당신이 가져가는 것은 짐가방뿐만이 아닙니다. 당신의 불안과 습관도 국경을 넘습니다."
      };

      const essayData: EssayData = selectedTemplate.essay ? {
        title: inject(selectedTemplate.essay.title),
        intro: inject(selectedTemplate.essay.intro),
        body: inject(selectedTemplate.essay.body)
      } : defaultEssay;

      // 6. Generate Downloads (Dynamic)
      const downloads: DownloadableResource[] = selectedTemplate.downloads ? selectedTemplate.downloads.map(d => ({
        ...d,
        title: inject(d.title),
        description: inject(d.description),
        triggerUrl: inject(d.triggerUrl)
      })) : [];

      const scenarioData: ScenarioData = {
          success: randInt(40, 95),
          salary: config.avgSalary,
          visa: config.visaName,
          living: randInt(100, 450), 
          story: {
              header: inject(selectedTemplate.story.titleTemplate),
              subHeader: inject(selectedTemplate.story.subTemplate),
              stages: selectedTemplate.story.stages.map(s => ({
                label: s.label,
                title: inject(s.title),
                situation: inject(s.content.situation),
                thought: inject(s.content.thought),
                action: inject(s.content.action),
                experiment: inject(s.content.experiment),
                failure: inject(s.content.failure),
                question: inject(s.content.question),
                solution: inject(s.content.solution),
                result: inject(s.content.result),
                reality: inject(s.content.reality),
              })) as [any, any, any, any]
          },
          resultTable: resultTable,
          additionalInfo: {
              obstacles: ['EU 규제 강화', '환율 변동', '언어 장벽'],
              nextSteps: [
                  { label: '구글 검색', value: `${start} 은퇴자 ${goal} 비자 후기` },
                  { label: '유튜브', value: `${goal} 골든비자 폐지 후 대안` },
                  { label: 'PDF 다운로드', value: `${goal} NIF + 부동산세 가이드` }
              ]
          },
          essay: essayData,
          downloads: downloads,
          visaInfoUrl: config.visaInfoUrl,
      };

      // Set Title dynamically
      const title = scenarioData.story.header;
      const progress = randInt(50, 92);

      const newResult: StoryResult = {
        title,
        scenarioData,
        progress,
        userInput: generationInput,
        timestamp: new Date().toLocaleTimeString(),
        isDefault: isDefaultScenario,
      };

      setResult(newResult);
      setLoading(false);

      localStorage.setItem('lastStory', JSON.stringify({ input: newResult.userInput }));

      if (window.innerWidth < 1024) {
          setTimeout(() => {
            const resultEl = document.getElementById('result-anchor');
            if (resultEl) resultEl.scrollIntoView({ behavior: 'smooth', block: 'start' });
          }, 100);
      }

    }, 1500); 
  }, [templates, db]);

  const handleGenerateFromPrompt = (parsedData: Partial<UserInput>) => {
    const baseInput: UserInput = {
      age: '',
      job: '',
      start: '',
      goal: '',
      months: 24,
      country: '',
      forcedTemplateId: ''
    };
    const finalInput = { ...baseInput, ...parsedData };
    setInput(finalInput);
    generateStory(finalInput);
  };

  const handleRandom = () => {
    const samples = db.randomSamples || [];
    if (samples.length === 0) {
      setToastMessage("🎲 관리자 페이지에서 랜덤 예시를 추가해주세요.");
      return;
    }
    const random = samples[Math.floor(Math.random() * samples.length)];
    const baseInput: UserInput = {
      age: '',
      job: '',
      start: '',
      goal: '',
      months: 24,
      country: '',
      forcedTemplateId: ''
    };
    const finalInput = { ...baseInput, ...random };
    setInput(finalInput);
    setToastMessage("🎲 랜덤 시나리오를 구성했습니다.");
    setTimeout(() => generateStory(finalInput), 500);
  };

  const handleDownload = () => {
    if (result) {
      downloadPDFElement('pdf-content', `희망구매_${result.userInput.goal}_${Date.now()}`);
      setToastMessage("📄 리포트가 PDF로 저장되었습니다.");
    }
  };

  const handleSearch = (type: 'google' | 'youtube') => {
    const qGoal = input.goal || '이민';
    const qJob = input.job || '취업';
    const url = type === 'google' 
      ? `https://google.com/search?q=${input.age}세 ${qGoal} ${qJob} 현실 비용`
      : `https://youtube.com/results?search_query=${qGoal} ${qJob} 브이로그`;
    window.open(url);
  };

  return (
    <div className="min-h-screen bg-[#0f172a] text-white font-sans selection:bg-emerald-500 selection:text-white">
       <div className="fixed inset-0 overflow-hidden pointer-events-none">
          <div className="absolute top-[-10%] right-[-10%] w-[500px] h-[500px] bg-indigo-600/20 rounded-full blur-[100px]"></div>
          <div className="absolute bottom-[-10%] left-[-10%] w-[500px] h-[500px] bg-emerald-600/10 rounded-full blur-[100px]"></div>
       </div>

      <div className="relative w-full max-w-[1400px] mx-auto min-h-screen flex flex-col pb-safe px-4 md:px-6 lg:px-8">

        <div className="pt-4 md:pt-8 pb-6">
           <Header 
             scenarioCount={templates.length} 
             lastVerified={db.lastVerified}
             onAdminClick={() => setShowAdminLogin(true)}
           />
        </div>

        <div className="flex-1 grid grid-cols-1 lg:grid-cols-12 gap-6 lg:gap-8 items-start">

            <div className="lg:col-span-4 space-y-6 sticky top-8">
                <InputForm 
                  input={input}
                  onChange={handleInputChange}
                  onGenerate={handleGenerateFromPrompt}
                  onRandom={handleRandom}
                  onDownload={handleDownload}
                  canDownload={!!result}
                  isGenerating={loading}
                />

                <div className="hidden lg:block space-y-6">
                    <ActionButtons 
                      onGoogleSearch={() => handleSearch('google')}
                      onYoutubeSearch={() => handleSearch('youtube')}
                      onRandom={handleRandom}
                      onRefresh={() => window.location.reload()}
                      onReward={() => {}} 
                    />
                    <AdBanner />
                </div>
            </div>

            <div className="lg:col-span-8 space-y-6">
                <div id="result-anchor"></div>

                {!result && !loading && (
                    <div className="hidden lg:flex h-full min-h-[400px] items-center justify-center border-2 border-dashed border-white/10 rounded-3xl bg-white/5 text-gray-400">
                        <div className="text-center p-8">
                            <div className="text-4xl mb-4">👈</div>
                            <h3 className="text-xl font-bold mb-2">시뮬레이션을 시작하세요</h3>
                            <p className="text-sm">왼쪽 패널에 정보를 입력하고<br/>미래를 확인해보세요.</p>
                        </div>
                    </div>
                )}

                <ResultSection result={result} loading={loading} />

                <div className="lg:hidden space-y-6">
                    <AdBanner />
                    <ActionButtons 
                      onGoogleSearch={() => handleSearch('google')}
                      onYoutubeSearch={() => handleSearch('youtube')}
                      onRandom={handleRandom}
                      onRefresh={() => window.location.reload()}
                      onReward={() => {}} 
                    />
                </div>
            </div>
        </div>

        <div className="h-12"></div>
      </div>

      {showAdminLogin && (
          <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/80 backdrop-blur-md p-6">
            <GlassCard className="p-8 w-full max-w-sm text-center space-y-6 border border-white/20">
              <h2 className="text-2xl font-bold bg-gradient-to-r from-white to-gray-400 bg-clip-text text-transparent">System Access</h2>
              <input 
                type="password" 
                value={adminPassword}
                onChange={(e) => setAdminPassword(e.target.value)}
                onKeyDown={(e) => e.key === 'Enter' && handleAdminLogin()}
                className="w-full p-4 bg-white/5 rounded-xl text-center text-xl font-bold border border-white/10 focus:border-emerald-500 focus:outline-none transition-colors"
                placeholder="Passcode"
                autoFocus
              />
              <div className="flex gap-4">
                <button onClick={() => setShowAdminLogin(false)} className="flex-1 py-3 bg-gray-700/50 hover:bg-gray-700 rounded-xl transition-colors font-medium">Cancel</button>
                <button onClick={handleAdminLogin} className="flex-1 py-3 bg-emerald-600 hover:bg-emerald-500 rounded-xl transition-colors font-bold shadow-lg shadow-emerald-900/50">Enter</button>
              </div>
            </GlassCard>
          </div>
      )}

      {isAdmin && (
        <AdminDashboard 
          db={db} 
          onUpdateDb={setDb} 
          templates={templates} 
          onUpdateTemplates={setTemplates}
          onClose={() => setIsAdmin(false)} 
        />
      )}

      <Toast message={toastMessage} onClose={() => setToastMessage(null)} />
    </div>
  );
}

export default App;

import { GoogleGenAI, Type, SchemaType } from "@google/genai";
import { UserInput, ScenarioTemplate } from "./types";
import { detectCountry, GLOBAL_100 } from "./constants";

// Initialize Gemini Client
const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export const generateNewScenarioTemplate = async (input: UserInput): Promise<ScenarioTemplate | null> => {
  try {
    const countryKey = input.country || detectCountry(input.goal);
    const config = GLOBAL_100[countryKey] || GLOBAL_100['default'];

    // Define the schema for the AI response
    // We want the AI to generate a template with placeholders ({age}, {job}, etc.)
    const schema = {
      type: Type.OBJECT,
      properties: {
        id: { type: Type.STRING, description: "Unique ID like 'template_canada_immigration'" },
        type: { type: Type.STRING, enum: ["report", "essay"] },
        tags: { 
          type: Type.ARRAY, 
          items: { type: Type.STRING },
          description: "Keywords for matching (e.g., 'canada', 'vancouver', 'immigration')" 
        },
        story: {
          type: Type.OBJECT,
          properties: {
            titleTemplate: { type: Type.STRING, description: "Title with placeholders (e.g., '{age}세 {start} -> {goal} 이민')" },
            subTemplate: { type: Type.STRING, description: "Subtitle (e.g., '{months}개월 생존기')" },
            stages: {
              type: Type.ARRAY,
              description: "4 stages of the simulation",
              items: {
                type: Type.OBJECT,
                properties: {
                  label: { type: Type.STRING },
                  title: { type: Type.STRING },
                  content: {
                    type: Type.OBJECT,
                    properties: {
                      situation: { type: Type.STRING, nullable: true },
                      thought: { type: Type.STRING, nullable: true },
                      action: { type: Type.STRING, nullable: true },
                      experiment: { type: Type.STRING, nullable: true },
                      failure: { type: Type.STRING, nullable: true },
                      question: { type: Type.STRING, nullable: true },
                      solution: { type: Type.STRING, nullable: true },
                      result: { type: Type.STRING, nullable: true },
                      reality: { type: Type.STRING, nullable: true },
                    }
                  }
                }
              }
            }
          }
        },
        resultTable: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              item: { type: Type.STRING },
              before: { type: Type.STRING },
              after: { type: Type.STRING },
              diff: { type: Type.STRING }
            }
          }
        },
        essay: {
          type: Type.OBJECT,
          properties: {
            title: { type: Type.STRING },
            intro: { type: Type.STRING },
            body: { type: Type.STRING }
          }
        },
        downloads: {
            type: Type.ARRAY,
            items: {
                type: Type.OBJECT,
                properties: {
                    title: { type: Type.STRING },
                    description: { type: Type.STRING },
                    type: { type: Type.STRING, enum: ["pdf", "excel", "doc"] },
                    triggerType: { type: Type.STRING, enum: ["ad", "link"] },
                    triggerUrl: { type: Type.STRING, nullable: true }
                }
            }
        }
      },
      required: ["id", "type", "tags", "story", "essay"]
    };

    const prompt = `
      You are the engine of 'Hope Purchase Platform'. 
      User Input: Age ${input.age}, Job ${input.job}, Start ${input.start}, Goal ${input.goal}, Duration ${input.months} months.

      Task: Create a REALISTIC, CYNICAL, and ANALYTICAL simulation template for moving to ${input.goal}.

      CRITICAL REQUIREMENT:
      The output must be a REUSABLE TEMPLATE. 
      Use placeholders '{age}', '{job}', '{start}', '{goal}', '{months}', '{currency}' in the text strings where appropriate, instead of the hardcoded user values.
      However, keep specific country facts (e.g., specific Visa names, local rent prices in ${config.currency}, specific local problems) hardcoded.

      Tone:
      - "Dry Author" style: Cynical, realistic, focusing on hidden costs and psychological struggles.
      - Not a fairy tale. Highlight the specific difficulties of ${input.goal} (e.g., visa issues in US, slow admin in Europe, bugs in SE Asia).

      Structure:
      1. Story Stages: Create 4 distinct stages (Day 1, Early Failures, Crisis, Final Reality).
      2. Result Table: Compare specific costs (Rent, Tax, Healthcare) between ${input.start} and ${input.goal}.
      3. Essay: A cynical column about why moving to ${input.goal} won't fix internal problems.
      4. Downloads: Suggest 2 realistic resources (PDF/Excel) that would help (e.g., Specific Visa Checklist, Tax Calculator).

      Target Country Data for context:
      - Currency: ${config.currency}
      - Visa: ${config.visaName}
      - Avg Salary: ${config.avgSalary}
    `;

    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash-preview',
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: schema,
        temperature: 0.7, 
      }
    });

    const jsonText = response.text;
    if (!jsonText) return null;

    const generatedTemplate = JSON.parse(jsonText) as ScenarioTemplate;

    // Post-processing: Ensure tags include the goal for future matching
    if (!generatedTemplate.tags.includes(input.goal.toLowerCase())) {
        generatedTemplate.tags.push(input.goal.toLowerCase());
    }
    generatedTemplate.id = `ai_${Date.now()}_${input.goal.replace(/\s/g, '_')}`;

    return generatedTemplate;

  } catch (error) {
    console.error("Gemini AI Generation Failed:", error);
    return null;
  }
};

import React, { useState, useEffect, useCallback } from 'react';
import { Header } from './components/Header';
import { InputForm } from './components/InputForm';
import { ResultSection, downloadPDFElement } from './components/ResultSection';
import { AdBanner } from './components/AdBanner';
import { ActionButtons } from './components/ActionButtons';
import { Toast } from './components/Toast';
import { AdminDashboard } from './components/AdminDashboard';
import { INITIAL_DB, GLOBAL_100, detectCountry, DEFAULT_TEMPLATES } from './constants';
import { UserInput, StoryResult, ScenarioDB, ScenarioData, ScenarioTemplate, ComparisonRow, EssayData, DownloadableResource } from './types';
import { GlassCard } from './components/GlassCard';
import { generateNewScenarioTemplate } from './aiService';

function App() {
  const [db, setDb] = useState<ScenarioDB>(() => {
    const saved = localStorage.getItem('app_db');
    return saved ? JSON.parse(saved) : INITIAL_DB;
  });
  const [templates, setTemplates] = useState<ScenarioTemplate[]>(() => {
    const saved = localStorage.getItem('app_templates');
    return saved ? JSON.parse(saved) : DEFAULT_TEMPLATES;
  });

  const [isAdmin, setIsAdmin] = useState(false);
  const [showAdminLogin, setShowAdminLogin] = useState(false);
  const [adminPassword, setAdminPassword] = useState('');

  const [input, setInput] = useState<UserInput>({
    age: '',
    job: '',
    start: '',
    goal: '',
    months: 24,
    country: '',
    forcedTemplateId: ''
  });
  const [result, setResult] = useState<StoryResult | null>(null);
  const [loading, setLoading] = useState(false);
  const [aiGenerating, setAiGenerating] = useState(false);
  const [toastMessage, setToastMessage] = useState<string | null>(null);

  useEffect(() => {
    if (window.location.hash === '#admin') setShowAdminLogin(true);
  }, []);

  // Persist DB and Templates to LocalStorage
  useEffect(() => {
    localStorage.setItem('app_db', JSON.stringify(db));
  }, [db]);
  useEffect(() => {
    localStorage.setItem('app_templates', JSON.stringify(templates));
  }, [templates]);

  const handleAdminLogin = () => {
    if (adminPassword === '1234') {
      setIsAdmin(true);
      setShowAdminLogin(false);
      setToastMessage("🔓 관리자 모드로 접속했습니다.");
    } else {
      alert("비밀번호가 올바르지 않습니다.");
    }
  };

  const handleInputChange = (field: keyof UserInput, value: string | number) => {
    setInput(prev => ({ ...prev, [field]: value }));
  };

  const generateStory = useCallback(async (generationInput: UserInput) => {
    setLoading(true);
    setResult(null); 
    setAiGenerating(false);

    // 1. Prepare Variables
    const age = generationInput.age || '미지정';
    const job = generationInput.job || '미지정';
    const start = generationInput.start || '미지정';
    const goal = generationInput.goal || '미지정';
    const months = generationInput.months || 24;
    const countryKey = generationInput.country || detectCountry(goal);
    const config = GLOBAL_100[countryKey] || GLOBAL_100['default'];
    const isDefaultScenario = countryKey === 'default' && !generationInput.forcedTemplateId;

    // 2. Select Template Logic
    let selectedTemplate: ScenarioTemplate | null = null;
    let usedAI = false;

    // PRIORITY 0: Forced Template ID
    if (generationInput.forcedTemplateId) {
      selectedTemplate = templates.find(t => t.id === generationInput.forcedTemplateId) || null;
    }

    if (!selectedTemplate) {
        const jobLower = job.toLowerCase();
        const goalLower = goal.toLowerCase();
        const startLower = start.toLowerCase();

        // Check Existing Templates by Tags
        selectedTemplate = templates.find(t => 
             t.tags.some(tag => goalLower.includes(tag)) && 
             (t.tags.some(tag => jobLower.includes(tag) || startLower.includes(tag) || t.tags.length < 5)) // Loose matching
        ) || null;

        // --- GEMINI AI INTEGRATION START ---
        // If no specific template is found (only generic defaults would remain), AND we have an API key environment
        // We try to generate a NEW template using AI
        if (!selectedTemplate && process.env.API_KEY && goal !== '미지정') {
           setAiGenerating(true);
           try {
              const aiTemplate = await generateNewScenarioTemplate(generationInput);
              if (aiTemplate) {
                 selectedTemplate = aiTemplate;
                 // Save the new template for future reuse!
                 setTemplates(prev => [aiTemplate, ...prev]);
                 setToastMessage("🤖 AI가 새로운 시나리오를 분석하여 저장했습니다.");
                 usedAI = true;
              }
           } catch (e) {
              console.error("AI Generation failed, falling back to default", e);
           }
           setAiGenerating(false);
        }
        // --- GEMINI AI INTEGRATION END ---
    }

    // Final Fallback
    if (!selectedTemplate) {
      selectedTemplate = templates.find(t => t.id === 'template_default') || templates[0];
    }

    // 3. Inject Variables
    const inject = (text?: string) => {
      if (!text) return "";
      return text
        .replace(/{age}/g, age)
        .replace(/{job}/g, job)
        .replace(/{start}/g, start)
        .replace(/{goal}/g, goal)
        .replace(/{months}/g, months.toString())
        .replace(/{currency}/g, config.currency)
        .replace(/{prop}/g, config.prop)
        .replace(/{bank}/g, config.bank)
        .replace(/{visa}/g, config.visaName);
    };

    const randInt = (min: number, max: number) => Math.floor(Math.random() * (max - min + 1)) + min;

    // 4. Generate Result Table
    let resultTable: ComparisonRow[] = [];

    if (selectedTemplate.resultTable) {
      resultTable = selectedTemplate.resultTable.map(row => ({
        item: inject(row.item),
        before: inject(row.before),
        after: inject(row.after),
        diff: inject(row.diff)
      }));
    } else {
      resultTable = [
          { item: '월 생활비', before: `${config.currency} 4,500`, after: `${config.currency} 3,200`, diff: `-1,300` },
          { item: '자산', before: '유동성 부족', after: '환차익 발생', diff: `+${randInt(1, 15)}%` },
          { item: '의료비', before: '보험 적용', after: '사립 병원', diff: '+200%' },
          { item: '순 저축', before: '100', after: '350', diff: '+250' }
      ];
    }

    // 5. Generate Essay
    const defaultEssay: EssayData = {
      title: `${goal}의 현실: 숫자가 말해주지 않는 것들`,
      intro: `${start}를 떠나 ${goal}로 향하는 당신의 발걸음은 가볍겠지만, 현실의 무게는 결코 가볍지 않습니다.`,
      body: "우리는 종종 장소만 바뀌면 삶이 바뀔 것이라 착각합니다. 하지만 당신이 가져가는 것은 짐가방뿐만이 아닙니다. 당신의 불안과 습관도 국경을 넘습니다."
    };

    const essayData: EssayData = selectedTemplate.essay ? {
      title: inject(selectedTemplate.essay.title),
      intro: inject(selectedTemplate.essay.intro),
      body: inject(selectedTemplate.essay.body)
    } : defaultEssay;

    // 6. Generate Downloads
    const downloads: DownloadableResource[] = selectedTemplate.downloads ? selectedTemplate.downloads.map(d => ({
      ...d,
      title: inject(d.title),
      description: inject(d.description),
      triggerUrl: inject(d.triggerUrl)
    })) : [];

    const scenarioData: ScenarioData = {
        success: randInt(40, 95),
        salary: config.avgSalary,
        visa: config.visaName,
        living: randInt(100, 450), 
        story: {
            header: inject(selectedTemplate.story.titleTemplate),
            subHeader: inject(selectedTemplate.story.subTemplate),
            stages: selectedTemplate.story.stages.map(s => ({
              label: s.label,
              title: inject(s.title),
              situation: inject(s.content.situation),
              thought: inject(s.content.thought),
              action: inject(s.content.action),
              experiment: inject(s.content.experiment),
              failure: inject(s.content.failure),
              question: inject(s.content.question),
              solution: inject(s.content.solution),
              result: inject(s.content.result),
              reality: inject(s.content.reality),
            })) as [any, any, any, any]
        },
        resultTable: resultTable,
        additionalInfo: {
            obstacles: ['현지 규제', '환율 변동', '언어 장벽'],
            nextSteps: [
                { label: '구글 검색', value: `${start} 은퇴자 ${goal} 비자 후기` },
                { label: '유튜브', value: `${goal} 현지 물가 브이로그` },
                { label: 'PDF 다운로드', value: `${goal} 정착 가이드` }
            ]
        },
        essay: essayData,
        downloads: downloads,
        visaInfoUrl: config.visaInfoUrl,
    };

    const title = scenarioData.story.header;
    const progress = randInt(50, 92);

    const newResult: StoryResult = {
      title,
      scenarioData,
      progress,
      userInput: generationInput,
      timestamp: new Date().toLocaleTimeString(),
      isDefault: isDefaultScenario && !usedAI,
    };

    setResult(newResult);
    setLoading(false);

    localStorage.setItem('lastStory', JSON.stringify({ input: newResult.userInput }));

    if (window.innerWidth < 1024) {
        setTimeout(() => {
          const resultEl = document.getElementById('result-anchor');
          if (resultEl) resultEl.scrollIntoView({ behavior: 'smooth', block: 'start' });
        }, 100);
    }
  }, [templates, db]); // Removed timeout wrapper to allow async

  const handleGenerateFromPrompt = (parsedData: Partial<UserInput>) => {
    const baseInput: UserInput = {
      age: '',
      job: '',
      start: '',
      goal: '',
      months: 24,
      country: '',
      forcedTemplateId: ''
    };
    const finalInput = { ...baseInput, ...parsedData };
    setInput(finalInput);
    generateStory(finalInput);
  };

  const handleRandom = () => {
    const samples = db.randomSamples || [];
    if (samples.length === 0) {
      setToastMessage("🎲 관리자 페이지에서 랜덤 예시를 추가해주세요.");
      return;
    }
    const random = samples[Math.floor(Math.random() * samples.length)];
    const baseInput: UserInput = {
      age: '',
      job: '',
      start: '',
      goal: '',
      months: 24,
      country: '',
      forcedTemplateId: ''
    };
    const finalInput = { ...baseInput, ...random };
    setInput(finalInput);
    setToastMessage("🎲 랜덤 시나리오를 구성했습니다.");
    setTimeout(() => generateStory(finalInput), 500);
  };

