    stages: [
      { label: string; title: string; content: Partial<SimulationStage> },
      { label: string; title: string; content: Partial<SimulationStage> },
      { label: string; title: string; content: Partial<SimulationStage> },
      { label: string; title: string; content: Partial<SimulationStage> }
