import React, { useState, useEffect } from 'react';
import { GlassCard } from './GlassCard';
import { ScenarioDB, ScenarioTemplate, DownloadableResource, UserInput } from '../types';
import { DEFAULT_TEMPLATES } from '../constants';

interface AdminDashboardProps {
  db: ScenarioDB;
  onUpdateDb: (newDb: ScenarioDB) => void;
  templates: ScenarioTemplate[];
  onUpdateTemplates: (newTemplates: ScenarioTemplate[]) => void;
  onClose: () => void;
}

const RandomSampleEditor: React.FC<{db: ScenarioDB, onUpdateDb: (newDb: ScenarioDB) => void, templates: ScenarioTemplate[]}> = ({ db, onUpdateDb, templates }) => {
    const [samples, setSamples] = useState<Partial<UserInput>[]>(db.randomSamples || []);

    // DB가 외부에서 변경되었을 때 동기화
    useEffect(() => {
        if(db.randomSamples) {
            setSamples(db.randomSamples);
        }
    }, [db.randomSamples]);

    const handleUpdate = (index: number, field: keyof UserInput, value: string | number | boolean) => {
        const newSamples = [...samples];
        newSamples[index] = { ...newSamples[index], [field]: value };

        // AI 모드가 켜지면 템플릿 ID는 비움 (충돌 방지)
        if (field === 'useAI' && value === true) {
            newSamples[index].forcedTemplateId = '';
        }

        setSamples(newSamples);
    };

    const handleSave = () => {
        // Force update the parent DB state
        const updatedDb = { ...db, randomSamples: samples };
        onUpdateDb(updatedDb);

        // Ensure LocalStorage is updated immediately (backup mechanism)
        localStorage.setItem('app_db', JSON.stringify(updatedDb));

        // 저장 피드백 애니메이션
        const btn = document.getElementById('save-samples-btn');
        if(btn) {
            const originalText = btn.innerHTML;
            btn.innerHTML = "✅ 저장 완료!";
            btn.classList.remove('bg-emerald-600', 'hover:bg-emerald-500');
            btn.classList.add('bg-green-500');
            setTimeout(() => {
                btn.innerHTML = originalText;
                btn.classList.add('bg-emerald-600', 'hover:bg-emerald-500');
                btn.classList.remove('bg-green-500');
            }, 2000);
        }
    };

    const handleAdd = () => {
        setSamples([...samples, { age: '30', job: '직장인', start: '서울', goal: '미국', months: 24, forcedTemplateId: '', isDomestic: false, useAI: false }]);
    };

    const handleRemove = (index: number) => {
        if (confirm('이 예시를 삭제하시겠습니까?')) {
            const newSamples = [...samples];
            newSamples.splice(index, 1);
            setSamples(newSamples);
        }
    };

    return (
        <div className="h-full overflow-y-auto p-6 md:p-8 space-y-6 pb-20">
            <GlassCard className="p-6 border-l-4 border-l-purple-500">
                 <div className="flex justify-between items-center mb-6">
                    <div>
                        <h3 className="text-xl font-bold flex items-center gap-2">
                           🔀 랜덤 예시 & 결과 매칭
                           <span className="text-xs bg-purple-500/20 text-purple-300 px-2 py-1 rounded-full">{samples.length}개</span>
                        </h3>
                        <p className="text-xs text-gray-400 mt-1">입력값과 출력될 시나리오 방식을 설정하고 저장하세요.</p>
                    </div>
                    <button 
                        id="save-samples-btn"
                        onClick={handleSave} 
                        className="px-6 py-2.5 bg-emerald-600 hover:bg-emerald-500 rounded-xl font-bold text-xs text-white shadow-lg transition-all flex items-center gap-2"
                    >
                        <span>💾</span> 변경사항 저장
                    </button>
                 </div>

                 <div className="grid gap-4">
                    {samples.map((sample, index) => (
                         <div key={index} className="bg-white/5 border border-white/10 rounded-xl p-4 relative group hover:border-purple-500/30 transition-colors">
                            <button 
                                onClick={() => handleRemove(index)} 
                                className="absolute -top-2 -right-2 bg-red-500 text-white rounded-full w-6 h-6 flex items-center justify-center shadow-lg opacity-0 group-hover:opacity-100 transition-opacity z-10 hover:bg-red-600"
                                title="삭제"
                            >
                                ×
                            </button>

                            <div className="grid grid-cols-2 md:grid-cols-12 gap-3 items-end">
                                {/* Input Fields Group */}
                                <div className="col-span-1 md:col-span-1">
                                    <label className="block text-[10px] text-gray-500 mb-1 uppercase tracking-wider">나이</label>
                                    <input 
                                        value={sample.age || ''} 
                                        onChange={(e) => handleUpdate(index, 'age', e.target.value)} 
                                        className="w-full bg-black/30 p-2.5 rounded-lg text-sm border border-transparent focus:border-purple-500 focus:outline-none text-center"
                                        placeholder="00"
                                    />
                                </div>
                                <div className="col-span-1 md:col-span-2">
                                    <label className="block text-[10px] text-gray-500 mb-1 uppercase tracking-wider">직업</label>
                                    <input 
                                        value={sample.job || ''} 
                                        onChange={(e) => handleUpdate(index, 'job', e.target.value)} 
                                        className="w-full bg-black/30 p-2.5 rounded-lg text-sm border border-transparent focus:border-purple-500 focus:outline-none"
                                        placeholder="직업 입력"
                                    />
                                </div>
                                <div className="col-span-1 md:col-span-1">
                                    <label className="block text-[10px] text-gray-500 mb-1 uppercase tracking-wider">출발</label>
                                    <input 
                                        value={sample.start || ''} 
                                        onChange={(e) => handleUpdate(index, 'start', e.target.value)} 
                                        className="w-full bg-black/30 p-2.5 rounded-lg text-sm border border-transparent focus:border-purple-500 focus:outline-none"
                                        placeholder="출발지"
                                    />
                                </div>
                                <div className="col-span-1 md:col-span-1">
                                    <label className="block text-[10px] text-gray-500 mb-1 uppercase tracking-wider">도착</label>
                                    <input 
                                        value={sample.goal || ''} 
                                        onChange={(e) => handleUpdate(index, 'goal', e.target.value)} 
                                        className="w-full bg-black/30 p-2.5 rounded-lg text-sm border border-transparent focus:border-purple-500 focus:outline-none font-bold text-emerald-400"
                                        placeholder="도착지"
                                    />
                                </div>
                                <div className="col-span-2 md:col-span-1">
                                    <label className="block text-[10px] text-gray-500 mb-1 uppercase tracking-wider">이동타입</label>
                                    <select 
                                        value={sample.isDomestic ? 'domestic' : 'intl'} 
                                        onChange={(e) => handleUpdate(index, 'isDomestic', e.target.value === 'domestic')} 
                                        className="w-full bg-black/30 p-2.5 rounded-lg text-sm border border-transparent focus:border-purple-500 focus:outline-none"
                                    >
                                        <option value="intl">해외</option>
                                        <option value="domestic">국내</option>
                                    </select>
                                </div>

                                {/* Control Group: AI vs Existing Template */}
                                <div className={`col-span-2 md:col-span-6 p-2 rounded-lg border transition-all ${sample.useAI ? 'bg-emerald-900/30 border-emerald-500' : 'bg-white/5 border-white/10'}`}>
                                    <div className="flex items-center gap-2 mb-1">
                                        <input 
                                            type="checkbox"
                                            id={`use-ai-${index}`}
                                            checked={!!sample.useAI}
                                            onChange={(e) => handleUpdate(index, 'useAI', e.target.checked)}
                                            className="w-4 h-4 text-emerald-600 bg-gray-700 border-gray-600 rounded focus:ring-emerald-500 focus:ring-2"
                                        />
                                        <label htmlFor={`use-ai-${index}`} className={`text-xs font-bold cursor-pointer select-none ${sample.useAI ? 'text-emerald-400' : 'text-gray-400'}`}>
                                            🤖 AI 신규 생성 모드
                                        </label>
                                    </div>

                                    {!sample.useAI ? (
                                        <select
                                            value={sample.forcedTemplateId || ''}
                                            onChange={(e) => handleUpdate(index, 'forcedTemplateId', e.target.value)}
                                            className="w-full bg-black/50 p-2 rounded text-xs text-white border border-white/10 focus:border-indigo-500 focus:outline-none"
                                        >
                                            <option value="">(기본: 태그 매칭)</option>
                                            {templates.map(t => (
                                                <option key={t.id} value={t.id}>
                                                    {t.id.startsWith('ai_') ? '🤖 ' : '📄 '}
                                                    {t.id}
                                                </option>
                                            ))}
                                        </select>
                                    ) : (
                                        <div className="text-[10px] text-emerald-200/80 px-1 py-1">
                                            실행 시 AI가 새 시나리오를 생성하고 <strong className="text-emerald-400 underline decoration-emerald-500">영구 저장</strong>합니다.
                                        </div>
                                    )}
                                </div>
                            </div>
                         </div>
                    ))}

                    <button 
                        onClick={handleAdd} 
                        className="w-full py-4 bg-white/5 hover:bg-white/10 border border-dashed border-white/20 rounded-xl text-sm font-bold text-gray-400 hover:text-white transition-colors flex items-center justify-center gap-2 group"
                    >
                        <span className="group-hover:scale-125 transition-transform">➕</span> 새 랜덤 시나리오 추가
                    </button>
                 </div>
            </GlassCard>
        </div>
    );
};

export const AdminDashboard: React.FC<AdminDashboardProps> = ({ 
  db, 
  onUpdateDb, 
  templates, 
  onUpdateTemplates, 
  onClose 
}) => {
  const [activeTab, setActiveTab] = useState<'control' | 'templates' | 'samples'>('control');
  const [logs, setLogs] = useState<string[]>([]);

  // Template Editing State
  const [selectedTemplateId, setSelectedTemplateId] = useState<string | null>(null);
  const [jsonInput, setJsonInput] = useState<string>('');
  const [isEditing, setIsEditing] = useState(false);
  const [editMode, setEditMode] = useState<'json' | 'easy'>('easy');

  // Temporary state for Easy Editor
  const [easyData, setEasyData] = useState<ScenarioTemplate | null>(null);

  const addLog = (msg: string) => {
    const timestamp = new Date().toLocaleTimeString();
    setLogs(prev => [`[${timestamp}] ${msg}`, ...prev]);
  };

  const handleVerifyAll = () => {
    addLog("🤖 AI 전체 검증 시작... (Data Integrity Check)");
    setTimeout(() => {
      onUpdateDb({
        ...db,
        lastVerified: new Date().toLocaleString(),
        changes: [
          { type: '시스템', details: '100개 시나리오 정합성 검증 완료', timestamp: new Date().toLocaleString() },
          ...db.changes
        ]
      });
      addLog("✅ 검증 완료. 데이터베이스가 최신 상태입니다.");
    }, 1500);
  };

  const handleSelectTemplate = (t: ScenarioTemplate) => {
    setSelectedTemplateId(t.id);
    const jsonStr = JSON.stringify(t, null, 2);
    setJsonInput(jsonStr);
    setEasyData(JSON.parse(jsonStr)); // Deep copy
    setIsEditing(true);
  };

  const handleCreateNew = () => {
    const newTemplate = { ...DEFAULT_TEMPLATES[0], id: `custom_${Date.now()}`, tags: ['new'] };
    setSelectedTemplateId(null);
    const jsonStr = JSON.stringify(newTemplate, null, 2);
    setJsonInput(jsonStr);
    setEasyData(newTemplate);
    setIsEditing(true);
  };

  const handleSaveTemplate = () => {
    try {
      const payload = editMode === 'easy' && easyData ? easyData : JSON.parse(jsonInput);

      if (!payload.id || !payload.story) throw new Error("Invalid Format");

      const exists = templates.find(t => t.id === payload.id);
      let newTemplates;

      if (exists) {
