export const generateNewScenarioTemplate = async (input: UserInput): Promise<ScenarioTemplate | null> => {
  try {
    const countryKey = input.country || detectCountry(input.goal);
    const config = GLOBAL_100[countryKey] || GLOBAL_100['default'];

    // Determine context nuances based on Domestic vs International
    const domesticInstruction = `
      This is a **DOMESTIC MOVE** (Within the same country).
      - **DO NOT** mention Visas, Immigration checkpoints, or Currency Exchange.
      - **FOCUS ON**: Real estate prices (Jeonse/Monthly), School districts (8-hakgun), Regional prejudice, Commuting hell, City vs Countryside lifestyle gaps.
      - Comparison Table: Compare Rent vs Rent, Commute Time vs Commute Time, Private Academy Costs.
    `;

    const internationalInstruction = `
      This is an **INTERNATIONAL MOVE** (Crossing borders).
      - **FOCUS ON**: Visas (${config.visaName}), Language barriers, Cultural racism, Tax residency, Healthcare access (Insurance vs Private).
      - Comparison Table: Cost of Living, Tax Rates, Safety, Medical Costs.
    `;

    const contextDescription = `
      User Profile:
      - Age: ${input.age}
      - Job: ${input.job}
      - From: ${input.start} -> To: ${input.goal}
      - Family: ${input.family || 'Single'}
      - Move Type: ${input.moveType || 'General Move'}
      - Assets: ${input.assets || 'Unknown'}
      - **Is Domestic Move?**: ${input.isDomestic ? 'YES (Domestic)' : 'NO (International)'}
    `;

    // Define the schema for the AI response
    const schema = {
      type: Type.OBJECT,
      properties: {
        id: { type: Type.STRING, description: "Unique ID like 'template_seoul_jeju_domestic' or 'template_korea_canada_immig'" },
        type: { type: Type.STRING, enum: ["report", "essay"] },
        tags: { 
          type: Type.ARRAY, 
          items: { type: Type.STRING },
          description: "Keywords including location, job, move type, family status, domestic/international" 
        },
        story: {
          type: Type.OBJECT,
          properties: {
            titleTemplate: { type: Type.STRING, description: "Title with placeholders (e.g., '{age}세 {job}의 {goal} 리얼 생존기')" },
            subTemplate: { type: Type.STRING, description: "Subtitle (e.g., '{family}의 {months}개월 정착 시뮬레이션')" },
            stages: {
              type: Type.ARRAY,
              description: "4 stages of the simulation",
              items: {
                type: Type.OBJECT,
                properties: {
                  label: { type: Type.STRING },
                  title: { type: Type.STRING },
                  content: {
                    type: Type.OBJECT,
                    properties: {
                      situation: { type: Type.STRING, nullable: true },
                      thought: { type: Type.STRING, nullable: true },
                      action: { type: Type.STRING, nullable: true },
                      experiment: { type: Type.STRING, nullable: true },
                      failure: { type: Type.STRING, nullable: true },
                      question: { type: Type.STRING, nullable: true },
                      solution: { type: Type.STRING, nullable: true },
                      result: { type: Type.STRING, nullable: true },
                      reality: { type: Type.STRING, nullable: true },
                    }
                  }
                }
              }
            }
          }
        },
        resultTable: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              item: { type: Type.STRING },
              before: { type: Type.STRING },
              after: { type: Type.STRING },
              diff: { type: Type.STRING }
            }
          }
        },
        essay: {
          type: Type.OBJECT,
          properties: {
            title: { type: Type.STRING },
            intro: { type: Type.STRING },
            body: { type: Type.STRING }
          }
        },
        downloads: {
            type: Type.ARRAY,
            items: {
                type: Type.OBJECT,
                properties: {
                    title: { type: Type.STRING },
                    description: { type: Type.STRING },
                    type: { type: Type.STRING, enum: ["pdf", "excel", "doc"] },
                    triggerType: { type: Type.STRING, enum: ["ad", "link"] },
                    triggerUrl: { type: Type.STRING, nullable: true }
                }
            }
        }
      },
      required: ["id", "type", "tags", "story", "essay"]
    };

    const prompt = `
      Create a "Dry Author" style life simulation template.

      ${contextDescription}

      ${input.isDomestic ? domesticInstruction : internationalInstruction}

      CRITICAL INSTRUCTIONS:
      1. **Tone**: Cynical, Analytical, Hyper-Realistic. Highlight "Hidden Costs" (Mental & Financial).
      2. **Variables**: The output MUST be a generic template using placeholders: {age}, {job}, {start}, {goal}, {months}, {currency}, {family}.
         - Even if the user input specific values, replace them with placeholders in the template text where appropriate so it can be reused.
         - However, keep specific local facts hardcoded (e.g. "Gangnam traffic", "Jeju wind", "Vancouver rain").

      3. **Structure**:
         - Story: 4 Stages (Dream -> Reality Check -> Crisis -> Adaptation/Failure).
         - Essay: A sharp critique of the user's desire to move to ${input.goal}.
         - Result Table: 4 Key metrics comparing Start vs Goal.
         - Downloads: 2 specific tools (PDF/Excel) relevant to the move type.
    `;

    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash-preview',
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: schema,
        temperature: 0.7, 
      }
    });

    const jsonText = response.text;
    if (!jsonText) return null;

    const generatedTemplate = JSON.parse(jsonText) as ScenarioTemplate;

    // Post-processing: Ensure tags and ID are robust
    const additionalTags = [
        input.goal.toLowerCase(), 
        input.moveType?.toLowerCase() || 'general', 
        input.isDomestic ? 'domestic' : 'international',
        input.family?.includes('kid') || input.family?.includes('child') ? 'family' : 'single'
    ];

    generatedTemplate.tags = [...new Set([...generatedTemplate.tags, ...additionalTags])];

    // Ensure unique ID for persistence
    const typePrefix = input.isDomestic ? 'domestic' : 'global';
    generatedTemplate.id = `ai_${typePrefix}_${Date.now()}_${input.goal.replace(/\s/g, '').toLowerCase()}`;

    return generatedTemplate;

  } catch (error) {
    console.error("Gemini AI Generation Failed:", error);
    return null;
  }
};

import React, { useState, useEffect } from 'react';
import { GlassCard } from './GlassCard';
import { ScenarioDB, ScenarioTemplate, DownloadableResource, UserInput } from '../types';
import { DEFAULT_TEMPLATES } from '../constants';
import { generateBatchRandomSamples, generateNewScenarioTemplate, suggestNewScenarioTopics, validateSystemData } from '../aiService';

interface AdminDashboardProps {
  db: ScenarioDB;
  onUpdateDb: (newDb: ScenarioDB) => void;
  templates: ScenarioTemplate[];
  onUpdateTemplates: (newTemplates: ScenarioTemplate[]) => void;
  onClose: () => void;
}

const RandomSampleEditor: React.FC<{db: ScenarioDB, onUpdateDb: (newDb: ScenarioDB) => void, templates: ScenarioTemplate[]}> = ({ db, onUpdateDb, templates }) => {
    const [samples, setSamples] = useState<Partial<UserInput>[]>(db.randomSamples || []);

    // DB가 외부에서 변경되었을 때 동기화
    useEffect(() => {
        if(db.randomSamples) {
            setSamples(db.randomSamples);
        }
    }, [db.randomSamples]);

    const handleUpdate = (index: number, field: keyof UserInput, value: string | number | boolean) => {
        const newSamples = [...samples];
        newSamples[index] = { ...newSamples[index], [field]: value };

        // AI 모드가 켜지면 템플릿 ID는 비움 (충돌 방지)
        if (field === 'useAI' && value === true) {
            newSamples[index].forcedTemplateId = '';
        }

        setSamples(newSamples);
    };

    const handleSave = () => {
        // Force update the parent DB state
        const updatedDb = { ...db, randomSamples: samples };
        onUpdateDb(updatedDb);

        // Ensure LocalStorage is updated immediately (backup mechanism)
        localStorage.setItem('app_db', JSON.stringify(updatedDb));

        // 저장 피드백 애니메이션
        const btn = document.getElementById('save-samples-btn');
        if(btn) {
            const originalText = btn.innerHTML;
            btn.innerHTML = "✅ 저장 완료!";
            btn.classList.remove('bg-emerald-600', 'hover:bg-emerald-500');
            btn.classList.add('bg-green-500');
            setTimeout(() => {
                btn.innerHTML = originalText;
                btn.classList.add('bg-emerald-600', 'hover:bg-emerald-500');
                btn.classList.remove('bg-green-500');
            }, 2000);
        }
    };

    const handleAdd = () => {
        setSamples([...samples, { age: '30', job: '직장인', start: '서울', goal: '미국', months: 24, forcedTemplateId: '', isDomestic: false, useAI: false }]);
    };

    const handleRemove = (index: number) => {
        if (confirm('이 예시를 삭제하시겠습니까?')) {
            const newSamples = [...samples];
            newSamples.splice(index, 1);
            setSamples(newSamples);
        }
    };

    return (
        <div className="h-full overflow-y-auto p-6 md:p-8 space-y-6 pb-20">
            <GlassCard className="p-6 border-l-4 border-l-purple-500">
                 <div className="flex justify-between items-center mb-6">
                    <div>
                        <h3 className="text-xl font-bold flex items-center gap-2">
                           🔀 랜덤 예시 & 결과 매칭
                           <span className="text-xs bg-purple-500/20 text-purple-300 px-2 py-1 rounded-full">{samples.length}개</span>
                        </h3>
                        <p className="text-xs text-gray-400 mt-1">입력값과 출력될 시나리오 방식을 설정하고 저장하세요.</p>
                    </div>
                    <button 
                        id="save-samples-btn"
                        onClick={handleSave} 
                        className="px-6 py-2.5 bg-emerald-600 hover:bg-emerald-500 rounded-xl font-bold text-xs text-white shadow-lg transition-all flex items-center gap-2"
                    >
                        <span>💾</span> 변경사항 저장
                    </button>
                 </div>

                 <div className="grid gap-4">
                    {samples.map((sample, index) => (
                         <div key={index} className="bg-white/5 border border-white/10 rounded-xl p-4 relative group hover:border-purple-500/30 transition-colors">
                            <button 
                                onClick={() => handleRemove(index)} 
                                className="absolute -top-2 -right-2 bg-red-500 text-white rounded-full w-6 h-6 flex items-center justify-center shadow-lg opacity-0 group-hover:opacity-100 transition-opacity z-10 hover:bg-red-600"
                                title="삭제"
                            >
                                ×
                            </button>

                            <div className="grid grid-cols-2 md:grid-cols-12 gap-3 items-end">
                                {/* Input Fields Group */}
                                <div className="col-span-1 md:col-span-1">
                                    <label className="block text-[10px] text-gray-500 mb-1 uppercase tracking-wider">나이</label>
                                    <input 
                                        value={sample.age || ''} 
                                        onChange={(e) => handleUpdate(index, 'age', e.target.value)} 
                                        className="w-full bg-black/30 p-2.5 rounded-lg text-sm border border-transparent focus:border-purple-500 focus:outline-none text-center"
                                        placeholder="00"
                                    />
                                </div>
                                <div className="col-span-1 md:col-span-2">
                                    <label className="block text-[10px] text-gray-500 mb-1 uppercase tracking-wider">직업</label>
                                    <input 
                                        value={sample.job || ''} 
                                        onChange={(e) => handleUpdate(index, 'job', e.target.value)} 
                                        className="w-full bg-black/30 p-2.5 rounded-lg text-sm border border-transparent focus:border-purple-500 focus:outline-none"
                                        placeholder="직업 입력"
                                    />
                                </div>
                                <div className="col-span-1 md:col-span-1">
                                    <label className="block text-[10px] text-gray-500 mb-1 uppercase tracking-wider">출발</label>
                                    <input 
                                        value={sample.start || ''} 
                                        onChange={(e) => handleUpdate(index, 'start', e.target.value)} 
                                        className="w-full bg-black/30 p-2.5 rounded-lg text-sm border border-transparent focus:border-purple-500 focus:outline-none"
                                        placeholder="출발지"
                                    />
                                </div>
                                <div className="col-span-1 md:col-span-1">
                                    <label className="block text-[10px] text-gray-500 mb-1 uppercase tracking-wider">도착</label>
                                    <input 
                                        value={sample.goal || ''} 
                                        onChange={(e) => handleUpdate(index, 'goal', e.target.value)} 
                                        className="w-full bg-black/30 p-2.5 rounded-lg text-sm border border-transparent focus:border-purple-500 focus:outline-none font-bold text-emerald-400"
                                        placeholder="도착지"
                                    />
                                </div>
                                <div className="col-span-2 md:col-span-1">
                                    <label className="block text-[10px] text-gray-500 mb-1 uppercase tracking-wider">이동타입</label>
                                    <select 
                                        value={sample.isDomestic ? 'domestic' : 'intl'} 
                                        onChange={(e) => handleUpdate(index, 'isDomestic', e.target.value === 'domestic')} 
                                        className="w-full bg-black/30 p-2.5 rounded-lg text-sm border border-transparent focus:border-purple-500 focus:outline-none"
                                    >
                                        <option value="intl">해외</option>
                                        <option value="domestic">국내</option>
                                    </select>
                                </div>

                                {/* Control Group: AI vs Existing Template */}
                                <div className={`col-span-2 md:col-span-6 p-2 rounded-lg border transition-all ${sample.useAI ? 'bg-emerald-900/30 border-emerald-500' : 'bg-white/5 border-white/10'}`}>
                                    <div className="flex items-center gap-2 mb-1">
                                        <input 
                                            type="checkbox"
                                            id={`use-ai-${index}`}
                                            checked={!!sample.useAI}
                                            onChange={(e) => handleUpdate(index, 'useAI', e.target.checked)}
                                            className="w-4 h-4 text-emerald-600 bg-gray-700 border-gray-600 rounded focus:ring-emerald-500 focus:ring-2"
                                        />
                                        <label htmlFor={`use-ai-${index}`} className={`text-xs font-bold cursor-pointer select-none ${sample.useAI ? 'text-emerald-400' : 'text-gray-400'}`}>
                                            🤖 AI 신규 생성 모드
                                        </label>
                                    </div>

                                    {!sample.useAI ? (
                                        <select
                                            value={sample.forcedTemplateId || ''}
                                            onChange={(e) => handleUpdate(index, 'forcedTemplateId', e.target.value)}
                                            className="w-full bg-black/50 p-2 rounded text-xs text-white border border-white/10 focus:border-indigo-500 focus:outline-none"
                                        >
                                            <option value="">(기본: 태그 매칭)</option>
                                            {templates.map(t => (
                                                <option key={t.id} value={t.id}>
                                                    {t.id.startsWith('ai_') ? '🤖 ' : '📄 '}
                                                    {t.id}
                                                </option>
                                            ))}
                                        </select>
                                    ) : (
                                        <div className="text-[10px] text-emerald-200/80 px-1 py-1">
                                            실행 시 AI가 새 시나리오를 생성하고 <strong className="text-emerald-400 underline decoration-emerald-500">영구 저장</strong>합니다.
                                        </div>
                                    )}
                                </div>
                            </div>
                         </div>
                    ))}

                    <button 
                        onClick={handleAdd} 
                        className="w-full py-4 bg-white/5 hover:bg-white/10 border border-dashed border-white/20 rounded-xl text-sm font-bold text-gray-400 hover:text-white transition-colors flex items-center justify-center gap-2 group"
                    >
                        <span className="group-hover:scale-125 transition-transform">➕</span> 새 랜덤 시나리오 추가
                    </button>
                 </div>
            </GlassCard>
        </div>
    );
};

export const AdminDashboard: React.FC<AdminDashboardProps> = ({ 
  db, 
  onUpdateDb, 
  templates, 
  onUpdateTemplates, 
  onClose 
}) => {
  const [activeTab, setActiveTab] = useState<'control' | 'templates' | 'samples'>('control');
  const [logs, setLogs] = useState<string[]>([]);

  // AI Maintenance State
  const [aiMaintenance, setAiMaintenance] = useState({
      updateTemplates: false,
      updateSamples: false,
      validate: false
  });
  const [batchSize, setBatchSize] = useState<number>(3); // Default batch size
  const [aiRunning, setAiRunning] = useState(false);

  // Template Editing State
  const [selectedTemplateId, setSelectedTemplateId] = useState<string | null>(null);
  const [jsonInput, setJsonInput] = useState<string>('');
  const [isEditing, setIsEditing] = useState(false);
  const [editMode, setEditMode] = useState<'json' | 'easy'>('easy');

  // Temporary state for Easy Editor
  const [easyData, setEasyData] = useState<ScenarioTemplate | null>(null);

  const addLog = (msg: string) => {
    const timestamp = new Date().toLocaleTimeString();
    setLogs(prev => [`[${timestamp}] ${msg}`, ...prev]);
  };

  const runAIMaintenance = async () => {
    if(!process.env.API_KEY) {
        alert("API Key is missing!");
        return;
    }

    setAiRunning(true);
    addLog(`🚀 AI 자동 유지보수 시작 (Batch Size: ${batchSize})...`);

    try {
        // 1. Validation Logic
        if (aiMaintenance.validate) {
            addLog("🔍 데이터 정합성 검사 중...");
            const report = await validateSystemData(db, templates);
            report.forEach(r => addLog(`📋 [리포트] ${r}`));
        }

        // 2. Sample Updates
        if (aiMaintenance.updateSamples) {
            addLog(`🎲 ${batchSize}개의 새로운 랜덤 예시 생성 중...`);
            const newSamples = await generateBatchRandomSamples(batchSize); 
            if (newSamples.length > 0) {
                // Merge and save
                // Use functional update for latest state, although here we passed db via props
                // Since this component might be mounted for a while, it's safer to trust the prop + local accumulation if needed
                // But for now, just prop.db is fine as parent updates trigger re-render

                // Note: We need to respect the *current* db in the parent, but we only have props here.
                // Assuming parent updates props on call.
                const updatedSamples = [...newSamples, ...(db.randomSamples || [])].slice(0, 30); // increased limit
                onUpdateDb({ ...db, randomSamples: updatedSamples });
                addLog(`✅ 랜덤 예시 ${newSamples.length}개 추가 및 저장 완료`);
            } else {
                addLog("⚠️ 랜덤 예시 생성 실패 (API 응답 없음)");
            }
        }

        // 3. Template Expansion
        if (aiMaintenance.updateTemplates) {
            addLog(`🧠 부족한 시나리오 주제 ${batchSize}개 분석 중...`);
            const allTags = templates.flatMap(t => t.tags);
            const topicIdeas = await suggestNewScenarioTopics(allTags, batchSize);

            if (topicIdeas.length === 0) {
                 addLog("⚠️ 새로운 주제를 발견하지 못했습니다.");
            } else {
                addLog(`💡 발견된 주제: ${topicIdeas.map(t => t.goal).join(', ')}`);

                // Process sequentially to update UI
                let completedCount = 0;
                let currentTemplates = [...templates]; // Local copy to accumulate during loop

                for (const idea of topicIdeas) {
                    addLog(`[${completedCount + 1}/${topicIdeas.length}] ✍️ 템플릿 생성 중: ${idea.goal}...`);
                    const newTemplate = await generateNewScenarioTemplate(idea as UserInput);

                    if (newTemplate) {
                        currentTemplates = [newTemplate, ...currentTemplates];
                        onUpdateTemplates(currentTemplates); // Save immediately
                        addLog(`✨ 템플릿 등록 완료: ${newTemplate.id}`);
                    }
                    completedCount++;
                }
            }
        }

        addLog("🏁 모든 AI 작업이 성공적으로 완료되었습니다.");

    } catch (e) {
        addLog(`❌ 치명적 오류 발생: ${e}`);
    } finally {
        setAiRunning(false);
    }
  };

  const handleSelectTemplate = (t: ScenarioTemplate) => {
    setSelectedTemplateId(t.id);
    const jsonStr = JSON.stringify(t, null, 2);
    setJsonInput(jsonStr);
    setEasyData(JSON.parse(jsonStr)); // Deep copy
    setIsEditing(true);
  };

  const handleCreateNew = () => {
    const newTemplate = { ...DEFAULT_TEMPLATES[0], id: `custom_${Date.now()}`, tags: ['new'] };
    setSelectedTemplateId(null);
    const jsonStr = JSON.stringify(newTemplate, null, 2);
    setJsonInput(jsonStr);
    setEasyData(newTemplate);
    setIsEditing(true);
  };

  const handleSaveTemplate = () => {
    try {
      const payload = editMode === 'easy' && easyData ? easyData : JSON.parse(jsonInput);

      if (!payload.id || !payload.story) throw new Error("Invalid Format");

      const exists = templates.find(t => t.id === payload.id);
      let newTemplates;

      if (exists) {
        newTemplates = templates.map(t => t.id === payload.id ? payload : t);
        addLog(`📝 템플릿 수정됨: ${payload.id}`);
      } else {
        newTemplates = [payload, ...templates];
        addLog(`✨ 새 템플릿 추가됨: ${payload.id}`);
      }

      onUpdateTemplates(newTemplates);

      setJsonInput(JSON.stringify(payload, null, 2));
      setEasyData(payload);

      alert("저장되었습니다.");
    } catch (e) {
      alert("JSON 형식이 올바르지 않습니다.");
    }
  };

  const handleDeleteTemplate = (id: string) => {
    if(confirm("정말 삭제하시겠습니까?")) {
        const newTemplates = templates.filter(t => t.id !== id);
        onUpdateTemplates(newTemplates);
        setIsEditing(false);
        addLog(`🗑 템플릿 삭제됨: ${id}`);
    }
  }

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/80 backdrop-blur-md p-4 animate-fade-in">
      <GlassCard className="w-full max-w-6xl h-[90vh] flex flex-col bg-[#111827] border-white/20 shadow-2xl overflow-hidden">
        {/* Header */}
        <div className="p-6 border-b border-white/10 flex justify-between items-center bg-black/20">
          <div>
             <h2 className="text-2xl font-black text-white flex items-center gap-2">
                <span className="text-3xl">⚙️</span> SYSTEM ADMIN
             </h2>
             <p className="text-xs text-emerald-400 font-mono mt-1">
                Connected: {new Date().toLocaleDateString()}
             </p>
          </div>
          <button onClick={onClose} className="w-10 h-10 rounded-full bg-white/10 hover:bg-white/20 flex items-center justify-center text-white transition-colors">
            ✕
          </button>
        </div>

        {/* Tabs */}
        <div className="flex border-b border-white/10 bg-black/10">
           <button 
             onClick={() => setActiveTab('control')}
             className={`px-8 py-4 text-sm font-bold transition-colors ${activeTab === 'control' ? 'bg-emerald-600/20 text-emerald-400 border-b-2 border-emerald-500' : 'text-gray-400 hover:text-white'}`}
           >
             📡 모니터링
           </button>
           <button 
             onClick={() => setActiveTab('templates')}
             className={`px-8 py-4 text-sm font-bold transition-colors ${activeTab === 'templates' ? 'bg-emerald-600/20 text-emerald-400 border-b-2 border-emerald-500' : 'text-gray-400 hover:text-white'}`}
           >
             📄 템플릿 관리 ({templates.length})
           </button>
           <button 
             onClick={() => setActiveTab('samples')}
             className={`px-8 py-4 text-sm font-bold transition-colors ${activeTab === 'samples' ? 'bg-emerald-600/20 text-emerald-400 border-b-2 border-emerald-500' : 'text-gray-400 hover:text-white'}`}
           >
             🔀 랜덤 예시 설정
           </button>
        </div>

        {/* Content */}
        <div className="flex-1 overflow-hidden bg-[#0f172a]">

           {/* TAB 1: CONTROL */}
           {activeTab === 'control' && (
             <div className="p-8 h-full overflow-y-auto space-y-8">
                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                    {/* Status & Maintenance Panel */}
                    <GlassCard className="p-6 border-l-4 border-l-emerald-500">
                        <h3 className="text-gray-400 text-xs font-bold uppercase tracking-wider mb-4 flex items-center gap-2">
                           🤖 AI Auto-Maintenance
                        </h3>

                        <div className="space-y-4 mb-6">
                            <div className="flex justify-between items-center p-3 bg-white/5 rounded-lg border border-white/5">
                                <span>총 템플릿</span>
                                <span className="text-white font-bold">{templates.length} Types</span>
                            </div>
                            <div className="flex justify-between items-center p-3 bg-white/5 rounded-lg border border-white/5">
                                <span>랜덤 예시</span>
                                <span className="text-white font-bold">{db.randomSamples?.length || 0} Sets</span>
                            </div>
                        </div>

                        <div className="bg-black/30 p-4 rounded-xl space-y-3 mb-4">
                            <p className="text-[10px] text-gray-500 uppercase font-bold mb-2">Maintenance Tasks</p>

                            <label className="flex items-center gap-3 cursor-pointer p-2 hover:bg-white/5 rounded-lg transition-colors">
                                <input 
                                    type="checkbox" 
                                    checked={aiMaintenance.updateTemplates}
                                    onChange={e => setAiMaintenance({...aiMaintenance, updateTemplates: e.target.checked})}
                                    className="w-4 h-4 rounded text-emerald-500 bg-gray-800 border-gray-600 focus:ring-emerald-500" 
                                />
                                <span className="text-sm text-gray-300">🆕 템플릿 추가 작성 (누락된 주제 분석)</span>
                            </label>

                            <label className="flex items-center gap-3 cursor-pointer p-2 hover:bg-white/5 rounded-lg transition-colors">
                                <input 
                                    type="checkbox" 
                                    checked={aiMaintenance.updateSamples}
                                    onChange={e => setAiMaintenance({...aiMaintenance, updateSamples: e.target.checked})}
                                    className="w-4 h-4 rounded text-emerald-500 bg-gray-800 border-gray-600 focus:ring-emerald-500" 
                                />
                                <span className="text-sm text-gray-300">🎲 랜덤 예시 설정 업데이트 (최신 트렌드)</span>
                            </label>

                            <label className="flex items-center gap-3 cursor-pointer p-2 hover:bg-white/5 rounded-lg transition-colors">
                                <input 
                                    type="checkbox" 
                                    checked={aiMaintenance.validate}
                                    onChange={e => setAiMaintenance({...aiMaintenance, validate: e.target.checked})}
                                    className="w-4 h-4 rounded text-emerald-500 bg-gray-800 border-gray-600 focus:ring-emerald-500" 
                                />
                                <span className="text-sm text-gray-300">🩺 전체 데이터 정합성 검증 (오류 체크)</span>
                            </label>

                            {/* Batch Size Selector */}
                            <div className="pt-2 border-t border-white/10 mt-2">
                                <div className="text-[10px] text-gray-500 mb-2">작업 개수 (Batch Size)</div>
                                <div className="flex gap-2">
                                    {[3, 5, 10].map(size => (
                                        <button 
                                            key={size}
                                            onClick={() => setBatchSize(size)}
                                            className={`flex-1 py-1.5 rounded-lg text-xs font-bold transition-all ${batchSize === size ? 'bg-emerald-600 text-white shadow' : 'bg-white/5 text-gray-400 hover:bg-white/10'}`}
                                        >
                                            {size}개
                                        </button>
                                    ))}
                                </div>
                            </div>
                        </div>

                        <button 
                          onClick={runAIMaintenance}
                          disabled={aiRunning || (!aiMaintenance.updateTemplates && !aiMaintenance.updateSamples && !aiMaintenance.validate)}
                          className={`w-full py-3.5 rounded-xl font-bold text-white shadow-lg transition-all flex items-center justify-center gap-2
                             ${aiRunning ? 'bg-gray-700 cursor-not-allowed' : 'bg-gradient-to-r from-emerald-600 to-teal-600 hover:from-emerald-500 hover:to-teal-500 shadow-emerald-900/30'}
                          `}
                        >
                            {aiRunning ? (
                                <>
                                   <div className="w-4 h-4 border-2 border-white/30 border-t-white rounded-full animate-spin"></div>
                                   {batchSize}개 생성 및 업데이트 중...
                                </>
                            ) : (
                                <>⚡ AI 실행 및 업데이트</>
                            )}
                        </button>
                    </GlassCard>

                    {/* Logs Panel */}
                    <GlassCard className="p-6 flex flex-col">
                        <h3 className="text-gray-400 text-xs font-bold uppercase tracking-wider mb-4">System Activity Logs</h3>
                        <div className="flex-1 bg-black/40 rounded-xl p-4 font-mono text-xs text-green-400 overflow-y-auto border border-white/5 shadow-inner">
                            {logs.length === 0 ? (
                                <div className="h-full flex flex-col items-center justify-center text-gray-600 opacity-50 gap-2">
                                    <span className="text-2xl">📡</span>
                                    <span>Waiting for system events...</span>
                                </div>
                            ) : (
                                logs.map((log, i) => (
                                    <div key={i} className="mb-1.5 border-b border-white/5 pb-1.5 break-all leading-relaxed animate-fade-in">
                                        {log.includes('❌') || log.includes('⚠️') ? <span className="text-red-400">{log}</span> : 
                                         log.includes('✨') ? <span className="text-yellow-300">{log}</span> :
                                         log}
                                    </div>
                                ))
                            )}
                        </div>
                        <div className="mt-2 text-right">
                           <button onClick={() => setLogs([])} className="text-[10px] text-gray-500 hover:text-white underline">Clear Logs</button>
                        </div>
                    </GlassCard>
                </div>
             </div>
           )}

           {/* TAB 2: TEMPLATES */}
           {activeTab === 'templates' && (
             <div className="h-full flex flex-col md:flex-row">
                {/* List */}
                <div className="w-full md:w-1/3 border-r border-white/10 overflow-y-auto p-4 space-y-2 bg-[#1e293b]/50">
                    <button 
                        onClick={handleCreateNew}
                        className="w-full py-3 bg-indigo-600 hover:bg-indigo-500 rounded-xl font-bold text-white mb-4 shadow-lg transition-colors"
                    >
                        + 새 템플릿 만들기
                    </button>
                    {templates.map(t => (
                        <div 
                           key={t.id} 
                           onClick={() => handleSelectTemplate(t)}
                           className={`p-4 rounded-xl cursor-pointer transition-all border ${selectedTemplateId === t.id ? 'bg-emerald-600/20 border-emerald-500 text-white' : 'bg-white/5 border-white/5 text-gray-400 hover:bg-white/10'}`}
                        >
                            <div className="flex justify-between items-center mb-1">
                                <span className="font-bold text-xs bg-black/30 px-2 py-1 rounded text-gray-300">{t.id}</span>
                                <span className="text-[10px] uppercase">{t.type}</span>
                            </div>
                            <div className="text-sm font-bold truncate">{t.story.titleTemplate}</div>
                            <div className="flex gap-1 mt-2 flex-wrap">
                                {t.tags.map(tag => (
                                    <span key={tag} className="text-[9px] px-1.5 py-0.5 bg-white/10 rounded text-gray-400">#{tag}</span>
                                ))}
                            </div>
                        </div>
                    ))}
                </div>

                {/* Editor */}
                <div className="w-full md:w-2/3 p-6 overflow-y-auto bg-[#0f172a]">
                    {isEditing ? (
                        <div className="space-y-4 h-full flex flex-col">
                             <div className="flex justify-between items-center">
                                 <h3 className="text-xl font-bold text-white">Edit Template</h3>
                                 <div className="flex gap-2 bg-black/30 p-1 rounded-lg">
                                     <button 
                                        onClick={() => setEditMode('easy')} 
                                        className={`px-3 py-1 text-xs rounded-md font-bold transition-colors ${editMode === 'easy' ? 'bg-emerald-500 text-white' : 'text-gray-400'}`}
                                     >
                                        EASY
                                     </button>
                                     <button 
                                        onClick={() => setEditMode('json')} 
                                        className={`px-3 py-1 text-xs rounded-md font-bold transition-colors ${editMode === 'json' ? 'bg-emerald-500 text-white' : 'text-gray-400'}`}
                                     >
                                        JSON
                                     </button>
                                 </div>
                             </div>

                             <div className="flex-1 overflow-hidden relative">
                                {editMode === 'json' ? (
                                    <textarea
                                        value={jsonInput}
                                        onChange={(e) => setJsonInput(e.target.value)}
                                        className="w-full h-full bg-[#1e1e1e] text-green-400 font-mono text-xs p-4 rounded-xl border border-white/10 focus:outline-none focus:border-emerald-500 resize-none"
                                        spellCheck={false}
                                    />
                                ) : (
                                    <div className="h-full overflow-y-auto space-y-6 pr-2">
                                        {easyData && (
                                            <>
                                                <div className="grid grid-cols-2 gap-4">
                                                    <div>
                                                        <label className="text-xs text-gray-500 block mb-1">ID</label>
                                                        <input 
                                                            value={easyData.id}
                                                            onChange={(e) => setEasyData({...easyData, id: e.target.value})}
                                                            className="w-full bg-black/30 p-2 rounded text-white border border-white/10"
                                                        />
                                                    </div>
                                                    <div>
                                                        <label className="text-xs text-gray-500 block mb-1">Tags (comma separated)</label>
                                                        <input 
                                                            value={easyData.tags.join(', ')}
                                                            onChange={(e) => setEasyData({...easyData, tags: e.target.value.split(',').map(s => s.trim())})}
                                                            className="w-full bg-black/30 p-2 rounded text-white border border-white/10"
                                                        />
                                                    </div>
                                                </div>
                                                <div>
                                                    <label className="text-xs text-gray-500 block mb-1">Title Template</label>
                                                    <input 
                                                        value={easyData.story.titleTemplate}
                                                        onChange={(e) => setEasyData({...easyData, story: {...easyData.story, titleTemplate: e.target.value}})}
                                                        className="w-full bg-black/30 p-2 rounded text-white border border-white/10"
                                                    />
                                                </div>
