import { UserInput, StoryResult, ScenarioDB, ScenarioData, ScenarioTemplate, ComparisonRow, EssayData, DownloadableResource } from './types';
import { GlassCard } from './components/GlassCard';
import { generateNewScenarioTemplate, parseUserPrompt } from './aiService';

function App() {
  const [db, setDb] = useState<ScenarioDB>(() => {
    const saved = localStorage.getItem('app_db');
    return saved ? JSON.parse(saved) : INITIAL_DB;
  });
  const [templates, setTemplates] = useState<ScenarioTemplate[]>(() => {
    const saved = localStorage.getItem('app_templates');
    return saved ? JSON.parse(saved) : DEFAULT_TEMPLATES;
  });

  const [isAdmin, setIsAdmin] = useState(false);
  const [showAdminLogin, setShowAdminLogin] = useState(false);
  const [adminPassword, setAdminPassword] = useState('');

  const [input, setInput] = useState<UserInput>({
    age: '',
    job: '',
    start: '',
    goal: '',
    months: 24,
    country: '',
    forcedTemplateId: '',
    family: '',
    moveType: '',
    assets: '',
    useAI: false
  });
  const [result, setResult] = useState<StoryResult | null>(null);
  const [loading, setLoading] = useState(false);
  const [aiGenerating, setAiGenerating] = useState(false);
  const [aiAnalyzing, setAiAnalyzing] = useState(false);
  const [toastMessage, setToastMessage] = useState<string | null>(null);

  useEffect(() => {
    if (window.location.hash === '#admin') setShowAdminLogin(true);
  }, []);

  // Persist DB and Templates to LocalStorage
  useEffect(() => {
    localStorage.setItem('app_db', JSON.stringify(db));
  }, [db]);
  useEffect(() => {
    localStorage.setItem('app_templates', JSON.stringify(templates));
  }, [templates]);

  const handleAdminLogin = () => {
    if (adminPassword === '1234') {
      setIsAdmin(true);
      setShowAdminLogin(false);
      setToastMessage("🔓 관리자 모드로 접속했습니다.");
    } else {
      alert("비밀번호가 올바르지 않습니다.");
    }
  };

  const handleInputChange = (field: keyof UserInput, value: string | number) => {
    setInput(prev => ({ ...prev, [field]: value }));
  };

  const generateStory = useCallback(async (generationInput: UserInput) => {
    setLoading(true);
    setResult(null); 
    setAiGenerating(false);

    // 1. Prepare Variables
    const age = generationInput.age || '미지정';
    const job = generationInput.job || '미지정';
    const start = generationInput.start || '미지정';
    const goal = generationInput.goal || '미지정';
    const months = generationInput.months || 24;
    const countryKey = generationInput.country || detectCountry(goal);
    const config = GLOBAL_100[countryKey] || GLOBAL_100['default'];
    const isDefaultScenario = countryKey === 'default' && !generationInput.forcedTemplateId && !generationInput.useAI;

    // 2. Select Template Logic
    let selectedTemplate: ScenarioTemplate | null = null;
    let usedAI = false;

    // CASE A: Explicit AI Generation Mode (from Admin or specific trigger)
    // "이 버튼이 활성화되면 만들어주는 것을 너가 저장하면 되고"
    if (generationInput.useAI && process.env.API_KEY) {
        setAiGenerating(true);
        try {
           const aiTemplate = await generateNewScenarioTemplate(generationInput);
           if (aiTemplate) {
              selectedTemplate = aiTemplate;
              // Save the new template for permanent storage
              setTemplates(prev => [aiTemplate, ...prev]);
              setToastMessage("🤖 AI가 생성한 새 템플릿이 영구 저장되었습니다.");
              usedAI = true;
           }
        } catch (e) {
           console.error("Forced AI Generation failed", e);
           setToastMessage("❌ AI 생성 실패. 기존 템플릿을 사용합니다.");
        }
        setAiGenerating(false);
    }

    // CASE B: Forced Template ID (Pre-linked in Admin)
    // "이 버튼을 안체크되면 그냥 템플릿에서 기존것을 불러오는 것"
    if (!selectedTemplate && generationInput.forcedTemplateId) {
      selectedTemplate = templates.find(t => t.id === generationInput.forcedTemplateId) || null;
    }

    // CASE C: Intelligent Matching (Fallback)
    if (!selectedTemplate) {
        const jobLower = job.toLowerCase();
        const goalLower = goal.toLowerCase();

        // Find by tags
        selectedTemplate = templates.find(t => {
             const hasGoal = t.tags.some(tag => goalLower.includes(tag));
             const hasFamily = generationInput.family ? t.tags.some(tag => generationInput.family?.toLowerCase().includes(tag)) : true;
             return hasGoal && hasFamily;
        }) || null;

        // Fallback: Just goal matching
        if (!selectedTemplate) {
            selectedTemplate = templates.find(t => t.tags.some(tag => goalLower.includes(tag))) || null;
        }

        // Final Fallback: AI (if not explicitly disabled and API key exists and goal is valid)
        // This handles the user typing in the main input form (not admin samples)
        if (!selectedTemplate && process.env.API_KEY && goal !== '미지정') {
           setAiGenerating(true);
           try {
              const aiTemplate = await generateNewScenarioTemplate(generationInput);
              if (aiTemplate) {
                 selectedTemplate = aiTemplate;
                 setTemplates(prev => [aiTemplate, ...prev]);
                 setToastMessage("🤖 새로운 패턴 발견! AI가 분석하여 저장했습니다.");
                 usedAI = true;
              }
           } catch (e) { console.error(e); }
           setAiGenerating(false);
        }
    }

    // Final Safe Fallback
    if (!selectedTemplate) {
      selectedTemplate = templates.find(t => t.id === 'template_default') || templates[0];
    }

    // 3. Inject Variables
    const inject = (text?: string) => {
      if (!text) return "";
      return text
        .replace(/{age}/g, age)
        .replace(/{job}/g, job)
        .replace(/{start}/g, start)
        .replace(/{goal}/g, goal)
        .replace(/{months}/g, months.toString())
        .replace(/{currency}/g, config.currency)
        .replace(/{prop}/g, config.prop)
        .replace(/{bank}/g, config.bank)
        .replace(/{visa}/g, config.visaName)
        .replace(/{family}/g, generationInput.family || '가족')
        .replace(/{moveType}/g, generationInput.moveType || '이동');
    };

    const randInt = (min: number, max: number) => Math.floor(Math.random() * (max - min + 1)) + min;

    // 4. Generate Result Table
    let resultTable: ComparisonRow[] = [];

    if (selectedTemplate.resultTable) {
      resultTable = selectedTemplate.resultTable.map(row => ({
        item: inject(row.item),
        before: inject(row.before),
        after: inject(row.after),
        diff: inject(row.diff)
      }));
    } else {
      resultTable = [
          { item: '월 생활비', before: `${config.currency} 4,500`, after: `${config.currency} 3,200`, diff: `-1,300` },
          { item: '자산', before: '유동성 부족', after: '환차익 발생', diff: `+${randInt(1, 15)}%` },
          { item: '의료비', before: '보험 적용', after: '사립 병원', diff: '+200%' },
          { item: '순 저축', before: '100', after: '350', diff: '+250' }
      ];
    }

    // 5. Generate Essay
    const defaultEssay: EssayData = {
      title: `${goal}의 현실: 숫자가 말해주지 않는 것들`,
      intro: `${start}를 떠나 ${goal}로 향하는 당신의 발걸음은 가볍겠지만, 현실의 무게는 결코 가볍지 않습니다.`,
      body: "우리는 종종 장소만 바뀌면 삶이 바뀔 것이라 착각합니다. 하지만 당신이 가져가는 것은 짐가방뿐만이 아닙니다. 당신의 불안과 습관도 국경을 넘습니다."
    };

    const essayData: EssayData = selectedTemplate.essay ? {
      title: inject(selectedTemplate.essay.title),
      intro: inject(selectedTemplate.essay.intro),
      body: inject(selectedTemplate.essay.body)
    } : defaultEssay;

    // 6. Generate Downloads
    const downloads: DownloadableResource[] = selectedTemplate.downloads ? selectedTemplate.downloads.map(d => ({
      ...d,
      title: inject(d.title),
      description: inject(d.description),
      triggerUrl: inject(d.triggerUrl)
    })) : [];

    const scenarioData: ScenarioData = {
        success: randInt(40, 95),
        salary: config.avgSalary,
        visa: config.visaName,
        living: randInt(100, 450), 
        story: {
            header: inject(selectedTemplate.story.titleTemplate),
            subHeader: inject(selectedTemplate.story.subTemplate),
            stages: selectedTemplate.story.stages.map(s => ({
              label: s.label,
              title: inject(s.title),
              situation: inject(s.content.situation),
              thought: inject(s.content.thought),
              action: inject(s.content.action),
              experiment: inject(s.content.experiment),
              failure: inject(s.content.failure),
              question: inject(s.content.question),
              solution: inject(s.content.solution),
              result: inject(s.content.result),
              reality: inject(s.content.reality),
            })) as [any, any, any, any]
        },
        resultTable: resultTable,
        additionalInfo: {
            obstacles: ['현지 규제', '환율 변동', '언어 장벽'],
            nextSteps: [
                { label: '구글 검색', value: `${start} 은퇴자 ${goal} 비자 후기` },
                { label: '유튜브', value: `${goal} 현지 물가 브이로그` },
                { label: 'PDF 다운로드', value: `${goal} 정착 가이드` }
            ]
        },
        essay: essayData,
        downloads: downloads,
        visaInfoUrl: config.visaInfoUrl,
    };

    const title = scenarioData.story.header;
    const progress = randInt(50, 92);

    const newResult: StoryResult = {
      title,
      scenarioData,
      progress,
      userInput: generationInput,
      timestamp: new Date().toLocaleTimeString(),
      isDefault: isDefaultScenario && !usedAI,
    };

    setResult(newResult);
    setLoading(false);

    localStorage.setItem('lastStory', JSON.stringify({ input: newResult.userInput }));

    if (window.innerWidth < 1024) {
        setTimeout(() => {
          const resultEl = document.getElementById('result-anchor');
          if (resultEl) resultEl.scrollIntoView({ behavior: 'smooth', block: 'start' });
        }, 100);
    }
  }, [templates, db]);

  const handleGenerateFromPrompt = async (parsedData: Partial<UserInput>, rawText?: string) => {
    let finalInput: UserInput = {
      age: '', job: '', start: '', goal: '', months: 24, country: '', forcedTemplateId: '', family: '', moveType: '', assets: '', useAI: false,
      ...parsedData
    };

    // Use AI to parse raw text if available and if we want deeper analysis
    if (rawText && rawText.length > 10 && process.env.API_KEY) {
        setAiAnalyzing(true);
        try {
            const deepAnalysis = await parseUserPrompt(rawText);
            finalInput = { ...finalInput, ...deepAnalysis };
        } catch (e) {
            console.error("Deep analysis failed, using regex fallback");
        }
        setAiAnalyzing(false);
    }

    setInput(finalInput);
    generateStory(finalInput);
  };

  const handleRandom = () => {
    const samples = db.randomSamples || [];
    if (samples.length === 0) {
      setToastMessage("🎲 관리자 페이지에서 랜덤 예시를 추가해주세요.");
      return;
    }
    const random = samples[Math.floor(Math.random() * samples.length)];
    const baseInput: UserInput = {
      age: '', job: '', start: '', goal: '', months: 24, country: '', forcedTemplateId: '', family: '', moveType: '', assets: '', useAI: false
    };

    // Explicitly merge defaults with the random sample to ensure flags like useAI are carried over
    const finalInput = { ...baseInput, ...random };

    setInput(finalInput);
    setToastMessage("🎲 랜덤 시나리오를 구성했습니다.");
    setTimeout(() => generateStory(finalInput), 500);
  };

  const handleDownload = () => {
    if (result) {
      downloadPDFElement('pdf-content', `희망구매_${result.userInput.goal}_${Date.now()}`);
      setToastMessage("📄 리포트가 PDF로 저장되었습니다.");
    }
  };

  const handleSearch = (type: 'google' | 'youtube') => {
    const qGoal = input.goal || '이민';
    const qJob = input.job || '취업';
    const url = type === 'google' 
      ? `https://google.com/search?q=${input.age}세 ${qGoal} ${qJob} 현실 비용`
      : `https://youtube.com/results?search_query=${qGoal} ${qJob} 브이로그`;
    window.open(url);
  };

  return (
    <div className="min-h-screen bg-[#0f172a] text-white font-sans selection:bg-emerald-500 selection:text-white">
       <div className="fixed inset-0 overflow-hidden pointer-events-none">
          <div className="absolute top-[-10%] right-[-10%] w-[500px] h-[500px] bg-indigo-600/20 rounded-full blur-[100px]"></div>
          <div className="absolute bottom-[-10%] left-[-10%] w-[500px] h-[500px] bg-emerald-600/10 rounded-full blur-[100px]"></div>
       </div>

      <div className="relative w-full max-w-[1400px] mx-auto min-h-screen flex flex-col pb-safe px-4 md:px-6 lg:px-8">

        <div className="pt-4 md:pt-8 pb-6">
           <Header 
             scenarioCount={templates.length} 
             lastVerified={db.lastVerified}
             onAdminClick={() => setShowAdminLogin(true)}
           />
        </div>

        <div className="flex-1 grid grid-cols-1 lg:grid-cols-12 gap-6 lg:gap-8 items-start">

            <div className="lg:col-span-4 space-y-6 sticky top-8">
                <InputForm 
                  input={input}
                  onChange={handleInputChange}
                  onGenerate={handleGenerateFromPrompt}
                  onRandom={handleRandom}
                  onDownload={handleDownload}
                  canDownload={!!result}
                  isGenerating={loading || aiAnalyzing}
                />

                <div className="hidden lg:block space-y-6">
                    <ActionButtons 
                      onGoogleSearch={() => handleSearch('google')}
                      onYoutubeSearch={() => handleSearch('youtube')}
                      onRandom={handleRandom}
                      onRefresh={() => window.location.reload()}
                      onReward={() => {}} 
                    />
                    <AdBanner />
                </div>
            </div>

            <div className="lg:col-span-8 space-y-6">
                <div id="result-anchor"></div>

                {!result && !loading && !aiAnalyzing && (
                    <div className="hidden lg:flex h-full min-h-[400px] items-center justify-center border-2 border-dashed border-white/10 rounded-3xl bg-white/5 text-gray-400">
                        <div className="text-center p-8">
                            <div className="text-4xl mb-4">👈</div>
                            <h3 className="text-xl font-bold mb-2">시뮬레이션을 시작하세요</h3>
                            <p className="text-sm">구체적으로 입력할수록 AI가<br/>더 정밀한 미래를 예측합니다.</p>
                        </div>
                    </div>
                )}

                <ResultSection 
                    result={result} 
                    loading={loading} 
                    extraEssays={db.essays} 
                />

                {/* AI Analysis Overlay */}
                {aiAnalyzing && (
                    <div className="absolute inset-0 z-20 bg-[#0f172a]/90 backdrop-blur-md flex items-center justify-center rounded-3xl">
                        <div className="text-center space-y-4 p-8">
                             <div className="w-16 h-16 border-4 border-emerald-500 border-t-transparent rounded-full animate-spin mx-auto"></div>
                             <div>
                                 <h3 className="text-xl font-bold text-transparent bg-clip-text bg-gradient-to-r from-emerald-400 to-teal-400 animate-pulse">
                                     Deep Prompt Analysis...
                                 </h3>
                                 <p className="text-sm text-gray-400 mt-2">
                                     입력하신 내용의 의도를 파악하고 있습니다.<br/>(가족 구성원, 이사 목적, 예산 규모 등)
                                 </p>
                             </div>
                        </div>
                    </div>
                )}

                {/* AI Generation Overlay */}
                {loading && aiGenerating && (
                    <div className="absolute inset-0 z-20 bg-[#0f172a]/90 backdrop-blur-md flex items-center justify-center rounded-3xl">
                        <div className="text-center space-y-4 p-8">
                             <div className="w-16 h-16 border-4 border-indigo-500 border-t-transparent rounded-full animate-spin mx-auto"></div>
                             <div>
                                 <h3 className="text-xl font-bold text-transparent bg-clip-text bg-gradient-to-r from-indigo-400 to-purple-400 animate-pulse">
                                     Creating New Scenario...
                                 </h3>
                                 <p className="text-sm text-gray-400 mt-2">
                                     '{input.goal}'에 대한 맞춤형 템플릿을 생성 중입니다.<br/>
                                     분석된 결과는 영구 보존됩니다.
                                 </p>
                             </div>
                        </div>
                    </div>
                )}

                <div className="lg:hidden space-y-6">
                    <AdBanner />
                    <ActionButtons 
                      onGoogleSearch={() => handleSearch('google')}
                      onYoutubeSearch={() => handleSearch('youtube')}
                      onRandom={handleRandom}
                      onRefresh={() => window.location.reload()}
                      onReward={() => {}} 
                    />
                </div>
            </div>
        </div>

        <div className="h-12"></div>
      </div>

      {showAdminLogin && (
          <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/80 backdrop-blur-md p-6">
            <GlassCard className="p-8 w-full max-w-sm text-center space-y-6 border border-white/20">
              <h2 className="text-2xl font-bold bg-gradient-to-r from-white to-gray-400 bg-clip-text text-transparent">System Access</h2>
              <input 
                type="password" 
                value={adminPassword}
                onChange={(e) => setAdminPassword(e.target.value)}
                onKeyDown={(e) => e.key === 'Enter' && handleAdminLogin()}
                className="w-full p-4 bg-white/5 rounded-xl text-center text-xl font-bold border border-white/10 focus:border-emerald-500 focus:outline-none transition-colors"
                placeholder="Passcode"
                autoFocus
              />
              <div className="flex gap-4">
                <button onClick={() => setShowAdminLogin(false)} className="flex-1 py-3 bg-gray-700/50 hover:bg-gray-700 rounded-xl transition-colors font-medium">Cancel</button>
                <button onClick={handleAdminLogin} className="flex-1 py-3 bg-emerald-600 hover:bg-emerald-500 rounded-xl transition-colors font-bold shadow-lg shadow-emerald-900/50">Enter</button>
              </div>
            </GlassCard>
          </div>
      )}

      {isAdmin && (
        <AdminDashboard 
          db={db} 
          onUpdateDb={setDb} 
          templates={templates} 
          onUpdateTemplates={setTemplates}
          onClose={() => setIsAdmin(false)} 
        />
      )}

      <Toast message={toastMessage} onClose={() => setToastMessage(null)} />
    </div>
  );
}

export default App;

import { GoogleGenAI, Type, SchemaType } from "@google/genai";
import { UserInput, ScenarioTemplate, ScenarioDB } from "./types";
import { detectCountry, GLOBAL_100 } from "./constants";

// Helper to get Client with dynamic key
const getGenAI = (): GoogleGenAI | null => {
  const localKey = localStorage.getItem('user_gemini_key');
  // Simple Base64 decoding if user stored it "encrypted" (basic obfuscation)
  // In a real app, this logic handles the retrieval. 
  // Here we assume raw key or simple string.
  const apiKey = localKey || process.env.API_KEY;

  if (!apiKey) {
    console.warn("No API Key found in LocalStorage or Env");
    return null;
  }
  return new GoogleGenAI({ apiKey });
};

export const saveApiKey = (key: string) => {
    localStorage.setItem('user_gemini_key', key);
};

export const validateApiKey = async (key: string): Promise<boolean> => {
    try {
        const client = new GoogleGenAI({ apiKey: key });
        // Try a very cheap/fast call to validate
        await client.models.generateContent({
            model: 'gemini-2.5-flash-preview',
            contents: 'ping',
        });
        return true;
    } catch (e) {
        console.error("API Key Validation Failed", e);
        return false;
    }
};

/**
 * AI Input Parser: Analyzes raw natural language to extract structured data
 */
export const parseUserPrompt = async (rawText: string): Promise<Partial<UserInput>> => {
  try {
    const ai = getGenAI();
    if (!ai) return {};

    const schema = {
      type: Type.OBJECT,
      properties: {
        age: { type: Type.STRING, description: "Numeric age string, default '30'" },
        job: { type: Type.STRING, description: "Current job or 'Unemployed'" },
        start: { type: Type.STRING, description: "Starting location (City/Country), default 'Korea'" },
        goal: { type: Type.STRING, description: "Target location (City/Country)" },
        months: { type: Type.INTEGER, description: "Duration in months. If permanent/immigration, use 36." },
        family: { type: Type.STRING, description: "Family status (e.g., 'Single', 'Couple', 'Family of 4', 'With pet')" },
        moveType: { type: Type.STRING, description: "Type of move (e.g., 'Immigration', 'Work', 'Study', 'Month-long Stay', 'Retirement')" },
        assets: { type: Type.STRING, description: "Mentioned assets or budget (e.g., '1억', 'Tight budget')" },
        isDomestic: { type: Type.BOOLEAN, description: "True if the move is within the same country (e.g. Seoul to Jeju, Busan to Seoul). False if crossing borders." }
      },
      required: ["age", "start", "goal", "moveType", "isDomestic"]
    };

    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash-preview',
      contents: `Analyze this user prompt for a life simulation: "${rawText}". Extract key details. Determine strictly if it is a domestic move or international move.`,
      config: {
        responseMimeType: "application/json",
        responseSchema: schema,
        temperature: 0.1, 
      }
    });

    const text = response.text;
    if (!text) return {};
    return JSON.parse(text);
  } catch (e) {
    console.error("Input Parsing Failed", e);
    return {};
  }
};

/**
 * AI Data Generator: Creates diverse random user samples based on trends
 */
export const generateBatchRandomSamples = async (count: number): Promise<Partial<UserInput>[]> => {
  try {
    const ai = getGenAI();
    if (!ai) throw new Error("API Key Missing");

    const schema = {
      type: Type.ARRAY,
      items: {
        type: Type.OBJECT,
        properties: {
          age: { type: Type.STRING },
          job: { type: Type.STRING },
          start: { type: Type.STRING },
          goal: { type: Type.STRING },
          months: { type: Type.INTEGER },
          isDomestic: { type: Type.BOOLEAN },
          useAI: { type: Type.BOOLEAN, description: "MUST be strictly set to true" }
        },
        required: ["age", "job", "start", "goal", "months", "isDomestic", "useAI"]
      }
    };

    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash-preview',
      contents: `Generate exactly ${count} diverse and realistic user personas for a migration simulation app.
      CRITICAL: Return a JSON Array with ${count} items.
      Include a mix of:
      1. Young professionals seeking jobs abroad.
      2. Retirees looking for cheaper countries.
      3. Families moving for education.
      4. Domestic moves for lifestyle.
      5. Digital nomads.
      Set 'useAI' to true for all.`,
      config: {
        responseMimeType: "application/json",
        responseSchema: schema,
        temperature: 0.8,
      }
    });

    const parsed = JSON.parse(response.text || "[]");
    return Array.isArray(parsed) ? parsed : [];
  } catch (e) {
    console.error("Batch Sample Generation Failed", e);
    throw e; // Re-throw to handle in UI
  }
};

/**
 * AI Topic Suggester: Suggests new scenario topics that are missing from current templates
 */
export const suggestNewScenarioTopics = async (existingTags: string[], count: number): Promise<UserInput[]> => {
  try {
    const ai = getGenAI();
    if (!ai) throw new Error("API Key Missing");

    const schema = {
      type: Type.ARRAY,
      items: {
        type: Type.OBJECT,
        properties: {
          age: { type: Type.STRING },
          job: { type: Type.STRING },
          start: { type: Type.STRING },
          goal: { type: Type.STRING },
          months: { type: Type.INTEGER },
          family: { type: Type.STRING },
          moveType: { type: Type.STRING },
          isDomestic: { type: Type.BOOLEAN },
          useAI: { type: Type.BOOLEAN }
        },
        required: ["goal", "moveType"]
      }
    };

    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash-preview',
      contents: `Current scenario tags in DB: [${existingTags.join(', ')}].
      Identify exactly ${count} trending or missing migration/lifestyle scenarios that are NOT in the list.
      (e.g., "Early retirement (FIRE)", "Working Holiday in Australia", "Rural farming in Korea", "Education migration to Malaysia").
      Return them as UserInput objects so I can generate templates for them.
      CRITICAL: Return a JSON Array.`,
      config: {
        responseMimeType: "application/json",
        responseSchema: schema,
        temperature: 0.7,
      }
    });

    const parsed = JSON.parse(response.text || "[]");
    return Array.isArray(parsed) ? parsed : [];
  } catch (e) {
    console.error("Topic Suggestion Failed", e);
    throw e;
  }
};

/**
 * AI Validator: Checks database integrity
 */
export const validateSystemData = async (db: ScenarioDB, templates: ScenarioTemplate[]): Promise<string[]> => {
  try {
    const ai = getGenAI();
    if (!ai) return ["⚠️ API Key is missing. Validation skipped."];

    const dataSummary = {
      sampleCount: db.randomSamples.length,
      samples: db.randomSamples.slice(0, 5), // Only check a few
      templateCount: templates.length,
      templateIds: templates.map(t => t.id),
      sampleTemplateTags: templates[0]?.tags
    };

    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash-preview',
      contents: `Act as a Database Administrator AI. Audit this JSON summary of a simulation app:
      ${JSON.stringify(dataSummary)}

      Check for:
      1. Logical inconsistencies in samples (e.g. Age 10 retiring).
      2. Missing critical tags in templates.
      3. Data format issues.

      Return a list of short string logs/warnings. If all good, return ["✅ Data Integrity Verified", "No critical logical errors found"].`,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: { type: Type.STRING }
        }
      }
    });

    return JSON.parse(response.text || "[]");
  } catch (e) {
    return ["⚠️ Validation process failed due to API error."];
  }
}

export const generateNewScenarioTemplate = async (input: UserInput): Promise<ScenarioTemplate | null> => {
  try {
    const ai = getGenAI();
    if (!ai) throw new Error("API Key Missing");

    const countryKey = input.country || detectCountry(input.goal);
    const config = GLOBAL_100[countryKey] || GLOBAL_100['default'];

    // Determine context nuances based on Domestic vs International
    const domesticInstruction = `
      This is a **DOMESTIC MOVE** (Within the same country).
      - **DO NOT** mention Visas, Immigration checkpoints, or Currency Exchange.
      - **FOCUS ON**: Real estate prices (Jeonse/Monthly), School districts (8-hakgun), Regional prejudice, Commuting hell, City vs Countryside lifestyle gaps.
      - Comparison Table: Compare Rent vs Rent, Commute Time vs Commute Time, Private Academy Costs.
    `;

    const internationalInstruction = `
      This is an **INTERNATIONAL MOVE** (Crossing borders).
      - **FOCUS ON**: Visas (${config.visaName}), Language barriers, Cultural racism, Tax residency, Healthcare access (Insurance vs Private).
      - Comparison Table: Cost of Living, Tax Rates, Safety, Medical Costs.
    `;

    const contextDescription = `
      User Profile:
      - Age: ${input.age}
      - Job: ${input.job}
      - From: ${input.start} -> To: ${input.goal}
      - Family: ${input.family || 'Single'}
      - Move Type: ${input.moveType || 'General Move'}
      - Assets: ${input.assets || 'Unknown'}
      - **Is Domestic Move?**: ${input.isDomestic ? 'YES (Domestic)' : 'NO (International)'}
    `;

    // Define the schema for the AI response
    const schema = {
      type: Type.OBJECT,
      properties: {
        id: { type: Type.STRING, description: "Unique ID like 'template_seoul_jeju_domestic' or 'template_korea_canada_immig'" },
        type: { type: Type.STRING, enum: ["report", "essay"] },
        tags: { 
          type: Type.ARRAY, 
          items: { type: Type.STRING },
          description: "Keywords including location, job, move type, family status, domestic/international" 
        },
        story: {
          type: Type.OBJECT,
          properties: {
            titleTemplate: { type: Type.STRING, description: "Title with placeholders (e.g., '{age}세 {job}의 {goal} 리얼 생존기')" },
            subTemplate: { type: Type.STRING, description: "Subtitle (e.g., '{family}의 {months}개월 정착 시뮬레이션')" },
            stages: {
              type: Type.ARRAY,
              description: "4 stages of the simulation",
              items: {
                type: Type.OBJECT,
                properties: {
                  label: { type: Type.STRING },
                  title: { type: Type.STRING },
                  content: {
                    type: Type.OBJECT,
                    properties: {
                      situation: { type: Type.STRING, nullable: true },
                      thought: { type: Type.STRING, nullable: true },
                      action: { type: Type.STRING, nullable: true },
                      experiment: { type: Type.STRING, nullable: true },
                      failure: { type: Type.STRING, nullable: true },
                      question: { type: Type.STRING, nullable: true },
                      solution: { type: Type.STRING, nullable: true },
                      result: { type: Type.STRING, nullable: true },
                      reality: { type: Type.STRING, nullable: true },
                    }
                  }
                }
              }
            }
          }
        },
        resultTable: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              item: { type: Type.STRING },
              before: { type: Type.STRING },
              after: { type: Type.STRING },
              diff: { type: Type.STRING }
            }
          }
        },
        essay: {
          type: Type.OBJECT,
          properties: {
            title: { type: Type.STRING },
            intro: { type: Type.STRING },
            body: { type: Type.STRING }
          }
        },
        downloads: {
            type: Type.ARRAY,
            items: {
                type: Type.OBJECT,
                properties: {
                    title: { type: Type.STRING },
                    description: { type: Type.STRING },
                    type: { type: Type.STRING, enum: ["pdf", "excel", "doc"] },
                    triggerType: { type: Type.STRING, enum: ["ad", "link"] },
                    triggerUrl: { type: Type.STRING, nullable: true }
                }
            }
        }
      },
      required: ["id", "type", "tags", "story", "essay"]
    };

    const prompt = `
      Create a "Dry Author" style life simulation template.

      ${contextDescription}

      ${input.isDomestic ? domesticInstruction : internationalInstruction}

      CRITICAL INSTRUCTIONS:
      1. **Tone**: Cynical, Analytical, Hyper-Realistic. Highlight "Hidden Costs" (Mental & Financial).
      2. **Variables**: The output MUST be a generic template using placeholders: {age}, {job}, {start}, {goal}, {months}, {currency}, {family}.
         - Even if the user input specific values, replace them with placeholders in the template text where appropriate so it can be reused.
         - However, keep specific local facts hardcoded (e.g. "Gangnam traffic", "Jeju wind", "Vancouver rain").

      3. **Structure**:
         - Story: 4 Stages (Dream -> Reality Check -> Crisis -> Adaptation/Failure).
         - Essay: A sharp critique of the user's desire to move to ${input.goal}.
         - Result Table: 4 Key metrics comparing Start vs Goal.
         - Downloads: 2 specific tools (PDF/Excel) relevant to the move type.
    `;

    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash-preview',
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: schema,
        temperature: 0.7, 
      }
    });

    const jsonText = response.text;
    if (!jsonText) return null;

    const generatedTemplate = JSON.parse(jsonText) as ScenarioTemplate;

    // Post-processing: Ensure tags and ID are robust
    const additionalTags = [
        input.goal.toLowerCase(), 
        input.moveType?.toLowerCase() || 'general', 
        input.isDomestic ? 'domestic' : 'international',
        input.family?.includes('kid') || input.family?.includes('child') ? 'family' : 'single'
    ];

    generatedTemplate.tags = [...new Set([...generatedTemplate.tags, ...additionalTags])];

    // Ensure unique ID for persistence
    const typePrefix = input.isDomestic ? 'domestic' : 'global';
    generatedTemplate.id = `ai_${typePrefix}_${Date.now()}_${input.goal.replace(/\s/g, '').toLowerCase()}`;

    return generatedTemplate;

  } catch (error) {
    console.error("Gemini AI Generation Failed:", error);
    throw error;
  }
};

