const EssayEditor: React.FC<{ db: ScenarioDB; onUpdateDb: (newDb: ScenarioDB) => void }> = ({ db, onUpdateDb }) => {
    const [essays, setEssays] = useState<StandaloneEssay[]>(db.essays || []);
    const [editingId, setEditingId] = useState<string | null>(null);
    const [formData, setFormData] = useState<StandaloneEssay>({
        id: '',
        title: '',
        content: '',
        tags: [],
        date: ''
    });

    useEffect(() => {
        if(db.essays) setEssays(db.essays);
    }, [db.essays]);

    const handleCreate = () => {
        setEditingId('new');
        setFormData({
            id: `essay_${Date.now()}`,
            title: '',
            content: '',
            tags: [],
            date: new Date().toLocaleDateString()
        });
    };

    const handleEdit = (essay: StandaloneEssay) => {
        setEditingId(essay.id);
        setFormData(essay);
    };

    const handleDelete = (id: string) => {
        if(confirm("정말 삭제하시겠습니까?")) {
            const updated = essays.filter(e => e.id !== id);
            setEssays(updated);
            onUpdateDb({ ...db, essays: updated });
        }
    };

    const handleSave = () => {
        if (!formData.title || !formData.content) return alert("제목과 내용을 입력해주세요.");

        let updatedEssays;
        if (editingId === 'new') {
            updatedEssays = [formData, ...essays];
        } else {
            updatedEssays = essays.map(e => e.id === formData.id ? formData : e);
        }

        setEssays(updatedEssays);
        onUpdateDb({ ...db, essays: updatedEssays });
        setEditingId(null);
    };

    return (
        <div className="h-full flex flex-col md:flex-row gap-6 p-6">
            {/* List */}
            <div className="w-full md:w-1/3 space-y-4 overflow-y-auto">
                <button onClick={handleCreate} className="w-full py-3 bg-indigo-600 hover:bg-indigo-500 rounded-xl font-bold text-white shadow-lg">
                    + 새 칼럼 작성
                </button>
                <div className="space-y-2">
                    {essays.map(essay => (
                        <div key={essay.id} className="p-4 bg-white/5 border border-white/5 hover:bg-white/10 rounded-xl cursor-pointer transition-colors" onClick={() => handleEdit(essay)}>
                            <h4 className="font-bold text-sm text-white truncate">{essay.title}</h4>
                            <div className="flex gap-2 mt-2">
                                <span className="text-[10px] text-gray-400">{essay.date}</span>
                                {essay.tags.slice(0, 2).map(tag => (
                                    <span key={tag} className="text-[10px] bg-emerald-900/50 text-emerald-400 px-1.5 py-0.5 rounded">#{tag}</span>
                                ))}
                            </div>
                        </div>
                    ))}
                    {essays.length === 0 && <div className="text-center text-gray-500 py-10">등록된 칼럼이 없습니다.</div>}
                </div>
            </div>

            {/* Editor */}
            <div className="w-full md:w-2/3 bg-black/20 rounded-xl border border-white/10 p-6 flex flex-col">
                {editingId ? (
                    <div className="flex flex-col h-full space-y-4">
                        <div className="flex justify-between items-center pb-4 border-b border-white/10">
                            <h3 className="text-lg font-bold text-white">{editingId === 'new' ? '새 칼럼 작성' : '칼럼 수정'}</h3>
                            <div className="flex gap-2">
                                <button onClick={() => setEditingId(null)} className="px-4 py-2 text-xs font-bold text-gray-400 hover:text-white">취소</button>
                                <button onClick={handleSave} className="px-6 py-2 bg-emerald-600 hover:bg-emerald-500 text-white text-xs font-bold rounded-lg shadow-lg">저장</button>
                            </div>
                        </div>
                        <input 
                            value={formData.title} 
                            onChange={e => setFormData({...formData, title: e.target.value})}
                            className="w-full bg-transparent text-xl font-bold text-white placeholder-gray-600 border-b border-white/10 pb-2 focus:outline-none focus:border-emerald-500" 
                            placeholder="제목을 입력하세요"
                        />
                        <div className="flex gap-2 items-center">
                            <span className="text-xs text-gray-500">태그 (쉼표로 구분):</span>
                            <input 
                                value={formData.tags.join(', ')} 
                                onChange={e => setFormData({...formData, tags: e.target.value.split(',').map(t => t.trim())})}
                                className="flex-1 bg-white/5 rounded px-3 py-1.5 text-xs text-white focus:outline-none border border-transparent focus:border-white/20"
                                placeholder="예: 이민, 현실, 조언"
                            />
                        </div>
                        <textarea 
                            value={formData.content}
                            onChange={e => setFormData({...formData, content: e.target.value})}
                            className="flex-1 bg-transparent text-sm leading-relaxed text-gray-300 resize-none focus:outline-none p-4 border border-white/5 rounded-lg" 
                            placeholder="본문을 작성하세요..."
                        />
                        {editingId !== 'new' && (
                            <button onClick={() => handleDelete(formData.id)} className="self-start text-xs text-red-400 hover:text-red-300 underline mt-2">
                                이 칼럼 삭제하기
                            </button>
                        )}
                    </div>
                ) : (
                    <div className="h-full flex items-center justify-center text-gray-500">
                        왼쪽에서 글을 선택하거나 새로 작성하세요.
                    </div>
                )}
            </div>
        </div>
    );
};

export const AdminDashboard: React.FC<AdminDashboardProps> = ({ 
  db, 
  onUpdateDb, 
  templates, 
  onUpdateTemplates, 
  onClose 
}) => {
  const [activeTab, setActiveTab] = useState<'control' | 'templates' | 'samples' | 'essays'>('control');
  const [logs, setLogs] = useState<string[]>([]);

  const [aiMaintenance, setAiMaintenance] = useState({
      updateTemplates: false,
      updateSamples: false,
      validate: false
  });
  const [batchSize, setBatchSize] = useState<number>(3); 
  const [aiRunning, setAiRunning] = useState(false);
  const [showKeyModal, setShowKeyModal] = useState(false);

  const [selectedTemplateId, setSelectedTemplateId] = useState<string | null>(null);
  const [jsonInput, setJsonInput] = useState<string>('');
  const [isEditing, setIsEditing] = useState(false);
  const [editMode, setEditMode] = useState<'json' | 'easy'>('easy');
  const [easyData, setEasyData] = useState<ScenarioTemplate | null>(null);

  const addLog = (msg: string) => {
    const timestamp = new Date().toLocaleTimeString();
    setLogs(prev => [`[${timestamp}] ${msg}`, ...prev]);
  };

  const runAIMaintenance = async () => {
    setAiRunning(true);
    addLog(`🚀 AI 자동 유지보수 시작 (Batch Size: ${batchSize})...`);

    // Create local accumulators to prevent race conditions during async loops
    const generatedTemplates: ScenarioTemplate[] = [];
    const generatedSamples: Partial<UserInput>[] = [];

    try {
        // 1. Validation Logic
        if (aiMaintenance.validate) {
            addLog("🔍 데이터 정합성 검사 중...");
            const report = await validateSystemData(db, templates);
            report.forEach(r => addLog(`📋 [리포트] ${r}`));
        }

        // 2. Sample Updates (Accumulate First)
        if (aiMaintenance.updateSamples) {
            addLog(`🎲 ${batchSize}개의 새로운 랜덤 예시 생성 중...`);
            const newSamples = await generateBatchRandomSamples(batchSize); 
            if (newSamples.length > 0) {
                generatedSamples.push(...newSamples);
                addLog(`✅ 랜덤 예시 ${newSamples.length}개 생성 성공 (저장 대기)`);
            } else {
                addLog("⚠️ 랜덤 예시 생성 실패 (AI 응답 없음)");
            }
        }

        // 3. Template Expansion (Accumulate First)
        if (aiMaintenance.updateTemplates) {
            addLog(`🧠 부족한 시나리오 주제 ${batchSize}개 분석 중...`);
            const allTags = templates.flatMap(t => t.tags);
            const topicIdeas = await suggestNewScenarioTopics(allTags, batchSize);

            if (topicIdeas.length === 0) {
                 addLog("⚠️ 새로운 주제를 발견하지 못했습니다.");
            } else {
                addLog(`💡 발견된 주제: ${topicIdeas.map(t => t.goal).join(', ')}`);

                // Sequential Processing to respect API limits and better logging
                for (let i = 0; i < topicIdeas.length; i++) {
                    const idea = topicIdeas[i];
                    addLog(`[${i + 1}/${topicIdeas.length}] ✍️ 템플릿 작성 중: ${idea.goal}...`);
                    const newTemplate = await generateNewScenarioTemplate(idea as UserInput);

                    if (newTemplate) {
                        generatedTemplates.push(newTemplate);
                        addLog(`✨ 템플릿 생성 완료: ${newTemplate.id}`);
                    }
                }
            }
        }

        // 4. CRITICAL: Commit Changes (Single Atomic Update per Category)

        // Commit Samples
        if (generatedSamples.length > 0) {
            const currentSamples = db.randomSamples || [];
            // Merge new samples at the top, limit total to 50
            const updatedSamples = [...generatedSamples, ...currentSamples].slice(0, 50);

            // Update State
            onUpdateDb({ ...db, randomSamples: updatedSamples });
            addLog(`💾 시스템 DB에 랜덤 예시 ${generatedSamples.length}건 반영 완료.`);
        }

        // Commit Templates
        if (generatedTemplates.length > 0) {
            // Merge new templates at the top
            const updatedTemplates = [...generatedTemplates, ...templates];

            // Update State
            onUpdateTemplates(updatedTemplates);
            addLog(`💾 시스템 DB에 템플릿 ${generatedTemplates.length}건 반영 완료.`);
        }

        addLog("🏁 모든 AI 작업 및 데이터 저장이 완료되었습니다.");

    } catch (e: any) {
        console.error(e);
        addLog(`❌ 치명적 오류 발생: ${e.message}`);
        // Simple heuristic to detect auth/404 errors likely caused by bad key
        if(e.message?.includes('404') || e.message?.includes('403') || e.message?.includes('401') || e.message?.includes('key')) {
             addLog("👉 API 키 설정이 필요해 보입니다. 키 설정 팝업을 엽니다.");
             setShowKeyModal(true);
        }
    } finally {
        setAiRunning(false);
    }
  };

  const handleSelectTemplate = (t: ScenarioTemplate) => {
    setSelectedTemplateId(t.id);
    const jsonStr = JSON.stringify(t, null, 2);
    setJsonInput(jsonStr);
    setEasyData(JSON.parse(jsonStr)); // Deep copy
    setIsEditing(true);
  };

  const handleCreateNew = () => {
    const newTemplate = { ...DEFAULT_TEMPLATES[0], id: `custom_${Date.now()}`, tags: ['new'] };
    setSelectedTemplateId(null);
    const jsonStr = JSON.stringify(newTemplate, null, 2);
    setJsonInput(jsonStr);
    setEasyData(newTemplate);
    setIsEditing(true);
  };

  const handleSaveTemplate = () => {
    try {
      const payload = editMode === 'easy' && easyData ? easyData : JSON.parse(jsonInput);
      if (!payload.id || !payload.story) throw new Error("Invalid Format");

      const exists = templates.find(t => t.id === payload.id);
      let newTemplates;

      if (exists) {
        newTemplates = templates.map(t => t.id === payload.id ? payload : t);
        addLog(`📝 템플릿 수정됨: ${payload.id}`);
      } else {
        newTemplates = [payload, ...templates];
        addLog(`✨ 새 템플릿 추가됨: ${payload.id}`);
      }

      onUpdateTemplates(newTemplates);
      setJsonInput(JSON.stringify(payload, null, 2));
      setEasyData(payload);
      alert("저장되었습니다.");
    } catch (e) {
      alert("JSON 형식이 올바르지 않습니다.");
    }
  };

  const handleDeleteTemplate = (id: string) => {
    if(confirm("정말 삭제하시겠습니까?")) {
        const newTemplates = templates.filter(t => t.id !== id);
        onUpdateTemplates(newTemplates);
        setIsEditing(false);
        addLog(`🗑 템플릿 삭제됨: ${id}`);
    }
  }

  return (
