import React, { useState, useEffect } from 'react';
import { GlassCard } from './GlassCard';
import { ScenarioDB, ScenarioTemplate, DownloadableResource, UserInput, StandaloneEssay } from '../types';
import { DEFAULT_TEMPLATES } from '../constants';
import { generateBatchRandomSamples, generateNewScenarioTemplate, suggestNewScenarioTopics, validateSystemData } from '../aiService';
import { ApiKeyModal } from './ApiKeyModal';

interface AdminDashboardProps {
  db: ScenarioDB;
  onUpdateDb: React.Dispatch<React.SetStateAction<ScenarioDB>>;
  templates: ScenarioTemplate[];
  onUpdateTemplates: React.Dispatch<React.SetStateAction<ScenarioTemplate[]>>;
  onClose: () => void;
}

// --- Data Export Modal (Now supports JSON Backup/Restore) ---
const DataExportModal: React.FC<{ 
    isOpen: boolean; 
    onClose: () => void; 
    db: ScenarioDB; 
    templates: ScenarioTemplate[];
    onRestore: (data: { db: ScenarioDB, templates: ScenarioTemplate[] }) => void;
}> = ({ isOpen, onClose, db, templates, onRestore }) => {
    const [copied, setCopied] = useState(false);
    const [activeTab, setActiveTab] = useState<'code' | 'backup'>('backup');

    if (!isOpen) return null;

    // Convert current state into a format ready to be pasted into constants.ts
    const exportCode = `
// --- PASTE THIS INTO constants.ts TO SAVE PERMANENTLY ---

import { ScenarioDB, ScenarioTemplate } from './types';

export const DEFAULT_TEMPLATES: ScenarioTemplate[] = ${JSON.stringify(templates, null, 2)};

export const INITIAL_DB: ScenarioDB = ${JSON.stringify(db, null, 2)};
    `;

    const handleCopy = () => {
        navigator.clipboard.writeText(exportCode);
        setCopied(true);
        setTimeout(() => setCopied(false), 2000);
    };

    const handleDownloadJson = () => {
        const fullBackup = {
            timestamp: new Date().toISOString(),
            db,
            templates
        };
        const element = document.createElement("a");
        const file = new Blob([JSON.stringify(fullBackup, null, 2)], {type: 'application/json'});
        element.href = URL.createObjectURL(file);
        element.download = `HOPE_BACKUP_${new Date().toISOString().slice(0,10)}.json`;
        document.body.appendChild(element); 
        element.click();
        document.body.removeChild(element);
    };

    const handleFileRestore = (e: React.ChangeEvent<HTMLInputElement>) => {
        const fileReader = new FileReader();
        if (e.target.files && e.target.files[0]) {
            fileReader.readAsText(e.target.files[0], "UTF-8");
            fileReader.onload = (event) => {
                try {
                    const json = JSON.parse(event.target?.result as string);
                    if (json.db && json.templates) {
                        if(confirm(`백업 파일(${json.timestamp})로 복구하시겠습니까? 현재 데이터는 덮어씌워집니다.`)) {
                            onRestore({ db: json.db, templates: json.templates });
                            onClose();
                            alert("✅ 복구 완료되었습니다.");
                        }
                    } else {
                        alert("❌ 올바르지 않은 백업 파일 형식입니다.");
                    }
                } catch (err) {
                    alert("❌ 파일 읽기 실패");
                }
            };
        }
    };

    return (
        <div className="fixed inset-0 z-[100] flex items-center justify-center bg-black/90 backdrop-blur-md p-6 animate-fade-in">
            <GlassCard className="w-full max-w-4xl h-[80vh] flex flex-col p-8 border-l-4 border-l-blue-500 shadow-2xl relative">
                <button onClick={onClose} className="absolute top-6 right-6 text-gray-400 hover:text-white">✕</button>

                <div className="mb-6">
                    <h2 className="text-2xl font-bold text-white flex items-center gap-2">
                        💾 데이터 관리 (백업 & 저장)
                    </h2>
                    <div className="flex gap-4 mt-4 border-b border-white/10">
                        <button onClick={() => setActiveTab('backup')} className={`pb-2 px-2 text-sm font-bold transition-colors ${activeTab === 'backup' ? 'text-blue-400 border-b-2 border-blue-400' : 'text-gray-400'}`}>파일 백업/복구</button>
                        <button onClick={() => setActiveTab('code')} className={`pb-2 px-2 text-sm font-bold transition-colors ${activeTab === 'code' ? 'text-blue-400 border-b-2 border-blue-400' : 'text-gray-400'}`}>개발자용 코드</button>
                    </div>
                </div>

                {activeTab === 'backup' ? (
                     <div className="flex-1 flex flex-col gap-6 justify-center items-center text-center p-8 bg-white/5 rounded-xl border border-white/10 border-dashed">
                        <div className="space-y-4 max-w-md">
                            <h3 className="text-xl font-bold text-white">📂 전체 데이터 백업</h3>
                            <p className="text-sm text-gray-400">
                                현재 작성된 모든 에세이, 템플릿, 설정을 JSON 파일로 다운로드합니다. 이 파일이 있으면 언제든 데이터를 복구할 수 있습니다.
                            </p>
                            <button onClick={handleDownloadJson} className="w-full py-4 bg-emerald-600 hover:bg-emerald-500 rounded-xl font-bold text-white text-lg shadow-lg transition-all transform hover:scale-105">
                                ⬇️ 백업 파일 다운로드 (.json)
                            </button>
                        </div>

                        <div className="w-full h-px bg-white/10 my-4"></div>

                        <div className="space-y-4 max-w-md">
                            <h3 className="text-xl font-bold text-white">♻️ 데이터 복구</h3>
                            <p className="text-sm text-gray-400">
                                백업해둔 JSON 파일을 선택하여 데이터를 복원합니다.
                            </p>
                            <label className="block w-full py-4 bg-blue-600/20 hover:bg-blue-600/30 border border-blue-500/50 rounded-xl font-bold text-blue-300 text-lg cursor-pointer transition-all hover:border-blue-400">
                                📤 백업 파일 업로드 및 복구
                                <input type="file" accept=".json" onChange={handleFileRestore} className="hidden" />
                            </label>
                        </div>
                     </div>
                ) : (
                    <div className="flex-1 bg-black/50 rounded-xl border border-white/10 overflow-hidden flex flex-col">
                        <div className="flex justify-between items-center p-2 bg-white/5 border-b border-white/10">
                            <span className="text-xs font-mono text-gray-500 ml-2">constants.ts export</span>
                            <button 
                                onClick={handleCopy}
                                className={`px-4 py-1.5 rounded-lg text-xs font-bold transition-all ${copied ? 'bg-green-500 text-white' : 'bg-blue-600 hover:bg-blue-500 text-white'}`}
                            >
                                {copied ? "✅ 복사 완료!" : "📋 코드 전체 복사"}
                            </button>
                        </div>
                        <textarea 
                            readOnly
                            value={exportCode}
                            className="flex-1 bg-transparent p-4 text-xs font-mono text-blue-200 resize-none focus:outline-none"
                        />
                    </div>
                )}

                <div className="mt-6 text-center">
                    <button onClick={onClose} className="px-8 py-3 bg-gray-700 hover:bg-gray-600 rounded-xl font-bold text-white">
                        닫기
                    </button>
                </div>
            </GlassCard>
        </div>
    );
};

const RandomSampleEditor: React.FC<{db: ScenarioDB, onUpdateDb: React.Dispatch<React.SetStateAction<ScenarioDB>>, templates: ScenarioTemplate[]}> = ({ db, onUpdateDb, templates }) => {
    // Safety check: ensure db.randomSamples is an array
    const [samples, setSamples] = useState<Partial<UserInput>[]>(Array.isArray(db.randomSamples) ? db.randomSamples : []);

    useEffect(() => {
        if(Array.isArray(db.randomSamples)) {
            setSamples(db.randomSamples);
        } else {
            setSamples([]);
        }
    }, [db.randomSamples]);

    const handleUpdate = (index: number, field: keyof UserInput, value: string | number | boolean) => {
        const newSamples = [...samples];
        if (newSamples[index]) {
            newSamples[index] = { ...newSamples[index], [field]: value };
             if (field === 'useAI' && value === true) {
                newSamples[index].forcedTemplateId = '';
            }
            setSamples(newSamples);
        }
    };

    const handleSave = () => {
        onUpdateDb(prev => ({ ...prev, randomSamples: samples }));
        alert("✅ 저장되었습니다.");
    };

    const handleAdd = () => {
        setSamples([...samples, { age: '30', job: '직장인', start: '서울', goal: '미국', months: 24, forcedTemplateId: '', isDomestic: false, useAI: false }]);
    };

    const handleRemove = (index: number) => {
        if (confirm('이 예시를 삭제하시겠습니까?')) {
            const newSamples = [...samples];
            newSamples.splice(index, 1);
            setSamples(newSamples);
        }
    };

    return (
        <div className="h-full overflow-y-auto p-6 md:p-8 space-y-6 pb-20">
            <GlassCard className="p-6 border-l-4 border-l-purple-500">
                 <div className="flex justify-between items-center mb-6">
                    <div>
                        <h3 className="text-xl font-bold flex items-center gap-2">
                           🔀 랜덤 예시 설정
                           <span className="text-xs bg-purple-500/20 text-purple-300 px-2 py-1 rounded-full">{samples.length}개</span>
                        </h3>
                    </div>
                    <button onClick={handleSave} className="px-6 py-2 bg-emerald-600 hover:bg-emerald-500 rounded-xl font-bold text-white text-sm">
                        저장
                    </button>
                 </div>

                 <div className="grid gap-4">
                    {samples.map((sample, index) => (
                         <div key={index} className="bg-white/5 border border-white/10 rounded-xl p-4 relative">
                            <button onClick={() => handleRemove(index)} className="absolute top-2 right-2 text-red-500 font-bold hover:text-white">✕</button>
                            <div className="grid grid-cols-2 md:grid-cols-6 gap-3">
                                <input value={sample.age || ''} onChange={(e) => handleUpdate(index, 'age', e.target.value)} className="bg-black/30 p-2 rounded text-sm text-white" placeholder="나이" />
                                <input value={sample.job || ''} onChange={(e) => handleUpdate(index, 'job', e.target.value)} className="bg-black/30 p-2 rounded text-sm text-white" placeholder="직업" />
                                <input value={sample.start || ''} onChange={(e) => handleUpdate(index, 'start', e.target.value)} className="bg-black/30 p-2 rounded text-sm text-white" placeholder="출발" />
                                <input value={sample.goal || ''} onChange={(e) => handleUpdate(index, 'goal', e.target.value)} className="bg-black/30 p-2 rounded text-sm text-white" placeholder="도착" />
                                <select value={sample.isDomestic ? 'domestic' : 'intl'} onChange={(e) => handleUpdate(index, 'isDomestic', e.target.value === 'domestic')} className="bg-black/30 p-2 rounded text-sm text-white">
                                    <option value="intl">해외</option>
                                    <option value="domestic">국내</option>
                                </select>
                                <div className="flex items-center gap-2">
                                     <input type="checkbox" checked={!!sample.useAI} onChange={(e) => handleUpdate(index, 'useAI', e.target.checked)} className="w-4 h-4" />
                                     <span className={`text-xs ${sample.useAI ? 'text-emerald-400 font-bold' : 'text-gray-400'}`}>AI 생성</span>
                                </div>
                            </div>
                         </div>
                    ))}
                    <button onClick={handleAdd} className="w-full py-3 bg-white/5 rounded-xl text-gray-400 hover:text-white border border-dashed border-white/20">+ 추가</button>
                 </div>
            </GlassCard>
        </div>
    );
};

const EssayEditor: React.FC<{ db: ScenarioDB; onUpdateDb: React.Dispatch<React.SetStateAction<ScenarioDB>> }> = ({ db, onUpdateDb }) => {
    // Safety check: ensure db.essays is an array
    const [essays, setEssays] = useState<StandaloneEssay[]>(Array.isArray(db.essays) ? db.essays : []);
    const [editingId, setEditingId] = useState<string | null>(null);
    const [formData, setFormData] = useState<StandaloneEssay>({ id: '', title: '', content: '', tags: [], date: '' });

    useEffect(() => {
        if(Array.isArray(db.essays)) {
            setEssays(db.essays);
        } else {
            setEssays([]);
        }
    }, [db.essays]);

    const handleCreate = () => {
        setEditingId('new');
        setFormData({ id: `essay_${Date.now()}`, title: '', content: '', tags: [], date: new Date().toLocaleDateString() });
    };

    const handleSave = () => {
        onUpdateDb(prev => {
            const current = Array.isArray(prev.essays) ? prev.essays : [];
            const updated = editingId === 'new' 
                ? [formData, ...current] 
                : current.map(e => e.id === formData.id ? formData : e);
            return { ...prev, essays: updated };
        });
        setEditingId(null);
    };

    return (
        <div className="h-full flex flex-col md:flex-row gap-6 p-6">
            <div className="w-full md:w-1/3 space-y-4">
                <button onClick={handleCreate} className="w-full py-3 bg-indigo-600 hover:bg-indigo-500 rounded-xl font-bold text-white">+ 새 칼럼 작성</button>
                <div className="space-y-2 h-[400px] overflow-y-auto">
                    {essays.map(essay => (
                        <div key={essay.id} className="p-4 bg-white/5 hover:bg-white/10 rounded-xl cursor-pointer" onClick={() => { setEditingId(essay.id); setFormData(essay); }}>
                            <h4 className="font-bold text-sm text-white truncate">{essay.title}</h4>
                        </div>
                    ))}
                </div>
            </div>
            <div className="w-full md:w-2/3 bg-black/20 rounded-xl p-6">
                {editingId ? (
                    <div className="flex flex-col h-full space-y-4">
                        <input value={formData.title} onChange={e => setFormData({...formData, title: e.target.value})} className="bg-transparent text-xl font-bold text-white border-b border-white/10 pb-2" placeholder="제목" />
                        <textarea value={formData.content} onChange={e => setFormData({...formData, content: e.target.value})} className="flex-1 bg-transparent text-sm text-gray-300 resize-none p-4 border border-white/5 rounded-lg h-[300px]" placeholder="내용" />
                        <div className="flex justify-end gap-2">
                            <button onClick={() => setEditingId(null)} className="px-4 py-2 text-xs font-bold text-gray-400">취소</button>
                            <button onClick={handleSave} className="px-6 py-2 bg-emerald-600 text-white text-xs font-bold rounded-lg">저장</button>
                        </div>
                    </div>
                ) : (
                    <div className="h-full flex items-center justify-center text-gray-500">글을 선택하거나 작성하세요.</div>
                )}
            </div>
        </div>
    );
};

export const AdminDashboard: React.FC<AdminDashboardProps> = ({ 
  db, 
  onUpdateDb, 
  templates, 
  onUpdateTemplates, 
  onClose 
}) => {
  const [activeTab, setActiveTab] = useState<'control' | 'templates' | 'samples' | 'essays'>('control');
  const [logs, setLogs] = useState<string[]>([]);
  const [aiMaintenance, setAiMaintenance] = useState({ updateTemplates: false, updateSamples: false, validate: false });
  const [batchSize, setBatchSize] = useState<number>(3); 
  const [aiRunning, setAiRunning] = useState(false);
  const [showKeyModal, setShowKeyModal] = useState(false);
  const [showExportModal, setShowExportModal] = useState(false);

  const addLog = (msg: string) => {
    const timestamp = new Date().toLocaleTimeString();
    setLogs(prev => [`[${timestamp}] ${msg}`, ...prev]);
  };

  const handleRestore = (data: { db: ScenarioDB, templates: ScenarioTemplate[] }) => {
    onUpdateDb(data.db);
    onUpdateTemplates(data.templates);
    // Explicitly save to local storage immediately
    localStorage.setItem('app_db', JSON.stringify(data.db));
    localStorage.setItem('app_templates', JSON.stringify(data.templates));
  };

  const runAIMaintenance = async () => {
    setAiRunning(true);
    addLog(`🚀 AI 자동 유지보수 시작 (Batch Size: ${batchSize})...`);

    try {
        const generatedTemplates: ScenarioTemplate[] = [];
        const generatedSamples: Partial<UserInput>[] = [];

        if (aiMaintenance.validate) {
            addLog("🔍 데이터 정합성 검사 중...");
            const report = await validateSystemData(db, templates);
            if (Array.isArray(report)) {
                report.forEach(r => addLog(`📋 [리포트] ${r}`));
            } else {
                addLog("⚠️ 검증 결과 형식이 올바르지 않습니다.");
            }
        }

        if (aiMaintenance.updateSamples) {
            addLog(`🎲 ${batchSize}개의 새로운 랜덤 예시 생성 중...`);
            const newSamples = await generateBatchRandomSamples(batchSize); 
            if (newSamples.length > 0) {
                generatedSamples.push(...newSamples);
                addLog(`✅ 랜덤 예시 ${newSamples.length}개 생성 성공`);
            }
        }

        if (aiMaintenance.updateTemplates) {
            addLog(`🧠 부족한 시나리오 주제 분석 중...`);
            const allTags = templates.flatMap(t => t.tags);
            const topicIdeas = await suggestNewScenarioTopics(allTags, batchSize);

            for (let i = 0; i < topicIdeas.length; i++) {
                const idea = topicIdeas[i];
                addLog(`[${i + 1}/${topicIdeas.length}] ✍️ 템플릿 작성 중: ${idea.goal}...`);
                const newTemplate = await generateNewScenarioTemplate(idea as UserInput);
                if (newTemplate) generatedTemplates.push(newTemplate);
            }
        }

        // Safe State Updates with explicit array checks to avoid 'number 0 is not iterable'
        if (generatedSamples.length > 0) {
            onUpdateDb(prev => ({
                 ...prev, 
                 randomSamples: [...generatedSamples, ...(Array.isArray(prev.randomSamples) ? prev.randomSamples : [])].slice(0, 50) 
            }));
            addLog(`💾 시스템 DB에 랜덤 예시 업데이트 완료.`);
        }

        if (generatedTemplates.length > 0) {
            onUpdateTemplates(prev => [...generatedTemplates, ...prev]);
            addLog(`💾 시스템 DB에 템플릿 업데이트 완료.`);
        }

        addLog("🏁 모든 작업 완료.");

    } catch (e: any) {
        console.error(e);
        addLog(`❌ 오류 발생: ${e.message}`);
    } finally {
        setAiRunning(false);
    }
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/80 backdrop-blur-md p-4 animate-fade-in">
      <GlassCard className="w-full max-w-6xl h-[90vh] flex flex-col bg-[#111827] border-white/20 shadow-2xl overflow-hidden">
        {/* Header */}
        <div className="p-6 border-b border-white/10 flex justify-between items-center bg-black/20">
          <div>
             <h2 className="text-2xl font-black text-white flex items-center gap-2">
                <span className="text-3xl">⚙️</span> SYSTEM ADMIN
             </h2>
             <p className="text-xs text-emerald-400 font-mono mt-1">
                Connected: {new Date().toLocaleDateString()}
             </p>
          </div>
          <div className="flex gap-2">
            <button 
                onClick={() => {
                   if(confirm("정말로 모든 데이터를 초기화하시겠습니까? (로컬 데이터 삭제 후 새로고침)")) {
                       localStorage.removeItem('app_db');
                       localStorage.removeItem('app_templates');
                       window.location.reload();
                   }
                }}
                className="px-4 py-2 bg-red-600/20 text-red-400 border border-red-500/50 rounded-lg text-xs font-bold hover:bg-red-600/30 transition-colors flex items-center gap-2"
            >
                🔄 데이터 초기화
            </button>
            <button 
                onClick={() => setShowExportModal(true)}
                className="px-4 py-2 bg-blue-600/20 text-blue-400 border border-blue-500/50 rounded-lg text-xs font-bold hover:bg-blue-600/30 transition-colors flex items-center gap-2"
            >
                💾 백업 및 저장
            </button>
            <button 
                onClick={() => setShowKeyModal(true)}
                className="px-4 py-2 bg-yellow-600/20 text-yellow-500 border border-yellow-600/50 rounded-lg text-xs font-bold hover:bg-yellow-600/30 transition-colors flex items-center gap-2"
            >
                🔑 API 키 설정
            </button>
            <button onClick={onClose} className="w-10 h-10 rounded-full bg-white/10 hover:bg-white/20 flex items-center justify-center text-white transition-colors">
                ✕
            </button>
          </div>
        </div>

        {/* Tabs */}
        <div className="flex border-b border-white/10 bg-black/10">
           {['control', 'templates', 'samples', 'essays'].map(tab => (
               <button 
                 key={tab}
                 onClick={() => setActiveTab(tab as any)}
                 className={`px-8 py-4 text-sm font-bold uppercase transition-colors ${activeTab === tab ? 'bg-emerald-600/20 text-emerald-400 border-b-2 border-emerald-500' : 'text-gray-400 hover:text-white'}`}
               >
                 {tab}
               </button>
           ))}
        </div>

        {/* Content */}
        <div className="flex-1 overflow-hidden bg-[#0f172a]">
           {activeTab === 'control' && (
             <div className="p-8 h-full overflow-y-auto space-y-8">
                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                    <GlassCard className="p-6 border-l-4 border-l-emerald-500">
                        <h3 className="text-gray-400 text-xs font-bold uppercase tracking-wider mb-4">AI Auto-Maintenance</h3>
                        <div className="space-y-4 mb-6">
                            <label className="flex items-center gap-3"><input type="checkbox" checked={aiMaintenance.updateTemplates} onChange={e => setAiMaintenance({...aiMaintenance, updateTemplates: e.target.checked})} className="w-4 h-4" /> 템플릿 생성</label>
                            <label className="flex items-center gap-3"><input type="checkbox" checked={aiMaintenance.updateSamples} onChange={e => setAiMaintenance({...aiMaintenance, updateSamples: e.target.checked})} className="w-4 h-4" /> 예시 업데이트</label>
                            <label className="flex items-center gap-3"><input type="checkbox" checked={aiMaintenance.validate} onChange={e => setAiMaintenance({...aiMaintenance, validate: e.target.checked})} className="w-4 h-4" /> 데이터 검증</label>
                            <div className="pt-2">
                                <span className="text-xs text-gray-400">Batch Size: {batchSize}</span>
                                <input type="range" min="1" max="5" value={batchSize} onChange={e => setBatchSize(Number(e.target.value))} className="w-full" />
                            </div>
                        </div>
                        <button onClick={runAIMaintenance} disabled={aiRunning} className="w-full py-3 bg-emerald-600 rounded-xl font-bold text-white shadow-lg">
                            {aiRunning ? 'AI 작업 중...' : '작업 실행'}
                        </button>
                    </GlassCard>

                    <GlassCard className="p-6 flex flex-col">
                        <h3 className="text-gray-400 text-xs font-bold uppercase tracking-wider mb-4">Logs</h3>
                        <div className="flex-1 bg-black/40 rounded-xl p-4 font-mono text-xs text-green-400 overflow-y-auto">
                            {logs.map((log, i) => <div key={i} className="mb-1">{log}</div>)}
                        </div>
                    </GlassCard>
                </div>
             </div>
           )}

           {activeTab === 'templates' && (
             <div className="p-8 text-center text-gray-400">
                 템플릿 편집 기능은 현재 점검 중입니다. (DB 업데이트 우선)
             </div>
           )}

           {activeTab === 'samples' && (
               <RandomSampleEditor db={db} onUpdateDb={onUpdateDb} templates={templates} />
           )}

           {activeTab === 'essays' && (
               <EssayEditor db={db} onUpdateDb={onUpdateDb} />
           )}
        </div>
      </GlassCard>

      <ApiKeyModal isOpen={showKeyModal} onClose={() => setShowKeyModal(false)} />
      <DataExportModal isOpen={showExportModal} onClose={() => setShowExportModal(false)} db={db} templates={templates} onRestore={handleRestore} />
    </div>
  );
};

import React, { useState, useEffect, useCallback } from 'react';
import { Header } from './components/Header';
import { InputForm } from './components/InputForm';
import { ResultSection, downloadPDFElement } from './components/ResultSection';
import { AdBanner } from './components/AdBanner';
import { ActionButtons } from './components/ActionButtons';
import { Toast } from './components/Toast';
import { AdminDashboard } from './components/AdminDashboard';
import { INITIAL_DB, GLOBAL_100, detectCountry, DEFAULT_TEMPLATES } from './constants';
import { UserInput, StoryResult, ScenarioDB, ScenarioData, ScenarioTemplate, ComparisonRow, EssayData, DownloadableResource } from './types';
import { GlassCard } from './components/GlassCard';
import { generateNewScenarioTemplate, parseUserPrompt } from './aiService';

function App() {
  // --- [CRITICAL FIX] Data Persistence Safety Layer ---
  // 사용자 데이터(에세이, 커스텀 템플릿)가 코드 업데이트로 인해 날아가지 않도록
  // LocalStorage 데이터를 최우선으로 하고, 기본값(DEFAULT_TEMPLATES)을 병합(Merge)합니다.

  const [db, setDb] = useState<ScenarioDB>(() => {
    try {
      const saved = localStorage.getItem('app_db');
      if (saved) {
        const parsed = JSON.parse(saved);

        // 데이터 병합: 기존 필드 유지 + 새 필드 추가
        // 중요: 사용자가 작성한 essays가 있다면 절대 덮어쓰지 않음
        const existingEssays = Array.isArray(parsed.essays) ? parsed.essays : [];
        const defaultEssays = Array.isArray(INITIAL_DB.essays) ? INITIAL_DB.essays : [];

        // 사용자가 작성한 데이터가 있으면 그것을 사용, 없으면 기본값 사용
        const mergedEssays = existingEssays.length > 0 ? existingEssays : defaultEssays;

        const existingSamples = Array.isArray(parsed.randomSamples) ? parsed.randomSamples : [];
        const defaultSamples = INITIAL_DB.randomSamples;
        const mergedSamples = existingSamples.length > 0 ? existingSamples : defaultSamples;

        return {
          ...INITIAL_DB, // 최신 코드의 구조(Schema)를 기반으로 함
          ...parsed,     // 로컬 저장소의 값을 덮어씀 (사용자 설정 우선)
          essays: mergedEssays, // 안전하게 병합된 에세이 리스트
          randomSamples: mergedSamples,
          scenarios: parsed.scenarios || {}
        };
      }
    } catch (e) {
      console.error("DB Load Error, resetting to default:", e);
    }
    return INITIAL_DB;
  });

  const [templates, setTemplates] = useState<ScenarioTemplate[]>(() => {
    try {
      const saved = localStorage.getItem('app_templates');
      if (saved) {
        const parsed = JSON.parse(saved);
        if (Array.isArray(parsed)) {
            // [FIX] 저장된 데이터가 있더라도, 기본 템플릿(4개)이 없으면 복구(Merge)
            const merged = [...parsed];
            DEFAULT_TEMPLATES.forEach(def => {
                // ID가 같은게 없으면 추가 (기본 템플릿 복구)
                if (!merged.find(t => t.id === def.id)) {
                    merged.push(def);
                }
            });
            // 만약 merged가 비어있다면 기본값 사용 (방어 코드)
            return merged.length > 0 ? merged : DEFAULT_TEMPLATES;
        }
      }
    } catch (e) {
      console.error("Templates Load Error, resetting:", e);
    }
    // 저장된 게 없으면 기본 4개 템플릿 사용
    return DEFAULT_TEMPLATES;
  });

  const [isAdmin, setIsAdmin] = useState(false);
  const [showAdminLogin, setShowAdminLogin] = useState(false);
  const [adminPassword, setAdminPassword] = useState('');

  const [input, setInput] = useState<UserInput>({
    age: '',
    job: '',
    start: '',
    goal: '',
    months: 24,
    country: '',
    forcedTemplateId: '',
    family: '',
    moveType: '',
    assets: '',
    useAI: false
  });
  const [result, setResult] = useState<StoryResult | null>(null);
  const [loading, setLoading] = useState(false);
  const [aiGenerating, setAiGenerating] = useState(false);
  const [aiAnalyzing, setAiAnalyzing] = useState(false);
  const [toastMessage, setToastMessage] = useState<string | null>(null);

  useEffect(() => {
    if (window.location.hash === '#admin') setShowAdminLogin(true);
  }, []);

  // Persist DB and Templates to LocalStorage
  useEffect(() => {
    localStorage.setItem('app_db', JSON.stringify(db));
  }, [db]);
  useEffect(() => {
    localStorage.setItem('app_templates', JSON.stringify(templates));
  }, [templates]);

  const handleAdminLogin = () => {
    if (adminPassword === '1234') {
      setIsAdmin(true);
      setShowAdminLogin(false);
      setToastMessage("🔓 관리자 모드로 접속했습니다.");
    } else {
      alert("비밀번호가 올바르지 않습니다.");
    }
  };

  const handleInputChange = (field: keyof UserInput, value: string | number) => {
    setInput(prev => ({ ...prev, [field]: value }));
  };

  const generateStory = useCallback(async (generationInput: UserInput) => {
    setLoading(true);
    setResult(null); 
    setAiGenerating(false);

    // 1. Prepare Variables
    const age = generationInput.age || '미지정';
    const job = generationInput.job || '미지정';
    const start = generationInput.start || '미지정';
    const goal = generationInput.goal || '미지정';
    const months = generationInput.months || 24;
    const countryKey = generationInput.country || detectCountry(goal);
    const config = GLOBAL_100[countryKey] || GLOBAL_100['default'];
    const isDefaultScenario = countryKey === 'default' && !generationInput.forcedTemplateId && !generationInput.useAI;

    // 2. Select Template Logic
    let selectedTemplate: ScenarioTemplate | null = null;
    let usedAI = false;

    // CASE A: Explicit AI Generation Mode (from Admin or specific trigger)
    if (generationInput.useAI && process.env.API_KEY) {
        setAiGenerating(true);
        try {
           const aiTemplate = await generateNewScenarioTemplate(generationInput);
           if (aiTemplate) {
              selectedTemplate = aiTemplate;
              // Save the new template for permanent storage
              setTemplates(prev => [aiTemplate, ...prev]);
              setToastMessage("🤖 AI가 생성한 새 템플릿이 영구 저장되었습니다.");
              usedAI = true;
           }
        } catch (e) {
           console.error("Forced AI Generation failed", e);
           setToastMessage("❌ AI 생성 실패. 기존 템플릿을 사용합니다.");
        }
        setAiGenerating(false);
    }

    // CASE B: Forced Template ID (Pre-linked in Admin)
    if (!selectedTemplate && generationInput.forcedTemplateId) {
      selectedTemplate = templates.find(t => t.id === generationInput.forcedTemplateId) || null;
    }

    // CASE C: Intelligent Matching (Fallback)
    if (!selectedTemplate) {
        const jobLower = job.toLowerCase();
        const goalLower = goal.toLowerCase();

        // Find by tags
        selectedTemplate = templates.find(t => {
             const hasGoal = t.tags.some(tag => goalLower.includes(tag));
             const hasFamily = generationInput.family ? t.tags.some(tag => generationInput.family?.toLowerCase().includes(tag)) : true;
             return hasGoal && hasFamily;
        }) || null;

        // Fallback: Just goal matching
        if (!selectedTemplate) {
            selectedTemplate = templates.find(t => t.tags.some(tag => goalLower.includes(tag))) || null;
        }

        // Final Fallback: AI (if not explicitly disabled and API key exists and goal is valid)
        if (!selectedTemplate && process.env.API_KEY && goal !== '미지정') {
           setAiGenerating(true);
           try {
              const aiTemplate = await generateNewScenarioTemplate(generationInput);
              if (aiTemplate) {
                 selectedTemplate = aiTemplate;
                 setTemplates(prev => [aiTemplate, ...prev]);
                 setToastMessage("🤖 새로운 패턴 발견! AI가 분석하여 저장했습니다.");
                 usedAI = true;
              }
           } catch (e) { console.error(e); }
           setAiGenerating(false);
        }
    }

    // Final Safe Fallback
    if (!selectedTemplate) {
      selectedTemplate = templates.find(t => t.id === 'template_default') || templates[0];
    }

    // 3. Inject Variables
    const inject = (text?: string) => {
      if (!text) return "";
      return text
        .replace(/{age}/g, age)
        .replace(/{job}/g, job)
        .replace(/{start}/g, start)
        .replace(/{goal}/g, goal)
        .replace(/{months}/g, months.toString())
        .replace(/{currency}/g, config.currency)
        .replace(/{prop}/g, config.prop)
        .replace(/{bank}/g, config.bank)
        .replace(/{visa}/g, config.visaName)
        .replace(/{family}/g, generationInput.family || '가족')
        .replace(/{moveType}/g, generationInput.moveType || '이동');
    };

    const randInt = (min: number, max: number) => Math.floor(Math.random() * (max - min + 1)) + min;

    // 4. Generate Result Table
    let resultTable: ComparisonRow[] = [];

    if (selectedTemplate.resultTable) {
      resultTable = selectedTemplate.resultTable.map(row => ({
        item: inject(row.item),
        before: inject(row.before),
        after: inject(row.after),
        diff: inject(row.diff)
      }));
    } else {
      resultTable = [
          { item: '월 생활비', before: `${config.currency} 4,500`, after: `${config.currency} 3,200`, diff: `-1,300` },
          { item: '자산', before: '유동성 부족', after: '환차익 발생', diff: `+${randInt(1, 15)}%` },
          { item: '의료비', before: '보험 적용', after: '사립 병원', diff: '+200%' },
          { item: '순 저축', before: '100', after: '350', diff: '+250' }
      ];
    }

    // 5. Generate Essay
    const defaultEssay: EssayData = {
      title: `${goal}의 현실: 숫자가 말해주지 않는 것들`,
      intro: `${start}를 떠나 ${goal}로 향하는 당신의 발걸음은 가볍겠지만, 현실의 무게는 결코 가볍지 않습니다.`,
      body: "우리는 종종 장소만 바뀌면 삶이 바뀔 것이라 착각합니다. 하지만 당신이 가져가는 것은 짐가방뿐만이 아닙니다. 당신의 불안과 습관도 국경을 넘습니다."
    };

    const essayData: EssayData = selectedTemplate.essay ? {
      title: inject(selectedTemplate.essay.title),
      intro: inject(selectedTemplate.essay.intro),
      body: inject(selectedTemplate.essay.body)
    } : defaultEssay;

    // 6. Generate Downloads
    const downloads: DownloadableResource[] = selectedTemplate.downloads ? selectedTemplate.downloads.map(d => ({
      ...d,
      title: inject(d.title),
      description: inject(d.description),
      triggerUrl: inject(d.triggerUrl)
    })) : [];

    const scenarioData: ScenarioData = {
        success: randInt(40, 95),
        salary: config.avgSalary,
        visa: config.visaName,
        living: randInt(100, 450), 
        story: {
            header: inject(selectedTemplate.story.titleTemplate),
            subHeader: inject(selectedTemplate.story.subTemplate),
            stages: selectedTemplate.story.stages.map(s => ({
              label: s.label,
              title: inject(s.title),
              situation: inject(s.content.situation),
              thought: inject(s.content.thought),
              action: inject(s.content.action),
              experiment: inject(s.content.experiment),
              failure: inject(s.content.failure),
              question: inject(s.content.question),
              solution: inject(s.content.solution),
              result: inject(s.content.result),
              reality: inject(s.content.reality),
            })) as [any, any, any, any]
        },
        resultTable: resultTable,
        additionalInfo: {
            obstacles: ['현지 규제', '환율 변동', '언어 장벽'],
            nextSteps: [
                { label: '구글 검색', value: `${start} 은퇴자 ${goal} 비자 후기` },
                { label: '유튜브', value: `${goal} 현지 물가 브이로그` },
                { label: 'PDF 다운로드', value: `${goal} 정착 가이드` }
            ]
        },
        essay: essayData,
        downloads: downloads,
        visaInfoUrl: config.visaInfoUrl,
    };

    const title = scenarioData.story.header;
    const progress = randInt(50, 92);

    const newResult: StoryResult = {
      title,
      scenarioData,
      progress,
      userInput: generationInput,
      timestamp: new Date().toLocaleTimeString(),
      isDefault: isDefaultScenario && !usedAI,
    };

    setResult(newResult);
    setLoading(false);

    localStorage.setItem('lastStory', JSON.stringify({ input: newResult.userInput }));

    if (window.innerWidth < 1024) {
        setTimeout(() => {
          const resultEl = document.getElementById('result-anchor');
          if (resultEl) resultEl.scrollIntoView({ behavior: 'smooth', block: 'start' });
        }, 100);
    }
  }, [templates, db]);

  const handleGenerateFromPrompt = async (parsedData: Partial<UserInput>, rawText?: string) => {
    let finalInput: UserInput = {
      age: '', job: '', start: '', goal: '', months: 24, country: '', forcedTemplateId: '', family: '', moveType: '', assets: '', useAI: false,
      ...parsedData
    };

    if (rawText && rawText.length > 10 && process.env.API_KEY) {
        setAiAnalyzing(true);
        try {
            const deepAnalysis = await parseUserPrompt(rawText);
            finalInput = { ...finalInput, ...deepAnalysis };
        } catch (e) {
            console.error("Deep analysis failed, using regex fallback");
        }
        setAiAnalyzing(false);
    }

    setInput(finalInput);
    generateStory(finalInput);
  };

  const handleRandom = () => {
    // Safety check: ensure randomSamples is array
    const samples = Array.isArray(db.randomSamples) ? db.randomSamples : [];
    if (samples.length === 0) {
      setToastMessage("🎲 예시 데이터가 없어 기본 예시를 복구합니다.");
      setDb(prev => ({...prev, randomSamples: INITIAL_DB.randomSamples}));
      setTimeout(() => handleRandom(), 100);
      return;
    }
    const random = samples[Math.floor(Math.random() * samples.length)];
    const baseInput: UserInput = {
      age: '', job: '', start: '', goal: '', months: 24, country: '', forcedTemplateId: '', family: '', moveType: '', assets: '', useAI: false
    };
    const finalInput = { ...baseInput, ...random };

    setInput(finalInput);
    setToastMessage("🎲 랜덤 시나리오를 구성했습니다.");
    setTimeout(() => generateStory(finalInput), 500);
  };

  const handleDownload = () => {
    if (result) {
      downloadPDFElement('pdf-content', `희망구매_${result.userInput.goal}_${Date.now()}`);
      setToastMessage("📄 리포트가 PDF로 저장되었습니다.");
    }
  };

  const handleSearch = (type: 'google' | 'youtube') => {
    const qGoal = input.goal || '이민';
    const qJob = input.job || '취업';
    const url = type === 'google' 
      ? `https://google.com/search?q=${input.age}세 ${qGoal} ${qJob} 현실 비용`
      : `https://youtube.com/results?search_query=${qGoal} ${qJob} 브이로그`;
    window.open(url);
  };

  return (
    <div className="min-h-screen bg-[#0f172a] text-white font-sans selection:bg-emerald-500 selection:text-white">
       <div className="fixed inset-0 overflow-hidden pointer-events-none">
          <div className="absolute top-[-10%] right-[-10%] w-[500px] h-[500px] bg-indigo-600/20 rounded-full blur-[100px]"></div>
          <div className="absolute bottom-[-10%] left-[-10%] w-[500px] h-[500px] bg-emerald-600/10 rounded-full blur-[100px]"></div>
       </div>

      <div className="relative w-full max-w-[1400px] mx-auto min-h-screen flex flex-col pb-safe px-4 md:px-6 lg:px-8">

        <div className="pt-4 md:pt-8 pb-6">
           <Header 
             scenarioCount={templates.length} 
             lastVerified={db.lastVerified}
             onAdminClick={() => setShowAdminLogin(true)}
           />
        </div>

        <div className="flex-1 grid grid-cols-1 lg:grid-cols-12 gap-6 lg:gap-8 items-start">

            <div className="lg:col-span-4 space-y-6 sticky top-8">
                <InputForm 
                  input={input}
                  onChange={handleInputChange}
                  onGenerate={handleGenerateFromPrompt}
                  onRandom={handleRandom}
                  onDownload={handleDownload}
                  canDownload={!!result}
                  isGenerating={loading || aiAnalyzing}
                />

                <div className="hidden lg:block space-y-6">
                    <ActionButtons 
                      onGoogleSearch={() => handleSearch('google')}
                      onYoutubeSearch={() => handleSearch('youtube')}
                      onRandom={handleRandom}
                      onRefresh={() => window.location.reload()}
                      onReward={() => {}} 
                    />
                    <AdBanner />
                </div>
            </div>

            <div className="lg:col-span-8 space-y-6">
                <div id="result-anchor"></div>

                {!result && !loading && !aiAnalyzing && (
                    <div className="hidden lg:flex h-full min-h-[400px] items-center justify-center border-2 border-dashed border-white/10 rounded-3xl bg-white/5 text-gray-400">
                        <div className="text-center p-8">
                            <div className="text-4xl mb-4">👈</div>
                            <h3 className="text-xl font-bold mb-2">시뮬레이션을 시작하세요</h3>
                            <p className="text-sm">구체적으로 입력할수록 AI가<br/>더 정밀한 미래를 예측합니다.</p>
                        </div>
                    </div>
                )}

                <ResultSection 
                    result={result} 
                    loading={loading} 
                    extraEssays={db.essays} 
                />

                {aiAnalyzing && (
                    <div className="absolute inset-0 z-20 bg-[#0f172a]/90 backdrop-blur-md flex items-center justify-center rounded-3xl">
                        <div className="text-center space-y-4 p-8">
                             <div className="w-16 h-16 border-4 border-emerald-500 border-t-transparent rounded-full animate-spin mx-auto"></div>
                             <div>
                                 <h3 className="text-xl font-bold text-transparent bg-clip-text bg-gradient-to-r from-emerald-400 to-teal-400 animate-pulse">
                                     Deep Prompt Analysis...
                                 </h3>
                                 <p className="text-sm text-gray-400 mt-2">
                                     입력하신 내용의 의도를 파악하고 있습니다.<br/>(가족 구성원, 이사 목적, 예산 규모 등)
                                 </p>
                             </div>
                        </div>
                    </div>
                )}

                {loading && aiGenerating && (
                    <div className="absolute inset-0 z-20 bg-[#0f172a]/90 backdrop-blur-md flex items-center justify-center rounded-3xl">
                        <div className="text-center space-y-4 p-8">
                             <div className="w-16 h-16 border-4 border-indigo-500 border-t-transparent rounded-full animate-spin mx-auto"></div>
                             <div>
                                 <h3 className="text-xl font-bold text-transparent bg-clip-text bg-gradient-to-r from-indigo-400 to-purple-400 animate-pulse">
                                     Creating New Scenario...
                                 </h3>
                                 <p className="text-sm text-gray-400 mt-2">
                                     '{input.goal}'에 대한 맞춤형 템플릿을 생성 중입니다.<br/>
                                     분석된 결과는 영구 보존됩니다.
                                 </p>
                             </div>
                        </div>
                    </div>
                )}

                <div className="lg:hidden space-y-6">
                    <AdBanner />
                    <ActionButtons 
                      onGoogleSearch={() => handleSearch('google')}
                      onYoutubeSearch={() => handleSearch('youtube')}
                      onRandom={handleRandom}
                      onRefresh={() => window.location.reload()}
                      onReward={() => {}} 
                    />
                </div>
            </div>
        </div>

        <div className="h-12"></div>
      </div>

      {showAdminLogin && (
          <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/80 backdrop-blur-md p-6">
            <GlassCard className="p-8 w-full max-w-sm text-center space-y-6 border border-white/20">
              <h2 className="text-2xl font-bold bg-gradient-to-r from-white to-gray-400 bg-clip-text text-transparent">System Access</h2>
              <input 
                type="password" 
                value={adminPassword}
                onChange={(e) => setAdminPassword(e.target.value)}
                onKeyDown={(e) => e.key === 'Enter' && handleAdminLogin()}
                className="w-full p-4 bg-white/5 rounded-xl text-center text-xl font-bold border border-white/10 focus:border-emerald-500 focus:outline-none transition-colors"
                placeholder="Passcode"
                autoFocus
              />
              <div className="flex gap-4">
                <button onClick={() => setShowAdminLogin(false)} className="flex-1 py-3 bg-gray-700/50 hover:bg-gray-700 rounded-xl transition-colors font-medium">Cancel</button>
                <button onClick={handleAdminLogin} className="flex-1 py-3 bg-emerald-600 hover:bg-emerald-500 rounded-xl transition-colors font-bold shadow-lg shadow-emerald-900/50">Enter</button>
              </div>
            </GlassCard>
          </div>
      )}

      {isAdmin && (
        <AdminDashboard 
          db={db} 
          onUpdateDb={setDb} 
          templates={templates} 
          onUpdateTemplates={setTemplates}
          onClose={() => setIsAdmin(false)} 
        />
      )}

      <Toast message={toastMessage} onClose={() => setToastMessage(null)} />
    </div>
  );
}

export default App;

import React, { useState, useEffect } from 'react';
import { GlassCard } from './GlassCard';
import { ScenarioDB, ScenarioTemplate, DownloadableResource, UserInput, StandaloneEssay } from '../types';
import { DEFAULT_TEMPLATES } from '../constants';
import { generateBatchRandomSamples, generateNewScenarioTemplate, suggestNewScenarioTopics, validateSystemData } from '../aiService';
import { ApiKeyModal } from './ApiKeyModal';

interface AdminDashboardProps {
  db: ScenarioDB;
  onUpdateDb: React.Dispatch<React.SetStateAction<ScenarioDB>>;
  templates: ScenarioTemplate[];
  onUpdateTemplates: React.Dispatch<React.SetStateAction<ScenarioTemplate[]>>;
  onClose: () => void;
}

// --- Data Export Modal (Improved UI for Visibility) ---
const DataExportModal: React.FC<{ 
    isOpen: boolean; 
    onClose: () => void; 
    db: ScenarioDB; 
    templates: ScenarioTemplate[];
    onRestore: (data: { db: ScenarioDB, templates: ScenarioTemplate[] }) => void;
}> = ({ isOpen, onClose, db, templates, onRestore }) => {
    const [copied, setCopied] = useState(false);
    const [activeTab, setActiveTab] = useState<'code' | 'backup'>('backup');

    if (!isOpen) return null;

    const exportCode = `
// --- PASTE THIS INTO constants.ts TO SAVE PERMANENTLY ---

import { ScenarioDB, ScenarioTemplate } from './types';

export const DEFAULT_TEMPLATES: ScenarioTemplate[] = ${JSON.stringify(templates, null, 2)};

export const INITIAL_DB: ScenarioDB = ${JSON.stringify(db, null, 2)};
    `;

    const handleCopy = () => {
        navigator.clipboard.writeText(exportCode);
        setCopied(true);
        setTimeout(() => setCopied(false), 2000);
    };

    const handleDownloadJson = () => {
        const fullBackup = {
            timestamp: new Date().toISOString(),
            db,
            templates
        };
        const element = document.createElement("a");
        const file = new Blob([JSON.stringify(fullBackup, null, 2)], {type: 'application/json'});
        element.href = URL.createObjectURL(file);
        element.download = `HOPE_BACKUP_${new Date().toISOString().slice(0,10)}.json`;
        document.body.appendChild(element); 
        element.click();
        document.body.removeChild(element);
    };

    const handleFileRestore = (e: React.ChangeEvent<HTMLInputElement>) => {
        const fileReader = new FileReader();
        if (e.target.files && e.target.files[0]) {
            fileReader.readAsText(e.target.files[0], "UTF-8");
            fileReader.onload = (event) => {
                try {
                    const json = JSON.parse(event.target?.result as string);
                    if (json.db && json.templates) {
                        if(confirm(`백업 파일(${json.timestamp})로 복구하시겠습니까? 현재 데이터는 덮어씌워집니다.`)) {
                            onRestore({ db: json.db, templates: json.templates });
                            onClose();
                            alert("✅ 복구 완료되었습니다.");
                        }
                    } else {
                        alert("❌ 올바르지 않은 백업 파일 형식입니다.");
                    }
                } catch (err) {
                    alert("❌ 파일 읽기 실패");
                }
            };
        }
    };

    return (
        <div className="fixed inset-0 z-[100] flex items-center justify-center bg-black/90 backdrop-blur-md p-4 animate-fade-in">
            <GlassCard className="w-full max-w-4xl h-[85vh] flex flex-col p-6 border-l-4 border-l-blue-500 shadow-2xl relative">
                <button onClick={onClose} className="absolute top-4 right-4 text-gray-400 hover:text-white p-2">✕</button>

                <div className="mb-4">
                    <h2 className="text-xl md:text-2xl font-bold text-white flex items-center gap-2">
                        💾 데이터 백업 & 복구
                    </h2>
                    <div className="flex gap-4 mt-4 border-b border-white/10">
                        <button onClick={() => setActiveTab('backup')} className={`pb-2 px-2 text-sm font-bold transition-colors ${activeTab === 'backup' ? 'text-blue-400 border-b-2 border-blue-400' : 'text-gray-400'}`}>파일 관리 (JSON)</button>
                        <button onClick={() => setActiveTab('code')} className={`pb-2 px-2 text-sm font-bold transition-colors ${activeTab === 'code' ? 'text-blue-400 border-b-2 border-blue-400' : 'text-gray-400'}`}>개발자용 코드</button>
                    </div>
                </div>

                <div className="flex-1 overflow-y-auto pr-2">
                {activeTab === 'backup' ? (
                     <div className="grid grid-cols-1 md:grid-cols-2 gap-6 p-4">
                        {/* Download Section */}
                        <div className="bg-white/5 rounded-xl p-6 border border-white/10 flex flex-col items-center text-center space-y-4">
                            <div className="text-4xl">⬇️</div>
                            <h3 className="text-lg font-bold text-white">데이터 내보내기</h3>
                            <p className="text-xs text-gray-400 h-10">
                                현재 상태(템플릿, 에세이 등)를 JSON 파일로 저장합니다.
                            </p>
                            <button onClick={handleDownloadJson} className="w-full py-3 bg-emerald-600 hover:bg-emerald-500 rounded-xl font-bold text-white text-sm shadow-lg transition-transform hover:scale-105">
                                파일 다운로드 (.json)
                            </button>
                        </div>

                        {/* Upload Section */}
                        <div className="bg-white/5 rounded-xl p-6 border border-white/10 flex flex-col items-center text-center space-y-4">
                            <div className="text-4xl">⬆️</div>
                            <h3 className="text-lg font-bold text-white">데이터 불러오기</h3>
                            <p className="text-xs text-gray-400 h-10">
                                저장해둔 JSON 파일을 업로드하여 복구합니다.
                            </p>
                            <label className="w-full py-3 bg-blue-600/20 hover:bg-blue-600/30 border border-blue-500/50 rounded-xl font-bold text-blue-300 text-sm cursor-pointer transition-colors text-center block">
                                파일 선택 및 복구
                                <input type="file" accept=".json" onChange={handleFileRestore} className="hidden" />
                            </label>
                        </div>

                        <div className="md:col-span-2 bg-yellow-500/10 border border-yellow-500/20 p-4 rounded-xl text-xs text-yellow-200 text-center">
                            💡 팁: 업데이트 전에는 반드시 파일을 다운로드해 두세요.
                        </div>
                     </div>
                ) : (
                    <div className="bg-black/50 rounded-xl border border-white/10 h-full flex flex-col">
                        <div className="flex justify-between items-center p-2 bg-white/5 border-b border-white/10">
                            <span className="text-xs font-mono text-gray-500 ml-2">constants.ts export</span>
                            <button 
                                onClick={handleCopy}
                                className={`px-4 py-1.5 rounded-lg text-xs font-bold transition-all ${copied ? 'bg-green-500 text-white' : 'bg-blue-600 hover:bg-blue-500 text-white'}`}
                            >
                                {copied ? "✅ 복사 완료!" : "📋 코드 전체 복사"}
                            </button>
                        </div>
                        <textarea 
                            readOnly
                            value={exportCode}
                            className="flex-1 bg-transparent p-4 text-xs font-mono text-blue-200 resize-none focus:outline-none"
                        />
                    </div>
                )}
                </div>
            </GlassCard>
        </div>
    );
};

const RandomSampleEditor: React.FC<{db: ScenarioDB, onUpdateDb: React.Dispatch<React.SetStateAction<ScenarioDB>>, templates: ScenarioTemplate[]}> = ({ db, onUpdateDb, templates }) => {
    // Safety check: ensure db.randomSamples is an array
    const [samples, setSamples] = useState<Partial<UserInput>[]>(Array.isArray(db.randomSamples) ? db.randomSamples : []);

    useEffect(() => {
        if(Array.isArray(db.randomSamples)) {
            setSamples(db.randomSamples);
        } else {
            setSamples([]);
        }
    }, [db.randomSamples]);

    const handleUpdate = (index: number, field: keyof UserInput, value: string | number | boolean) => {
        const newSamples = [...samples];
        if (newSamples[index]) {
            newSamples[index] = { ...newSamples[index], [field]: value };
             if (field === 'useAI' && value === true) {
                newSamples[index].forcedTemplateId = '';
            }
            setSamples(newSamples);
        }
    };

    const handleSave = () => {
        onUpdateDb(prev => ({ ...prev, randomSamples: samples }));
        alert("✅ 저장되었습니다.");
    };

    const handleAdd = () => {
        setSamples([...samples, { age: '30', job: '직장인', start: '서울', goal: '미국', months: 24, forcedTemplateId: '', isDomestic: false, useAI: false }]);
    };

    const handleRemove = (index: number) => {
        if (confirm('이 예시를 삭제하시겠습니까?')) {
            const newSamples = [...samples];
            newSamples.splice(index, 1);
            setSamples(newSamples);
        }
    };

    return (
        <div className="h-full overflow-y-auto p-6 md:p-8 space-y-6 pb-20">
            <GlassCard className="p-6 border-l-4 border-l-purple-500">
                 <div className="flex justify-between items-center mb-6">
                    <div>
                        <h3 className="text-xl font-bold flex items-center gap-2">
                           🔀 랜덤 예시 설정
                           <span className="text-xs bg-purple-500/20 text-purple-300 px-2 py-1 rounded-full">{samples.length}개</span>
                        </h3>
                    </div>
                    <button onClick={handleSave} className="px-6 py-2 bg-emerald-600 hover:bg-emerald-500 rounded-xl font-bold text-white text-sm">
                        저장
                    </button>
                 </div>

                 <div className="grid gap-4">
                    {samples.map((sample, index) => (
                         <div key={index} className="bg-white/5 border border-white/10 rounded-xl p-4 relative">
                            <button onClick={() => handleRemove(index)} className="absolute top-2 right-2 text-red-500 font-bold hover:text-white">✕</button>
                            <div className="grid grid-cols-2 md:grid-cols-6 gap-3">
                                <input value={sample.age || ''} onChange={(e) => handleUpdate(index, 'age', e.target.value)} className="bg-black/30 p-2 rounded text-sm text-white" placeholder="나이" />
                                <input value={sample.job || ''} onChange={(e) => handleUpdate(index, 'job', e.target.value)} className="bg-black/30 p-2 rounded text-sm text-white" placeholder="직업" />
                                <input value={sample.start || ''} onChange={(e) => handleUpdate(index, 'start', e.target.value)} className="bg-black/30 p-2 rounded text-sm text-white" placeholder="출발" />
                                <input value={sample.goal || ''} onChange={(e) => handleUpdate(index, 'goal', e.target.value)} className="bg-black/30 p-2 rounded text-sm text-white" placeholder="도착" />
                                <select value={sample.isDomestic ? 'domestic' : 'intl'} onChange={(e) => handleUpdate(index, 'isDomestic', e.target.value === 'domestic')} className="bg-black/30 p-2 rounded text-sm text-white">
                                    <option value="intl">해외</option>
                                    <option value="domestic">국내</option>
                                </select>
                                <div className="flex items-center gap-2">
                                     <input type="checkbox" checked={!!sample.useAI} onChange={(e) => handleUpdate(index, 'useAI', e.target.checked)} className="w-4 h-4" />
                                     <span className={`text-xs ${sample.useAI ? 'text-emerald-400 font-bold' : 'text-gray-400'}`}>AI 생성</span>
                                </div>
                            </div>
                         </div>
                    ))}
                    <button onClick={handleAdd} className="w-full py-3 bg-white/5 rounded-xl text-gray-400 hover:text-white border border-dashed border-white/20">+ 추가</button>
                 </div>
            </GlassCard>
        </div>
    );
};

const EssayEditor: React.FC<{ db: ScenarioDB; onUpdateDb: React.Dispatch<React.SetStateAction<ScenarioDB>> }> = ({ db, onUpdateDb }) => {
    // Safety check: ensure db.essays is an array
    const [essays, setEssays] = useState<StandaloneEssay[]>(Array.isArray(db.essays) ? db.essays : []);
    const [editingId, setEditingId] = useState<string | null>(null);
    const [formData, setFormData] = useState<StandaloneEssay>({ id: '', title: '', content: '', tags: [], date: '' });

    useEffect(() => {
        if(Array.isArray(db.essays)) {
            setEssays(db.essays);
        } else {
            setEssays([]);
        }
    }, [db.essays]);

    const handleCreate = () => {
        setEditingId('new');
        setFormData({ id: `essay_${Date.now()}`, title: '', content: '', tags: [], date: new Date().toLocaleDateString() });
    };

    const handleSave = () => {
        onUpdateDb(prev => {
            const current = Array.isArray(prev.essays) ? prev.essays : [];
            const updated = editingId === 'new' 
                ? [formData, ...current] 
                : current.map(e => e.id === formData.id ? formData : e);
            return { ...prev, essays: updated };
        });
        setEditingId(null);
    };

    return (
        <div className="h-full flex flex-col md:flex-row gap-6 p-6">
            <div className="w-full md:w-1/3 space-y-4">
                <button onClick={handleCreate} className="w-full py-3 bg-indigo-600 hover:bg-indigo-500 rounded-xl font-bold text-white">+ 새 칼럼 작성</button>
                <div className="space-y-2 h-[400px] overflow-y-auto">
                    {essays.map(essay => (
                        <div key={essay.id} className="p-4 bg-white/5 hover:bg-white/10 rounded-xl cursor-pointer" onClick={() => { setEditingId(essay.id); setFormData(essay); }}>
                            <h4 className="font-bold text-sm text-white truncate">{essay.title}</h4>
                        </div>
                    ))}
                </div>
            </div>
            <div className="w-full md:w-2/3 bg-black/20 rounded-xl p-6">
                {editingId ? (
                    <div className="flex flex-col h-full space-y-4">
                        <input value={formData.title} onChange={e => setFormData({...formData, title: e.target.value})} className="bg-transparent text-xl font-bold text-white border-b border-white/10 pb-2" placeholder="제목" />
                        <textarea value={formData.content} onChange={e => setFormData({...formData, content: e.target.value})} className="flex-1 bg-transparent text-sm text-gray-300 resize-none p-4 border border-white/5 rounded-lg h-[300px]" placeholder="내용" />
                        <div className="flex justify-end gap-2">
                            <button onClick={() => setEditingId(null)} className="px-4 py-2 text-xs font-bold text-gray-400">취소</button>
                            <button onClick={handleSave} className="px-6 py-2 bg-emerald-600 text-white text-xs font-bold rounded-lg">저장</button>
                        </div>
                    </div>
                ) : (
                    <div className="h-full flex items-center justify-center text-gray-500">글을 선택하거나 작성하세요.</div>
                )}
            </div>
        </div>
    );
};

export const AdminDashboard: React.FC<AdminDashboardProps> = ({ 
  db, 
  onUpdateDb, 
  templates, 
  onUpdateTemplates, 
  onClose 
}) => {
  const [activeTab, setActiveTab] = useState<'control' | 'templates' | 'samples' | 'essays'>('control');
  const [logs, setLogs] = useState<string[]>([]);
  const [aiMaintenance, setAiMaintenance] = useState({ updateTemplates: false, updateSamples: false, validate: false });
  const [batchSize, setBatchSize] = useState<number>(3); 
  const [aiRunning, setAiRunning] = useState(false);
  const [showKeyModal, setShowKeyModal] = useState(false);
  const [showExportModal, setShowExportModal] = useState(false);

  const addLog = (msg: string) => {
    const timestamp = new Date().toLocaleTimeString();
    setLogs(prev => [`[${timestamp}] ${msg}`, ...prev]);
  };

  const handleRestore = (data: { db: ScenarioDB, templates: ScenarioTemplate[] }) => {
    onUpdateDb(data.db);
    onUpdateTemplates(data.templates);
    // Explicitly save to local storage immediately
    localStorage.setItem('app_db', JSON.stringify(data.db));
    localStorage.setItem('app_templates', JSON.stringify(data.templates));
  };

  const handleRestoreDefaults = () => {
    if(confirm("기본 템플릿 4개(포르투갈, 발리, 강남, 기본)를 강제로 복원하시겠습니까? 기존 템플릿 목록에 추가됩니다.")) {
        onUpdateTemplates(prev => {
            const currentIds = prev.map(t => t.id);
            const defaultsToAdd = DEFAULT_TEMPLATES.filter(dt => !currentIds.includes(dt.id));
            if (defaultsToAdd.length === 0) {
                alert("이미 기본 템플릿이 모두 존재합니다.");
                return prev;
            }
            return [...defaultsToAdd, ...prev];
        });
        alert("✅ 복원 완료되었습니다.");
    }
  };

  const runAIMaintenance = async () => {
    setAiRunning(true);
    addLog(`🚀 AI 자동 유지보수 시작 (Batch Size: ${batchSize})...`);

    try {
        const generatedTemplates: ScenarioTemplate[] = [];
        const generatedSamples: Partial<UserInput>[] = [];

        if (aiMaintenance.validate) {
            addLog("🔍 데이터 정합성 검사 중...");
            const report = await validateSystemData(db, templates);
            if (Array.isArray(report)) {
                report.forEach(r => addLog(`📋 [리포트] ${r}`));
            } else {
                addLog("⚠️ 검증 결과 형식이 올바르지 않습니다.");
            }
        }

        if (aiMaintenance.updateSamples) {
            addLog(`🎲 ${batchSize}개의 새로운 랜덤 예시 생성 중...`);
            const newSamples = await generateBatchRandomSamples(batchSize); 
            if (newSamples.length > 0) {
                generatedSamples.push(...newSamples);
                addLog(`✅ 랜덤 예시 ${newSamples.length}개 생성 성공`);
            }
        }

        if (aiMaintenance.updateTemplates) {
            addLog(`🧠 부족한 시나리오 주제 분석 중...`);
            const allTags = templates.flatMap(t => t.tags);
            const topicIdeas = await suggestNewScenarioTopics(allTags, batchSize);

            for (let i = 0; i < topicIdeas.length; i++) {
                const idea = topicIdeas[i];
                addLog(`[${i + 1}/${topicIdeas.length}] ✍️ 템플릿 작성 중: ${idea.goal}...`);
                const newTemplate = await generateNewScenarioTemplate(idea as UserInput);
                if (newTemplate) generatedTemplates.push(newTemplate);
            }
        }

        // Safe State Updates with explicit array checks to avoid 'number 0 is not iterable'
        if (generatedSamples.length > 0) {
            onUpdateDb(prev => ({
                 ...prev, 
                 randomSamples: [...generatedSamples, ...(Array.isArray(prev.randomSamples) ? prev.randomSamples : [])].slice(0, 50) 
            }));
            addLog(`💾 시스템 DB에 랜덤 예시 업데이트 완료.`);
        }

        if (generatedTemplates.length > 0) {
            onUpdateTemplates(prev => [...generatedTemplates, ...prev]);
            addLog(`💾 시스템 DB에 템플릿 업데이트 완료.`);
        }

        addLog("🏁 모든 작업 완료.");

    } catch (e: any) {
        console.error(e);
        addLog(`❌ 오류 발생: ${e.message}`);
    } finally {
        setAiRunning(false);
    }
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/80 backdrop-blur-md p-4 animate-fade-in">
      <GlassCard className="w-full max-w-6xl h-[90vh] flex flex-col bg-[#111827] border-white/20 shadow-2xl overflow-hidden">
        {/* Header */}
        <div className="p-6 border-b border-white/10 flex justify-between items-center bg-black/20">
          <div>
             <h2 className="text-2xl font-black text-white flex items-center gap-2">
                <span className="text-3xl">⚙️</span> SYSTEM ADMIN
             </h2>
             <p className="text-xs text-emerald-400 font-mono mt-1">
                Connected: {new Date().toLocaleDateString()}
             </p>
          </div>
          <div className="flex gap-2">
            <button 
                onClick={() => {
                   if(confirm("정말로 모든 데이터를 초기화하시겠습니까? (로컬 데이터 삭제 후 새로고침)")) {
                       localStorage.removeItem('app_db');
                       localStorage.removeItem('app_templates');
                       window.location.reload();
                   }
                }}
                className="px-4 py-2 bg-red-600/20 text-red-400 border border-red-500/50 rounded-lg text-xs font-bold hover:bg-red-600/30 transition-colors flex items-center gap-2"
            >
                🔄 초기화
            </button>
            <button 
                onClick={() => setShowExportModal(true)}
                className="px-4 py-2 bg-blue-600/20 text-blue-400 border border-blue-500/50 rounded-lg text-xs font-bold hover:bg-blue-600/30 transition-colors flex items-center gap-2"
            >
                💾 백업/복구
            </button>
            <button 
                onClick={() => setShowKeyModal(true)}
                className="px-4 py-2 bg-yellow-600/20 text-yellow-500 border border-yellow-600/50 rounded-lg text-xs font-bold hover:bg-yellow-600/30 transition-colors flex items-center gap-2"
            >
                🔑 API 키
            </button>
            <button onClick={onClose} className="w-10 h-10 rounded-full bg-white/10 hover:bg-white/20 flex items-center justify-center text-white transition-colors">
                ✕
            </button>
          </div>
        </div>

        {/* Tabs */}
        <div className="flex border-b border-white/10 bg-black/10">
           {['control', 'templates', 'samples', 'essays'].map(tab => (
               <button 
                 key={tab}
                 onClick={() => setActiveTab(tab as any)}
                 className={`px-8 py-4 text-sm font-bold uppercase transition-colors ${activeTab === tab ? 'bg-emerald-600/20 text-emerald-400 border-b-2 border-emerald-500' : 'text-gray-400 hover:text-white'}`}
               >
                 {tab}
               </button>
           ))}
        </div>

        {/* Content */}
        <div className="flex-1 overflow-hidden bg-[#0f172a]">
           {activeTab === 'control' && (
             <div className="p-8 h-full overflow-y-auto space-y-8">
                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                    <GlassCard className="p-6 border-l-4 border-l-emerald-500">
                        <h3 className="text-gray-400 text-xs font-bold uppercase tracking-wider mb-4">AI Auto-Maintenance</h3>
                        <div className="space-y-4 mb-6">
                            <label className="flex items-center gap-3"><input type="checkbox" checked={aiMaintenance.updateTemplates} onChange={e => setAiMaintenance({...aiMaintenance, updateTemplates: e.target.checked})} className="w-4 h-4" /> 템플릿 생성</label>
                            <label className="flex items-center gap-3"><input type="checkbox" checked={aiMaintenance.updateSamples} onChange={e => setAiMaintenance({...aiMaintenance, updateSamples: e.target.checked})} className="w-4 h-4" /> 예시 업데이트</label>
                            <label className="flex items-center gap-3"><input type="checkbox" checked={aiMaintenance.validate} onChange={e => setAiMaintenance({...aiMaintenance, validate: e.target.checked})} className="w-4 h-4" /> 데이터 검증</label>
                            <div className="pt-2">
                                <span className="text-xs text-gray-400">Batch Size: {batchSize}</span>
                                <input type="range" min="1" max="5" value={batchSize} onChange={e => setBatchSize(Number(e.target.value))} className="w-full" />
                            </div>
                        </div>
                        <div className="space-y-3">
                            <button onClick={runAIMaintenance} disabled={aiRunning} className="w-full py-3 bg-emerald-600 rounded-xl font-bold text-white shadow-lg">
                                {aiRunning ? 'AI 작업 중...' : '작업 실행'}
                            </button>

                            <button onClick={handleRestoreDefaults} className="w-full py-3 bg-indigo-600/30 hover:bg-indigo-600/50 border border-indigo-500/50 rounded-xl font-bold text-indigo-300 shadow-lg text-sm">
                                🛠 기본 템플릿(4종) 강제 복구
                            </button>
                        </div>
                    </GlassCard>

                    <GlassCard className="p-6 flex flex-col">
                        <h3 className="text-gray-400 text-xs font-bold uppercase tracking-wider mb-4">Logs</h3>
                        <div className="flex-1 bg-black/40 rounded-xl p-4 font-mono text-xs text-green-400 overflow-y-auto">
                            {logs.map((log, i) => <div key={i} className="mb-1">{log}</div>)}
                        </div>
                    </GlassCard>
                </div>
             </div>
           )}

           {activeTab === 'templates' && (
             <div className="p-8 text-center text-gray-400">
                 템플릿 편집 기능은 현재 점검 중입니다. (DB 업데이트 우선)
             </div>
           )}

           {activeTab === 'samples' && (
               <RandomSampleEditor db={db} onUpdateDb={onUpdateDb} templates={templates} />
           )}

           {activeTab === 'essays' && (
               <EssayEditor db={db} onUpdateDb={onUpdateDb} />
           )}
        </div>
      </GlassCard>

      <ApiKeyModal isOpen={showKeyModal} onClose={() => setShowKeyModal(false)} />
      <DataExportModal isOpen={showExportModal} onClose={() => setShowExportModal(false)} db={db} templates={templates} onRestore={handleRestore} />
    </div>
  );
};

import React, { useState, useEffect, useCallback } from 'react';
import { Header } from './components/Header';
import { InputForm } from './components/InputForm';
import { ResultSection, downloadPDFElement } from './components/ResultSection';
import { AdBanner } from './components/AdBanner';
import { ActionButtons } from './components/ActionButtons';
import { Toast } from './components/Toast';
import { AdminDashboard } from './components/AdminDashboard';
import { INITIAL_DB, GLOBAL_100, detectCountry, DEFAULT_TEMPLATES } from './constants';
import { UserInput, StoryResult, ScenarioDB, ScenarioData, ScenarioTemplate, ComparisonRow, EssayData, DownloadableResource } from './types';
import { GlassCard } from './components/GlassCard';
import { generateNewScenarioTemplate, parseUserPrompt } from './aiService';

function App() {
  // --- [CRITICAL FIX] Data Persistence Safety Layer ---
  // 사용자 데이터(에세이, 커스텀 템플릿)가 코드 업데이트로 인해 날아가지 않도록
  // LocalStorage 데이터를 최우선으로 하고, 기본값(DEFAULT_TEMPLATES)을 병합(Merge)합니다.

  const [db, setDb] = useState<ScenarioDB>(() => {
    try {
      const saved = localStorage.getItem('app_db');
      if (saved) {
        const parsed = JSON.parse(saved);

        // 데이터 병합: 기존 필드 유지 + 새 필드 추가
        // 중요: 사용자가 작성한 essays가 있다면 절대 덮어쓰지 않음
        const existingEssays = Array.isArray(parsed.essays) ? parsed.essays : [];
        const defaultEssays = Array.isArray(INITIAL_DB.essays) ? INITIAL_DB.essays : [];

        // 사용자가 작성한 데이터가 있으면 그것을 사용, 없으면 기본값 사용
        const mergedEssays = existingEssays.length > 0 ? existingEssays : defaultEssays;

        const existingSamples = Array.isArray(parsed.randomSamples) ? parsed.randomSamples : [];
        const defaultSamples = INITIAL_DB.randomSamples;
        const mergedSamples = existingSamples.length > 0 ? existingSamples : defaultSamples;

        return {
          ...INITIAL_DB, // 최신 코드의 구조(Schema)를 기반으로 함
          ...parsed,     // 로컬 저장소의 값을 덮어씀 (사용자 설정 우선)
          essays: mergedEssays, // 안전하게 병합된 에세이 리스트
          randomSamples: mergedSamples,
          scenarios: parsed.scenarios || {}
        };
      }
    } catch (e) {
      console.error("DB Load Error, resetting to default:", e);
    }
    return INITIAL_DB;
  });

  const [templates, setTemplates] = useState<ScenarioTemplate[]>(() => {
    try {
      const saved = localStorage.getItem('app_templates');
      if (saved) {
        const parsed = JSON.parse(saved);
        if (Array.isArray(parsed)) {
            // [FIX] 저장된 데이터가 있더라도, 내용이 0개거나 기본 템플릿들이 없으면 복구(Merge)
            const merged = [...parsed];

            // 만약 아예 비어있으면 기본값으로 대체
            if (merged.length === 0) return DEFAULT_TEMPLATES;

            DEFAULT_TEMPLATES.forEach(def => {
                // ID가 같은게 없으면 추가 (기본 템플릿 복구)
                if (!merged.find(t => t.id === def.id)) {
                    merged.push(def);
                }
            });
            return merged;
        }
      }
    } catch (e) {
      console.error("Templates Load Error, resetting:", e);
    }
    // 저장된 게 없으면 기본 4개 템플릿 사용
    return DEFAULT_TEMPLATES;
  });

  const [isAdmin, setIsAdmin] = useState(false);
  const [showAdminLogin, setShowAdminLogin] = useState(false);
  const [adminPassword, setAdminPassword] = useState('');

  const [input, setInput] = useState<UserInput>({
    age: '',
    job: '',
    start: '',
    goal: '',
    months: 24,
    country: '',
    forcedTemplateId: '',
    family: '',
    moveType: '',
    assets: '',
    useAI: false
  });
  const [result, setResult] = useState<StoryResult | null>(null);
  const [loading, setLoading] = useState(false);
  const [aiGenerating, setAiGenerating] = useState(false);
  const [aiAnalyzing, setAiAnalyzing] = useState(false);
  const [toastMessage, setToastMessage] = useState<string | null>(null);

  useEffect(() => {
    if (window.location.hash === '#admin') setShowAdminLogin(true);
  }, []);

  // Persist DB and Templates to LocalStorage
  useEffect(() => {
    localStorage.setItem('app_db', JSON.stringify(db));
  }, [db]);

  useEffect(() => {
    // 템플릿이 비어있으면 저장하지 않고, 오히려 복구 시도 (Safety)
    if (templates.length > 0) {
        localStorage.setItem('app_templates', JSON.stringify(templates));
    }
  }, [templates]);

  const handleAdminLogin = () => {
    if (adminPassword === '1234') {
      setIsAdmin(true);
      setShowAdminLogin(false);
      setToastMessage("🔓 관리자 모드로 접속했습니다.");
    } else {
      alert("비밀번호가 올바르지 않습니다.");
    }
  };

  const handleInputChange = (field: keyof UserInput, value: string | number) => {
    setInput(prev => ({ ...prev, [field]: value }));
  };

  const generateStory = useCallback(async (generationInput: UserInput) => {
    setLoading(true);
    setResult(null); 
    setAiGenerating(false);

    // 1. Prepare Variables
    const age = generationInput.age || '미지정';
    const job = generationInput.job || '미지정';
    const start = generationInput.start || '미지정';
    const goal = generationInput.goal || '미지정';
    const months = generationInput.months || 24;
    const countryKey = generationInput.country || detectCountry(goal);
    const config = GLOBAL_100[countryKey] || GLOBAL_100['default'];
    const isDefaultScenario = countryKey === 'default' && !generationInput.forcedTemplateId && !generationInput.useAI;

    // 2. Select Template Logic
    let selectedTemplate: ScenarioTemplate | null = null;
    let usedAI = false;

    // CASE A: Explicit AI Generation Mode (from Admin or specific trigger)
    if (generationInput.useAI && process.env.API_KEY) {
        setAiGenerating(true);
        try {
           const aiTemplate = await generateNewScenarioTemplate(generationInput);
           if (aiTemplate) {
              selectedTemplate = aiTemplate;
              // Save the new template for permanent storage
              setTemplates(prev => [aiTemplate, ...prev]);
              setToastMessage("🤖 AI가 생성한 새 템플릿이 영구 저장되었습니다.");
              usedAI = true;
           }
        } catch (e) {
           console.error("Forced AI Generation failed", e);
           setToastMessage("❌ AI 생성 실패. 기존 템플릿을 사용합니다.");
        }
        setAiGenerating(false);
    }

    // CASE B: Forced Template ID (Pre-linked in Admin)
    if (!selectedTemplate && generationInput.forcedTemplateId) {
      selectedTemplate = templates.find(t => t.id === generationInput.forcedTemplateId) || null;
    }

    // CASE C: Intelligent Matching (Fallback)
    if (!selectedTemplate) {
        const jobLower = job.toLowerCase();
        const goalLower = goal.toLowerCase();

        // Find by tags
        selectedTemplate = templates.find(t => {
             const hasGoal = t.tags.some(tag => goalLower.includes(tag));
             const hasFamily = generationInput.family ? t.tags.some(tag => generationInput.family?.toLowerCase().includes(tag)) : true;
             return hasGoal && hasFamily;
        }) || null;

        // Fallback: Just goal matching
        if (!selectedTemplate) {
            selectedTemplate = templates.find(t => t.tags.some(tag => goalLower.includes(tag))) || null;
        }

        // Final Fallback: AI (if not explicitly disabled and API key exists and goal is valid)
        if (!selectedTemplate && process.env.API_KEY && goal !== '미지정') {
           setAiGenerating(true);
           try {
              const aiTemplate = await generateNewScenarioTemplate(generationInput);
              if (aiTemplate) {
                 selectedTemplate = aiTemplate;
                 setTemplates(prev => [aiTemplate, ...prev]);
                 setToastMessage("🤖 새로운 패턴 발견! AI가 분석하여 저장했습니다.");
                 usedAI = true;
              }
           } catch (e) { console.error(e); }
           setAiGenerating(false);
        }
    }

    // Final Safe Fallback
    if (!selectedTemplate) {
      selectedTemplate = templates.find(t => t.id === 'template_default') || templates[0];
    }

    // 3. Inject Variables
    const inject = (text?: string) => {
      if (!text) return "";
      return text
        .replace(/{age}/g, age)
        .replace(/{job}/g, job)
        .replace(/{start}/g, start)
        .replace(/{goal}/g, goal)
        .replace(/{months}/g, months.toString())
        .replace(/{currency}/g, config.currency)
        .replace(/{prop}/g, config.prop)
        .replace(/{bank}/g, config.bank)
        .replace(/{visa}/g, config.visaName)
        .replace(/{family}/g, generationInput.family || '가족')
        .replace(/{moveType}/g, generationInput.moveType || '이동');
    };

    const randInt = (min: number, max: number) => Math.floor(Math.random() * (max - min + 1)) + min;

    // 4. Generate Result Table
    let resultTable: ComparisonRow[] = [];

    if (selectedTemplate.resultTable) {
      resultTable = selectedTemplate.resultTable.map(row => ({
        item: inject(row.item),
        before: inject(row.before),
        after: inject(row.after),
        diff: inject(row.diff)
      }));
    } else {
      resultTable = [
          { item: '월 생활비', before: `${config.currency} 4,500`, after: `${config.currency} 3,200`, diff: `-1,300` },
          { item: '자산', before: '유동성 부족', after: '환차익 발생', diff: `+${randInt(1, 15)}%` },
          { item: '의료비', before: '보험 적용', after: '사립 병원', diff: '+200%' },
          { item: '순 저축', before: '100', after: '350', diff: '+250' }
      ];
    }

    // 5. Generate Essay
    const defaultEssay: EssayData = {
      title: `${goal}의 현실: 숫자가 말해주지 않는 것들`,
      intro: `${start}를 떠나 ${goal}로 향하는 당신의 발걸음은 가볍겠지만, 현실의 무게는 결코 가볍지 않습니다.`,
      body: "우리는 종종 장소만 바뀌면 삶이 바뀔 것이라 착각합니다. 하지만 당신이 가져가는 것은 짐가방뿐만이 아닙니다. 당신의 불안과 습관도 국경을 넘습니다."
    };

    const essayData: EssayData = selectedTemplate.essay ? {
      title: inject(selectedTemplate.essay.title),
      intro: inject(selectedTemplate.essay.intro),
      body: inject(selectedTemplate.essay.body)
    } : defaultEssay;

    // 6. Generate Downloads
    const downloads: DownloadableResource[] = selectedTemplate.downloads ? selectedTemplate.downloads.map(d => ({
      ...d,
      title: inject(d.title),
      description: inject(d.description),
      triggerUrl: inject(d.triggerUrl)
    })) : [];

    const scenarioData: ScenarioData = {
        success: randInt(40, 95),
        salary: config.avgSalary,
        visa: config.visaName,
        living: randInt(100, 450), 
        story: {
            header: inject(selectedTemplate.story.titleTemplate),
            subHeader: inject(selectedTemplate.story.subTemplate),
            stages: selectedTemplate.story.stages.map(s => ({
              label: s.label,
              title: inject(s.title),
              situation: inject(s.content.situation),
              thought: inject(s.content.thought),
              action: inject(s.content.action),
              experiment: inject(s.content.experiment),
              failure: inject(s.content.failure),
              question: inject(s.content.question),
              solution: inject(s.content.solution),
              result: inject(s.content.result),
              reality: inject(s.content.reality),
            })) as [any, any, any, any]
        },
        resultTable: resultTable,
        additionalInfo: {
            obstacles: ['현지 규제', '환율 변동', '언어 장벽'],
            nextSteps: [
                { label: '구글 검색', value: `${start} 은퇴자 ${goal} 비자 후기` },
                { label: '유튜브', value: `${goal} 현지 물가 브이로그` },
                { label: 'PDF 다운로드', value: `${goal} 정착 가이드` }
            ]
        },
        essay: essayData,
        downloads: downloads,
        visaInfoUrl: config.visaInfoUrl,
    };

    const title = scenarioData.story.header;
    const progress = randInt(50, 92);

    const newResult: StoryResult = {
      title,
      scenarioData,
      progress,
      userInput: generationInput,
      timestamp: new Date().toLocaleTimeString(),
      isDefault: isDefaultScenario && !usedAI,
    };

    setResult(newResult);
    setLoading(false);

    localStorage.setItem('lastStory', JSON.stringify({ input: newResult.userInput }));

    if (window.innerWidth < 1024) {
        setTimeout(() => {
          const resultEl = document.getElementById('result-anchor');
          if (resultEl) resultEl.scrollIntoView({ behavior: 'smooth', block: 'start' });
        }, 100);
    }
  }, [templates, db]);

  const handleGenerateFromPrompt = async (parsedData: Partial<UserInput>, rawText?: string) => {
    let finalInput: UserInput = {
      age: '', job: '', start: '', goal: '', months: 24, country: '', forcedTemplateId: '', family: '', moveType: '', assets: '', useAI: false,
      ...parsedData
    };

    if (rawText && rawText.length > 10 && process.env.API_KEY) {
        setAiAnalyzing(true);
        try {
            const deepAnalysis = await parseUserPrompt(rawText);
            finalInput = { ...finalInput, ...deepAnalysis };
        } catch (e) {
            console.error("Deep analysis failed, using regex fallback");
        }
        setAiAnalyzing(false);
    }

    setInput(finalInput);
    generateStory(finalInput);
  };

  const handleRandom = () => {
    // Safety check: ensure randomSamples is array
    const samples = Array.isArray(db.randomSamples) ? db.randomSamples : [];
    if (samples.length === 0) {
      setToastMessage("🎲 예시 데이터가 없어 기본 예시를 복구합니다.");
      setDb(prev => ({...prev, randomSamples: INITIAL_DB.randomSamples}));
      setTimeout(() => handleRandom(), 100);
      return;
    }
    const random = samples[Math.floor(Math.random() * samples.length)];
    const baseInput: UserInput = {
      age: '', job: '', start: '', goal: '', months: 24, country: '', forcedTemplateId: '', family: '', moveType: '', assets: '', useAI: false
    };
    const finalInput = { ...baseInput, ...random };

    setInput(finalInput);
    setToastMessage("🎲 랜덤 시나리오를 구성했습니다.");
    setTimeout(() => generateStory(finalInput), 500);
  };

  const handleDownload = () => {
    if (result) {
      downloadPDFElement('pdf-content', `희망구매_${result.userInput.goal}_${Date.now()}`);
      setToastMessage("📄 리포트가 PDF로 저장되었습니다.");
    }
  };

  const handleSearch = (type: 'google' | 'youtube') => {
    const qGoal = input.goal || '이민';
    const qJob = input.job || '취업';
    const url = type === 'google' 
      ? `https://google.com/search?q=${input.age}세 ${qGoal} ${qJob} 현실 비용`
      : `https://youtube.com/results?search_query=${qGoal} ${qJob} 브이로그`;
    window.open(url);
  };

  return (
    <div className="min-h-screen bg-[#0f172a] text-white font-sans selection:bg-emerald-500 selection:text-white">
       <div className="fixed inset-0 overflow-hidden pointer-events-none">
          <div className="absolute top-[-10%] right-[-10%] w-[500px] h-[500px] bg-indigo-600/20 rounded-full blur-[100px]"></div>
          <div className="absolute bottom-[-10%] left-[-10%] w-[500px] h-[500px] bg-emerald-600/10 rounded-full blur-[100px]"></div>
       </div>

      <div className="relative w-full max-w-[1400px] mx-auto min-h-screen flex flex-col pb-safe px-4 md:px-6 lg:px-8">

        <div className="pt-4 md:pt-8 pb-6">
           <Header 
             scenarioCount={templates.length} 
             lastVerified={db.lastVerified}
             onAdminClick={() => setShowAdminLogin(true)}
           />
        </div>

        <div className="flex-1 grid grid-cols-1 lg:grid-cols-12 gap-6 lg:gap-8 items-start">

            <div className="lg:col-span-4 space-y-6 sticky top-8">
                <InputForm 
                  input={input}
                  onChange={handleInputChange}
                  onGenerate={handleGenerateFromPrompt}
                  onRandom={handleRandom}
                  onDownload={handleDownload}
                  canDownload={!!result}
                  isGenerating={loading || aiAnalyzing}
                />

                <div className="hidden lg:block space-y-6">
                    <ActionButtons 
                      onGoogleSearch={() => handleSearch('google')}
                      onYoutubeSearch={() => handleSearch('youtube')}
                      onRandom={handleRandom}
                      onRefresh={() => window.location.reload()}
                      onReward={() => {}} 
                    />
                    <AdBanner />
                </div>
            </div>

            <div className="lg:col-span-8 space-y-6">
                <div id="result-anchor"></div>

                {!result && !loading && !aiAnalyzing && (
                    <div className="hidden lg:flex h-full min-h-[400px] items-center justify-center border-2 border-dashed border-white/10 rounded-3xl bg-white/5 text-gray-400">
                        <div className="text-center p-8">
                            <div className="text-4xl mb-4">👈</div>
                            <h3 className="text-xl font-bold mb-2">시뮬레이션을 시작하세요</h3>
                            <p className="text-sm">구체적으로 입력할수록 AI가<br/>더 정밀한 미래를 예측합니다.</p>
                        </div>
                    </div>
                )}

                <ResultSection 
                    result={result} 
                    loading={loading} 
                    extraEssays={db.essays} 
                />

                {aiAnalyzing && (
                    <div className="absolute inset-0 z-20 bg-[#0f172a]/90 backdrop-blur-md flex items-center justify-center rounded-3xl">
                        <div className="text-center space-y-4 p-8">
                             <div className="w-16 h-16 border-4 border-emerald-500 border-t-transparent rounded-full animate-spin mx-auto"></div>
                             <div>
                                 <h3 className="text-xl font-bold text-transparent bg-clip-text bg-gradient-to-r from-emerald-400 to-teal-400 animate-pulse">
                                     Deep Prompt Analysis...
                                 </h3>
                                 <p className="text-sm text-gray-400 mt-2">
                                     입력하신 내용의 의도를 파악하고 있습니다.<br/>(가족 구성원, 이사 목적, 예산 규모 등)
                                 </p>
                             </div>
                        </div>
                    </div>
                )}

                {loading && aiGenerating && (
                    <div className="absolute inset-0 z-20 bg-[#0f172a]/90 backdrop-blur-md flex items-center justify-center rounded-3xl">
                        <div className="text-center space-y-4 p-8">
                             <div className="w-16 h-16 border-4 border-indigo-500 border-t-transparent rounded-full animate-spin mx-auto"></div>
                             <div>
                                 <h3 className="text-xl font-bold text-transparent bg-clip-text bg-gradient-to-r from-indigo-400 to-purple-400 animate-pulse">
                                     Creating New Scenario...
                                 </h3>
                                 <p className="text-sm text-gray-400 mt-2">
                                     '{input.goal}'에 대한 맞춤형 템플릿을 생성 중입니다.<br/>
                                     분석된 결과는 영구 보존됩니다.
                                 </p>
                             </div>
                        </div>
                    </div>
                )}

                <div className="lg:hidden space-y-6">
                    <AdBanner />
                    <ActionButtons 
                      onGoogleSearch={() => handleSearch('google')}
                      onYoutubeSearch={() => handleSearch('youtube')}
                      onRandom={handleRandom}
                      onRefresh={() => window.location.reload()}
                      onReward={() => {}} 
                    />
                </div>
            </div>
        </div>

        <div className="h-12"></div>
      </div>

      {showAdminLogin && (
          <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/80 backdrop-blur-md p-6">
            <GlassCard className="p-8 w-full max-w-sm text-center space-y-6 border border-white/20">
              <h2 className="text-2xl font-bold bg-gradient-to-r from-white to-gray-400 bg-clip-text text-transparent">System Access</h2>
              <input 
                type="password" 
                value={adminPassword}
                onChange={(e) => setAdminPassword(e.target.value)}
                onKeyDown={(e) => e.key === 'Enter' && handleAdminLogin()}
                className="w-full p-4 bg-white/5 rounded-xl text-center text-xl font-bold border border-white/10 focus:border-emerald-500 focus:outline-none transition-colors"
                placeholder="Passcode"
                autoFocus
              />
              <div className="flex gap-4">
                <button onClick={() => setShowAdminLogin(false)} className="flex-1 py-3 bg-gray-700/50 hover:bg-gray-700 rounded-xl transition-colors font-medium">Cancel</button>
                <button onClick={handleAdminLogin} className="flex-1 py-3 bg-emerald-600 hover:bg-emerald-500 rounded-xl transition-colors font-bold shadow-lg shadow-emerald-900/50">Enter</button>
              </div>
            </GlassCard>
          </div>
      )}

      {isAdmin && (
        <AdminDashboard 
          db={db} 
          onUpdateDb={setDb} 
          templates={templates} 
          onUpdateTemplates={setTemplates}
          onClose={() => setIsAdmin(false)} 
        />
      )}

      <Toast message={toastMessage} onClose={() => setToastMessage(null)} />
    </div>
  );
}

export default App;

import React, { useState, useEffect } from 'react';
import { GlassCard } from './GlassCard';
import { ScenarioDB, ScenarioTemplate, DownloadableResource, UserInput, StandaloneEssay } from '../types';
import { DEFAULT_TEMPLATES } from '../constants';
import { generateBatchRandomSamples, generateNewScenarioTemplate, suggestNewScenarioTopics, validateSystemData } from '../aiService';
import { ApiKeyModal } from './ApiKeyModal';

interface AdminDashboardProps {
  db: ScenarioDB;
  onUpdateDb: React.Dispatch<React.SetStateAction<ScenarioDB>>;
  templates: ScenarioTemplate[];
  onUpdateTemplates: React.Dispatch<React.SetStateAction<ScenarioTemplate[]>>;
  onClose: () => void;
}

// --- Data Export Modal (Improved UI for Visibility) ---
const DataExportModal: React.FC<{ 
    isOpen: boolean; 
    onClose: () => void; 
    db: ScenarioDB; 
    templates: ScenarioTemplate[];
    onRestore: (data: { db: ScenarioDB, templates: ScenarioTemplate[] }) => void;
}> = ({ isOpen, onClose, db, templates, onRestore }) => {
    const [copied, setCopied] = useState(false);
    const [activeTab, setActiveTab] = useState<'code' | 'backup'>('backup');

    if (!isOpen) return null;

    const exportCode = `
// --- PASTE THIS INTO constants.ts TO SAVE PERMANENTLY ---

import { ScenarioDB, ScenarioTemplate } from './types';

export const DEFAULT_TEMPLATES: ScenarioTemplate[] = ${JSON.stringify(templates, null, 2)};

export const INITIAL_DB: ScenarioDB = ${JSON.stringify(db, null, 2)};
    `;

    const handleCopy = () => {
        navigator.clipboard.writeText(exportCode);
        setCopied(true);
        setTimeout(() => setCopied(false), 2000);
    };

    const handleDownloadJson = () => {
        const fullBackup = {
            timestamp: new Date().toISOString(),
            db,
            templates
        };
        const element = document.createElement("a");
        const file = new Blob([JSON.stringify(fullBackup, null, 2)], {type: 'application/json'});
        element.href = URL.createObjectURL(file);
        element.download = `HOPE_BACKUP_${new Date().toISOString().slice(0,10)}.json`;
        document.body.appendChild(element); 
        element.click();
        document.body.removeChild(element);
    };

    const handleFileRestore = (e: React.ChangeEvent<HTMLInputElement>) => {
        const fileReader = new FileReader();
        if (e.target.files && e.target.files[0]) {
            fileReader.readAsText(e.target.files[0], "UTF-8");
            fileReader.onload = (event) => {
                try {
                    const json = JSON.parse(event.target?.result as string);
                    if (json.db && json.templates) {
                        if(confirm(`백업 파일(${json.timestamp})로 복구하시겠습니까? 현재 데이터는 덮어씌워집니다.`)) {
                            onRestore({ db: json.db, templates: json.templates });
                            onClose();
                            alert("✅ 복구 완료되었습니다.");
                        }
                    } else {
                        alert("❌ 올바르지 않은 백업 파일 형식입니다.");
                    }
                } catch (err) {
                    alert("❌ 파일 읽기 실패");
                }
            };
        }
    };

    return (
        <div className="fixed inset-0 z-[100] flex items-center justify-center bg-black/90 backdrop-blur-md p-4 animate-fade-in">
            <GlassCard className="w-full max-w-4xl h-[85vh] flex flex-col p-6 border-l-4 border-l-blue-500 shadow-2xl relative">
                <button onClick={onClose} className="absolute top-4 right-4 text-gray-400 hover:text-white p-2">✕</button>

                <div className="mb-4">
                    <h2 className="text-xl md:text-2xl font-bold text-white flex items-center gap-2">
                        💾 데이터 백업 & 복구
                    </h2>
                    <div className="flex gap-4 mt-4 border-b border-white/10">
                        <button onClick={() => setActiveTab('backup')} className={`pb-2 px-2 text-sm font-bold transition-colors ${activeTab === 'backup' ? 'text-blue-400 border-b-2 border-blue-400' : 'text-gray-400'}`}>파일 관리 (JSON)</button>
                        <button onClick={() => setActiveTab('code')} className={`pb-2 px-2 text-sm font-bold transition-colors ${activeTab === 'code' ? 'text-blue-400 border-b-2 border-blue-400' : 'text-gray-400'}`}>개발자용 코드</button>
                    </div>
                </div>

                <div className="flex-1 overflow-y-auto pr-2">
                {activeTab === 'backup' ? (
                     <div className="grid grid-cols-1 md:grid-cols-2 gap-6 p-4">
                        {/* Download Section */}
                        <div className="bg-white/5 rounded-xl p-6 border border-white/10 flex flex-col items-center text-center space-y-4">
                            <div className="text-4xl">⬇️</div>
                            <h3 className="text-lg font-bold text-white">데이터 내보내기</h3>
                            <p className="text-xs text-gray-400 h-10">
                                현재 상태(템플릿, 에세이 등)를 JSON 파일로 저장합니다.
                            </p>
                            <button onClick={handleDownloadJson} className="w-full py-3 bg-emerald-600 hover:bg-emerald-500 rounded-xl font-bold text-white text-sm shadow-lg transition-transform hover:scale-105">
                                파일 다운로드 (.json)
                            </button>
                        </div>

                        {/* Upload Section */}
                        <div className="bg-white/5 rounded-xl p-6 border border-white/10 flex flex-col items-center text-center space-y-4">
                            <div className="text-4xl">⬆️</div>
                            <h3 className="text-lg font-bold text-white">데이터 불러오기</h3>
                            <p className="text-xs text-gray-400 h-10">
                                저장해둔 JSON 파일을 업로드하여 복구합니다.
                            </p>
                            <label className="w-full py-3 bg-blue-600/20 hover:bg-blue-600/30 border border-blue-500/50 rounded-xl font-bold text-blue-300 text-sm cursor-pointer transition-colors text-center block">
                                파일 선택 및 복구
                                <input type="file" accept=".json" onChange={handleFileRestore} className="hidden" />
                            </label>
                        </div>

                        <div className="md:col-span-2 bg-yellow-500/10 border border-yellow-500/20 p-4 rounded-xl text-xs text-yellow-200 text-center">
                            💡 팁: 업데이트 전에는 반드시 파일을 다운로드해 두세요.
                        </div>
                     </div>
                ) : (
                    <div className="bg-black/50 rounded-xl border border-white/10 h-full flex flex-col">
                        <div className="flex justify-between items-center p-2 bg-white/5 border-b border-white/10">
                            <span className="text-xs font-mono text-gray-500 ml-2">constants.ts export</span>
                            <button 
                                onClick={handleCopy}
                                className={`px-4 py-1.5 rounded-lg text-xs font-bold transition-all ${copied ? 'bg-green-500 text-white' : 'bg-blue-600 hover:bg-blue-500 text-white'}`}
                            >
                                {copied ? "✅ 복사 완료!" : "📋 코드 전체 복사"}
                            </button>
                        </div>
                        <textarea 
                            readOnly
                            value={exportCode}
                            className="flex-1 bg-transparent p-4 text-xs font-mono text-blue-200 resize-none focus:outline-none"
                        />
                    </div>
                )}
                </div>
            </GlassCard>
        </div>
    );
};

const RandomSampleEditor: React.FC<{db: ScenarioDB, onUpdateDb: React.Dispatch<React.SetStateAction<ScenarioDB>>, templates: ScenarioTemplate[]}> = ({ db, onUpdateDb, templates }) => {
    // Safety check: ensure db.randomSamples is an array
    const [samples, setSamples] = useState<Partial<UserInput>[]>(Array.isArray(db.randomSamples) ? db.randomSamples : []);

    useEffect(() => {
        if(Array.isArray(db.randomSamples)) {
            setSamples(db.randomSamples);
        } else {
            setSamples([]);
        }
    }, [db.randomSamples]);

    const handleUpdate = (index: number, field: keyof UserInput, value: string | number | boolean) => {
        const newSamples = [...samples];
        if (newSamples[index]) {
            newSamples[index] = { ...newSamples[index], [field]: value };
             if (field === 'useAI' && value === true) {
                newSamples[index].forcedTemplateId = '';
            }
            setSamples(newSamples);
        }
    };

    const handleSave = () => {
        onUpdateDb(prev => ({ ...prev, randomSamples: samples }));
        alert("✅ 저장되었습니다.");
    };

    const handleAdd = () => {
        setSamples([...samples, { age: '30', job: '직장인', start: '서울', goal: '미국', months: 24, forcedTemplateId: '', isDomestic: false, useAI: false }]);
    };

    const handleRemove = (index: number) => {
        if (confirm('이 예시를 삭제하시겠습니까?')) {
            const newSamples = [...samples];
            newSamples.splice(index, 1);
            setSamples(newSamples);
        }
    };

    return (
        <div className="h-full overflow-y-auto p-6 md:p-8 space-y-6 pb-20">
            <GlassCard className="p-6 border-l-4 border-l-purple-500">
                 <div className="flex justify-between items-center mb-6">
                    <div>
                        <h3 className="text-xl font-bold flex items-center gap-2">
                           🔀 랜덤 예시 설정
                           <span className="text-xs bg-purple-500/20 text-purple-300 px-2 py-1 rounded-full">{samples.length}개</span>
                        </h3>
                    </div>
                    <button onClick={handleSave} className="px-6 py-2 bg-emerald-600 hover:bg-emerald-500 rounded-xl font-bold text-white text-sm">
                        저장
                    </button>
                 </div>

                 <div className="grid gap-4">
                    {samples.map((sample, index) => (
                         <div key={index} className="bg-white/5 border border-white/10 rounded-xl p-4 relative">
                            <button onClick={() => handleRemove(index)} className="absolute top-2 right-2 text-red-500 font-bold hover:text-white">✕</button>
                            <div className="grid grid-cols-2 md:grid-cols-6 gap-3">
                                <input value={sample.age || ''} onChange={(e) => handleUpdate(index, 'age', e.target.value)} className="bg-black/30 p-2 rounded text-sm text-white" placeholder="나이" />
                                <input value={sample.job || ''} onChange={(e) => handleUpdate(index, 'job', e.target.value)} className="bg-black/30 p-2 rounded text-sm text-white" placeholder="직업" />
                                <input value={sample.start || ''} onChange={(e) => handleUpdate(index, 'start', e.target.value)} className="bg-black/30 p-2 rounded text-sm text-white" placeholder="출발" />
                                <input value={sample.goal || ''} onChange={(e) => handleUpdate(index, 'goal', e.target.value)} className="bg-black/30 p-2 rounded text-sm text-white" placeholder="도착" />
                                <select value={sample.isDomestic ? 'domestic' : 'intl'} onChange={(e) => handleUpdate(index, 'isDomestic', e.target.value === 'domestic')} className="bg-black/30 p-2 rounded text-sm text-white">
                                    <option value="intl">해외</option>
                                    <option value="domestic">국내</option>
                                </select>
                                <div className="flex items-center gap-2">
                                     <input type="checkbox" checked={!!sample.useAI} onChange={(e) => handleUpdate(index, 'useAI', e.target.checked)} className="w-4 h-4" />
                                     <span className={`text-xs ${sample.useAI ? 'text-emerald-400 font-bold' : 'text-gray-400'}`}>AI 생성</span>
                                </div>
                            </div>
                         </div>
                    ))}
                    <button onClick={handleAdd} className="w-full py-3 bg-white/5 rounded-xl text-gray-400 hover:text-white border border-dashed border-white/20">+ 추가</button>
                 </div>
            </GlassCard>
        </div>
    );
};

const EssayEditor: React.FC<{ db: ScenarioDB; onUpdateDb: React.Dispatch<React.SetStateAction<ScenarioDB>> }> = ({ db, onUpdateDb }) => {
    // Safety check: ensure db.essays is an array
    const [essays, setEssays] = useState<StandaloneEssay[]>(Array.isArray(db.essays) ? db.essays : []);
    const [editingId, setEditingId] = useState<string | null>(null);
    const [formData, setFormData] = useState<StandaloneEssay>({ id: '', title: '', content: '', tags: [], date: '' });

    useEffect(() => {
        if(Array.isArray(db.essays)) {
            setEssays(db.essays);
        } else {
            setEssays([]);
        }
    }, [db.essays]);

    const handleCreate = () => {
        setEditingId('new');
        setFormData({ id: `essay_${Date.now()}`, title: '', content: '', tags: [], date: new Date().toLocaleDateString() });
    };

    const handleSave = () => {
        onUpdateDb(prev => {
            const current = Array.isArray(prev.essays) ? prev.essays : [];
            const updated = editingId === 'new' 
                ? [formData, ...current] 
                : current.map(e => e.id === formData.id ? formData : e);
            return { ...prev, essays: updated };
        });
        setEditingId(null);
    };

    const handleDelete = (id: string) => {
        if (confirm("정말로 이 칼럼을 삭제하시겠습니까? (복구 불가)")) {
            onUpdateDb(prev => ({
                ...prev,
                essays: Array.isArray(prev.essays) ? prev.essays.filter(e => e.id !== id) : []
            }));
            if (editingId === id) {
                setEditingId(null);
            }
        }
    };

    return (
        <div className="h-full flex flex-col md:flex-row gap-6 p-6">
            <div className="w-full md:w-1/3 space-y-4">
                <button onClick={handleCreate} className="w-full py-3 bg-indigo-600 hover:bg-indigo-500 rounded-xl font-bold text-white">+ 새 칼럼 작성</button>
                <div className="space-y-2 h-[400px] overflow-y-auto">
                    {essays.map(essay => (
                        <div key={essay.id} className="p-4 bg-white/5 hover:bg-white/10 rounded-xl cursor-pointer relative group" onClick={() => { setEditingId(essay.id); setFormData(essay); }}>
                            <h4 className="font-bold text-sm text-white truncate pr-6">{essay.title || '(제목 없음)'}</h4>
                            <div className="text-xs text-gray-500 mt-1">{essay.date}</div>
                            <button 
                                onClick={(e) => { e.stopPropagation(); handleDelete(essay.id); }}
                                className="absolute top-3 right-3 text-gray-500 hover:text-red-400 opacity-0 group-hover:opacity-100 transition-opacity p-1"
                                title="삭제"
                            >
                                🗑️
                            </button>
                        </div>
                    ))}
                    {essays.length === 0 && <div className="text-center text-gray-600 text-xs py-10">작성된 글이 없습니다.</div>}
                </div>
            </div>
            <div className="w-full md:w-2/3 bg-black/20 rounded-xl p-6">
                {editingId ? (
                    <div className="flex flex-col h-full space-y-4">
                        <input value={formData.title} onChange={e => setFormData({...formData, title: e.target.value})} className="bg-transparent text-xl font-bold text-white border-b border-white/10 pb-2" placeholder="제목" />
                        <textarea value={formData.content} onChange={e => setFormData({...formData, content: e.target.value})} className="flex-1 bg-transparent text-sm text-gray-300 resize-none p-4 border border-white/5 rounded-lg h-[300px]" placeholder="내용" />
                        <div className="flex justify-between items-center">
                            {editingId !== 'new' ? (
                                <button onClick={() => handleDelete(editingId)} className="px-4 py-2 text-xs font-bold text-red-400 hover:bg-red-500/10 rounded-lg">
                                    🗑️ 삭제
                                </button>
                            ) : <div></div>}
                            <div className="flex gap-2">
                                <button onClick={() => setEditingId(null)} className="px-4 py-2 text-xs font-bold text-gray-400">취소</button>
                                <button onClick={handleSave} className="px-6 py-2 bg-emerald-600 text-white text-xs font-bold rounded-lg">저장</button>
                            </div>
                        </div>
                    </div>
                ) : (
                    <div className="h-full flex items-center justify-center text-gray-500">글을 선택하거나 작성하세요.</div>
                )}
            </div>
        </div>
    );
};

export const AdminDashboard: React.FC<AdminDashboardProps> = ({ 
  db, 
  onUpdateDb, 
  templates, 
  onUpdateTemplates, 
  onClose 
}) => {
  const [activeTab, setActiveTab] = useState<'control' | 'templates' | 'samples' | 'essays'>('control');
  const [logs, setLogs] = useState<string[]>([]);
  const [aiMaintenance, setAiMaintenance] = useState({ updateTemplates: false, updateSamples: false, validate: false });
  const [batchSize, setBatchSize] = useState<number>(3); 
  const [aiRunning, setAiRunning] = useState(false);
  const [showKeyModal, setShowKeyModal] = useState(false);
  const [showExportModal, setShowExportModal] = useState(false);

  const addLog = (msg: string) => {
    const timestamp = new Date().toLocaleTimeString();
    setLogs(prev => [`[${timestamp}] ${msg}`, ...prev]);
  };

  const handleRestore = (data: { db: ScenarioDB, templates: ScenarioTemplate[] }) => {
    onUpdateDb(data.db);
    onUpdateTemplates(data.templates);
    // Explicitly save to local storage immediately
    localStorage.setItem('app_db', JSON.stringify(data.db));
    localStorage.setItem('app_templates', JSON.stringify(data.templates));
  };

  const handleRestoreDefaults = () => {
    if(confirm("기본 템플릿 4개(포르투갈, 발리, 강남, 기본)를 강제로 복원하시겠습니까? 기존 템플릿 목록에 추가됩니다.")) {
        onUpdateTemplates(prev => {
            const currentIds = prev.map(t => t.id);
            const defaultsToAdd = DEFAULT_TEMPLATES.filter(dt => !currentIds.includes(dt.id));
            if (defaultsToAdd.length === 0) {
                alert("이미 기본 템플릿이 모두 존재합니다.");
                return prev;
            }
            return [...defaultsToAdd, ...prev];
        });
        alert("✅ 복원 완료되었습니다.");
    }
  };

  const runAIMaintenance = async () => {
    setAiRunning(true);
    addLog(`🚀 AI 자동 유지보수 시작 (Batch Size: ${batchSize})...`);

    try {
        const generatedTemplates: ScenarioTemplate[] = [];
        const generatedSamples: Partial<UserInput>[] = [];

        if (aiMaintenance.validate) {
            addLog("🔍 데이터 정합성 검사 중...");
            const report = await validateSystemData(db, templates);
            if (Array.isArray(report)) {
                report.forEach(r => addLog(`📋 [리포트] ${r}`));
            } else {
                addLog("⚠️ 검증 결과 형식이 올바르지 않습니다.");
            }
        }

        if (aiMaintenance.updateSamples) {
            addLog(`🎲 ${batchSize}개의 새로운 랜덤 예시 생성 중...`);
            const newSamples = await generateBatchRandomSamples(batchSize); 
            if (newSamples.length > 0) {
                generatedSamples.push(...newSamples);
                addLog(`✅ 랜덤 예시 ${newSamples.length}개 생성 성공`);
            }
        }

        if (aiMaintenance.updateTemplates) {
            addLog(`🧠 부족한 시나리오 주제 분석 중...`);
            const allTags = templates.flatMap(t => t.tags);
            const topicIdeas = await suggestNewScenarioTopics(allTags, batchSize);

            for (let i = 0; i < topicIdeas.length; i++) {
                const idea = topicIdeas[i];
                addLog(`[${i + 1}/${topicIdeas.length}] ✍️ 템플릿 작성 중: ${idea.goal}...`);
                const newTemplate = await generateNewScenarioTemplate(idea as UserInput);
                if (newTemplate) generatedTemplates.push(newTemplate);
            }
        }

        // Safe State Updates with explicit array checks to avoid 'number 0 is not iterable'
        if (generatedSamples.length > 0) {
            onUpdateDb(prev => ({
                 ...prev, 
                 randomSamples: [...generatedSamples, ...(Array.isArray(prev.randomSamples) ? prev.randomSamples : [])].slice(0, 50) 
            }));
            addLog(`💾 시스템 DB에 랜덤 예시 업데이트 완료.`);
        }

        if (generatedTemplates.length > 0) {
            onUpdateTemplates(prev => [...generatedTemplates, ...prev]);
            addLog(`💾 시스템 DB에 템플릿 업데이트 완료.`);
        }

        addLog("🏁 모든 작업 완료.");

    } catch (e: any) {
        console.error(e);
        addLog(`❌ 오류 발생: ${e.message}`);
    } finally {
        setAiRunning(false);
    }
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/80 backdrop-blur-md p-4 animate-fade-in">
      <GlassCard className="w-full max-w-6xl h-[90vh] flex flex-col bg-[#111827] border-white/20 shadow-2xl overflow-hidden">
        {/* Header */}
        <div className="p-6 border-b border-white/10 flex justify-between items-center bg-black/20">
          <div>
             <h2 className="text-2xl font-black text-white flex items-center gap-2">
                <span className="text-3xl">⚙️</span> SYSTEM ADMIN
             </h2>
             <p className="text-xs text-emerald-400 font-mono mt-1">
                Connected: {new Date().toLocaleDateString()}
             </p>
          </div>
          <div className="flex gap-2">
            <button 
                onClick={() => {
                   if(confirm("정말로 모든 데이터를 초기화하시겠습니까? (로컬 데이터 삭제 후 새로고침)")) {
                       localStorage.removeItem('app_db');
                       localStorage.removeItem('app_templates');
                       window.location.reload();
                   }
                }}
                className="px-4 py-2 bg-red-600/20 text-red-400 border border-red-500/50 rounded-lg text-xs font-bold hover:bg-red-600/30 transition-colors flex items-center gap-2"
            >
                🔄 초기화
            </button>
            <button 
                onClick={() => setShowExportModal(true)}
                className="px-4 py-2 bg-blue-600/20 text-blue-400 border border-blue-500/50 rounded-lg text-xs font-bold hover:bg-blue-600/30 transition-colors flex items-center gap-2"
            >
                💾 백업/복구
            </button>
            <button 
                onClick={() => setShowKeyModal(true)}
                className="px-4 py-2 bg-yellow-600/20 text-yellow-500 border border-yellow-600/50 rounded-lg text-xs font-bold hover:bg-yellow-600/30 transition-colors flex items-center gap-2"
            >
                🔑 API 키
            </button>
            <button onClick={onClose} className="w-10 h-10 rounded-full bg-white/10 hover:bg-white/20 flex items-center justify-center text-white transition-colors">
                ✕
            </button>
          </div>
        </div>

        {/* Tabs */}
        <div className="flex border-b border-white/10 bg-black/10">
           {['control', 'templates', 'samples', 'essays'].map(tab => (
               <button 
                 key={tab}
                 onClick={() => setActiveTab(tab as any)}
                 className={`px-8 py-4 text-sm font-bold uppercase transition-colors ${activeTab === tab ? 'bg-emerald-600/20 text-emerald-400 border-b-2 border-emerald-500' : 'text-gray-400 hover:text-white'}`}
               >
                 {tab}
               </button>
           ))}
        </div>

        {/* Content */}
        <div className="flex-1 overflow-hidden bg-[#0f172a]">
           {activeTab === 'control' && (
             <div className="p-8 h-full overflow-y-auto space-y-8">
                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                    <GlassCard className="p-6 border-l-4 border-l-emerald-500">
                        <h3 className="text-gray-400 text-xs font-bold uppercase tracking-wider mb-4">AI Auto-Maintenance</h3>
