                type: Type.OBJECT,
                properties: {
                  label: { type: Type.STRING },
                  title: { type: Type.STRING },
                  content: {
                    type: Type.OBJECT,
                    properties: {
                      situation: { type: Type.STRING, nullable: true },
                      thought: { type: Type.STRING, nullable: true },
                      action: { type: Type.STRING, nullable: true },
                      experiment: { type: Type.STRING, nullable: true },
                      failure: { type: Type.STRING, nullable: true },
                      question: { type: Type.STRING, nullable: true },
                      solution: { type: Type.STRING, nullable: true },
                      result: { type: Type.STRING, nullable: true },
                      reality: { type: Type.STRING, nullable: true },
                    }
                  }
                }
              }
            }
          }
        },
        resultTable: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              item: { type: Type.STRING },
              before: { type: Type.STRING },
              after: { type: Type.STRING },
              diff: { type: Type.STRING }
            }
          }
        },
        essay: {
          type: Type.OBJECT,
          properties: {
            title: { type: Type.STRING },
            intro: { type: Type.STRING },
            body: { type: Type.STRING }
          }
        },
        downloads: {
            type: Type.ARRAY,
            items: {
                type: Type.OBJECT,
                properties: {
                    title: { type: Type.STRING },
                    description: { type: Type.STRING },
                    type: { type: Type.STRING, enum: ["pdf", "excel", "doc"] },
                    triggerType: { type: Type.STRING, enum: ["ad", "link"] },
                    triggerUrl: { type: Type.STRING, nullable: true }
                }
            }
        }
      },
      required: ["id", "type", "tags", "story", "essay"]
    };

    const prompt = `
      Create a "Dry Author" style life simulation template.

      ${contextDescription}

      ${input.isDomestic ? domesticInstruction : internationalInstruction}

      CRITICAL INSTRUCTIONS:
      1. **Tone**: Cynical, Analytical, Hyper-Realistic. Highlight "Hidden Costs" (Mental & Financial).
      2. **Variables**: The output MUST be a generic template using placeholders: {age}, {job}, {start}, {goal}, {months}, {currency}, {family}.
         - Even if the user input specific values, replace them with placeholders in the template text where appropriate so it can be reused.
         - However, keep specific local facts hardcoded (e.g. "Gangnam traffic", "Jeju wind", "Vancouver rain").

      3. **Structure Requirement (EXACTLY 4 STAGES)**:
         - Stage 1 Label: "Day 1" (The Honeymoon/Investment)
         - Stage 2 Label: "Month 6" (The First Failure/Reality Check)
         - Stage 3 Label: "Month 12~18" (The Deep Crisis/Infrastructure Gap)
         - Stage 4 Label: "Month ${input.months}" (Final Result/Adaptation or Return)

      4. **Result Table**: 4 Key metrics comparing Start vs Goal (e.g., Cost of Living, Assets, Quality of Life).
      5. **Essay**: A sharp, 3-paragraph critique of the user's desire to move to ${input.goal}.
      6. **Downloads**: 2 specific tools (PDF/Excel) relevant to the move type.

      RETURN PURE JSON ONLY. NO MARKDOWN.
    `;

    const response = await withTimeout<GenerateContentResponse>(ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: schema,
        temperature: 0.7, 
      }
    }), 25000); // 25s timeout for full generation

    let jsonText = response.text || "";
    // FORCE CLEAN MARKDOWN (Fixes "not writing" issue)
    jsonText = jsonText.replace(/```json\n?/g, '').replace(/```/g, '').trim();

    if (!jsonText) return null;

    const generatedTemplate = JSON.parse(jsonText) as ScenarioTemplate;

    // Post-processing: Ensure tags and ID are robust
    const additionalTags = [
        input.goal.toLowerCase(), 
        input.moveType?.toLowerCase() || 'general', 
        input.isDomestic ? 'domestic' : 'international',
        input.family?.includes('kid') || input.family?.includes('child') ? 'family' : 'single'
    ];

    generatedTemplate.tags = [...new Set([...generatedTemplate.tags, ...additionalTags])];

    // Ensure unique ID for persistence
    const typePrefix = input.isDomestic ? 'domestic' : 'global';
    generatedTemplate.id = `ai_${typePrefix}_${Date.now()}_${input.goal.replace(/\s/g, '').toLowerCase()}`;

    return generatedTemplate;

  } catch (error) {
    console.error("Gemini AI Generation Failed:", error);
    throw error;
  }
};

import React, { useState, useEffect } from 'react';
import { GlassCard } from './GlassCard';
import { ScenarioDB, ScenarioTemplate, UserInput, StandaloneEssay } from '../types';
import { DEFAULT_TEMPLATES, INITIAL_DB } from '../constants';

interface AdminDashboardProps {
  db: ScenarioDB;
  onUpdateDb: React.Dispatch<React.SetStateAction<ScenarioDB>>;
  templates: ScenarioTemplate[];
  onUpdateTemplates: React.Dispatch<React.SetStateAction<ScenarioTemplate[]>>;
  onClose: () => void;
}

// --- 1. SMART BACKUP & RESTORE MODAL ---
const DataExportModal: React.FC<{ 
    isOpen: boolean; 
    onClose: () => void; 
    db: ScenarioDB; 
    templates: ScenarioTemplate[];
    onRestore: (data: { db: ScenarioDB, templates: ScenarioTemplate[] }) => void;
}> = ({ isOpen, onClose, db, templates, onRestore }) => {
    const [copied, setCopied] = useState(false);
    const [activeTab, setActiveTab] = useState<'code' | 'backup'>('backup');

    if (!isOpen) return null;

    const exportCode = `
// --- PASTE THIS INTO constants.ts TO SAVE PERMANENTLY ---
import { ScenarioDB, ScenarioTemplate } from './types';

export const DEFAULT_TEMPLATES: ScenarioTemplate[] = ${JSON.stringify(templates, null, 2)};

export const INITIAL_DB: ScenarioDB = ${JSON.stringify(db, null, 2)};
    `;

    const handleCopy = () => {
        navigator.clipboard.writeText(exportCode);
        setCopied(true);
        setTimeout(() => setCopied(false), 2000);
    };

    const handleDownloadJson = () => {
        const fullBackup = {
            timestamp: new Date().toISOString(),
            version: "4.0",
            db,
            templates
        };
        const element = document.createElement("a");
        const file = new Blob([JSON.stringify(fullBackup, null, 2)], {type: 'application/json'});
        const fileName = `HOPE_BACKUP_${new Date().toISOString().slice(0,10)}_${Date.now()}.json`;
        element.href = URL.createObjectURL(file);
        element.download = fileName;
        document.body.appendChild(element); 
        element.click();
        document.body.removeChild(element);
    };

    const handleFileRestore = (e: React.ChangeEvent<HTMLInputElement>) => {
        const fileReader = new FileReader();
        if (e.target.files && e.target.files[0]) {
            fileReader.readAsText(e.target.files[0], "UTF-8");
            fileReader.onload = (event) => {
                try {
                    const json = JSON.parse(event.target?.result as string);

                    if (!json.db || !json.templates) {
                        alert("❌ 올바르지 않은 백업 파일 형식입니다. (db 또는 templates 속성 누락)");
                        return;
                    }

                    // --- SMART MERGE LOGIC (기존 데이터 유지 + 새 데이터 추가) ---

                    // 1. Templates: ID가 없는 것만 추가
                    const currentTemplateIds = new Set(templates.map(t => t.id));
                    const newTemplates = [...templates];
                    let addedTemplatesCount = 0;

                    const uploadedTemplates = (json.templates as ScenarioTemplate[]);
                    uploadedTemplates.forEach(t => {
                        if (!currentTemplateIds.has(t.id)) {
                            newTemplates.push(t);
                            addedTemplatesCount++;
                        }
                    });

                    // 2. Random Samples: 내용이 완전히 같은게 없으면 추가
                    const newSamples = [...(db.randomSamples || [])];
                    let addedSamplesCount = 0;
                    const uploadedSamples = (json.db.randomSamples as Partial<UserInput>[] || []);
                    uploadedSamples.forEach(s => {
                        const exists = newSamples.some(curr => 
                            curr.age === s.age && 
                            curr.job === s.job && 
                            curr.goal === s.goal && 
                            curr.start === s.start
                        );
                        if (!exists) {
                            newSamples.push(s);
                            addedSamplesCount++;
                        }
                    });

                    // 3. Essays: ID가 없는 것만 추가
                    const newEssays = [...(db.essays || [])];
                    let addedEssaysCount = 0;
                    const currentEssayIds = new Set(newEssays.map(e => e.id));
                    const uploadedEssays = (json.db.essays as StandaloneEssay[] || []);
                    uploadedEssays.forEach(essay => {
                         if (!currentEssayIds.has(essay.id)) {
                             newEssays.push(essay);
                             addedEssaysCount++;
                         }
                    });

                    // 4. Scenarios Cache: 병합
                    const mergedScenarios = { ...json.db.scenarios, ...db.scenarios };

                    const confirmMsg = `백업 데이터를 병합하시겠습니까?\n\n` +
                                     `[추가될 항목]\n` +
                                     `- 템플릿: ${addedTemplatesCount}개\n` +
                                     `- 랜덤 예시: ${addedSamplesCount}개\n` +
                                     `- 에세이: ${addedEssaysCount}개\n\n` +
                                     `* 기존 데이터는 안전하게 유지되며, 누락된 항목만 추가됩니다.`;

                    if(confirm(confirmMsg)) {
                        const mergedDb: ScenarioDB = {
                            ...db,
                            randomSamples: newSamples,
                            essays: newEssays,
                            scenarios: mergedScenarios,
                            rates: { ...db.rates, ...json.db.rates }, // 환율은 최신 파일 우선 권장
                            lastVerified: new Date().toISOString()
                        };

                        onRestore({ db: mergedDb, templates: newTemplates });
                        onClose();
                        alert(`✅ 병합 완료!\n\n새로운 템플릿 ${addedTemplatesCount}개, 예시 ${addedSamplesCount}개, 에세이 ${addedEssaysCount}개가 추가되었습니다.`);
                    }

                } catch (err) {
                    console.error(err);
                    alert("❌ 파일 읽기 실패: JSON 형식이 올바르지 않습니다.");
                }
            };
        }
    };

    return (
        <div className="fixed inset-0 z-[100] flex items-center justify-center bg-black/90 backdrop-blur-md p-4 animate-fade-in">
            <GlassCard className="w-full max-w-4xl h-[85vh] flex flex-col p-6 border-l-4 border-l-blue-500 shadow-2xl relative">
                <button onClick={onClose} className="absolute top-4 right-4 text-gray-400 hover:text-white p-2">✕</button>
                <div className="mb-4">
                    <h2 className="text-xl md:text-2xl font-bold text-white flex items-center gap-2">
                        💾 데이터 백업 & 복구 (Smart Merge)
                    </h2>
                    <div className="flex gap-4 mt-4 border-b border-white/10">
                        <button onClick={() => setActiveTab('backup')} className={`pb-2 px-2 text-sm font-bold transition-colors ${activeTab === 'backup' ? 'text-blue-400 border-b-2 border-blue-400' : 'text-gray-400'}`}>파일 관리 (JSON)</button>
                        <button onClick={() => setActiveTab('code')} className={`pb-2 px-2 text-sm font-bold transition-colors ${activeTab === 'code' ? 'text-blue-400 border-b-2 border-blue-400' : 'text-gray-400'}`}>개발자용 코드</button>
                    </div>
                </div>
                <div className="flex-1 overflow-y-auto pr-2">
                {activeTab === 'backup' ? (
                     <div className="grid grid-cols-1 md:grid-cols-2 gap-6 p-4">
                        <div className="bg-white/5 rounded-xl p-6 border border-white/10 flex flex-col items-center text-center space-y-4">
                            <div className="text-4xl">⬇️</div>
                            <h3 className="text-lg font-bold text-white">데이터 내보내기</h3>
                            <p className="text-xs text-gray-400 h-10">현재 상태(템플릿, 에세이 등)를 JSON 파일로 저장합니다.</p>
                            <button onClick={handleDownloadJson} className="w-full py-3 bg-emerald-600 hover:bg-emerald-500 rounded-xl font-bold text-white text-sm shadow-lg transition-transform hover:scale-105">파일 다운로드 (.json)</button>
                        </div>
                        <div className="bg-white/5 rounded-xl p-6 border border-white/10 flex flex-col items-center text-center space-y-4">
                            <div className="text-4xl">⬆️</div>
                            <h3 className="text-lg font-bold text-white">데이터 불러오기 (병합)</h3>
                            <p className="text-xs text-gray-400 h-10">저장된 JSON 파일을 불러와 <b>없는 데이터만 추가</b>합니다.</p>
                            <label className="w-full py-3 bg-blue-600/20 hover:bg-blue-600/30 border border-blue-500/50 rounded-xl font-bold text-blue-300 text-sm cursor-pointer transition-colors text-center block">
                                파일 선택 (Smart Merge)
                                <input type="file" accept=".json" onChange={handleFileRestore} className="hidden" />
                            </label>
                        </div>
                     </div>
                ) : (
                    <div className="bg-black/50 rounded-xl border border-white/10 h-full flex flex-col">
                        <div className="flex justify-between items-center p-2 bg-white/5 border-b border-white/10">
                            <span className="text-xs font-mono text-gray-500 ml-2">constants.ts export</span>
                            <button onClick={handleCopy} className={`px-4 py-1.5 rounded-lg text-xs font-bold transition-all ${copied ? 'bg-green-500 text-white' : 'bg-blue-600 hover:bg-blue-500 text-white'}`}>{copied ? "✅ 복사 완료!" : "📋 코드 전체 복사"}</button>
                        </div>
                        <textarea readOnly value={exportCode} className="flex-1 bg-transparent p-4 text-xs font-mono text-blue-200 resize-none focus:outline-none" />
                    </div>
                )}
                </div>
            </GlassCard>
        </div>
    );
};

// --- 2. RANDOM SAMPLE EDITOR ---
const RandomSampleEditor: React.FC<{db: ScenarioDB, onUpdateDb: React.Dispatch<React.SetStateAction<ScenarioDB>>}> = ({ db, onUpdateDb }) => {
    const [samples, setSamples] = useState<Partial<UserInput>[]>(Array.isArray(db.randomSamples) ? db.randomSamples : []);

    useEffect(() => {
        if(Array.isArray(db.randomSamples)) setSamples(db.randomSamples);
        else setSamples([]);
    }, [db.randomSamples]);

    const handleUpdate = (index: number, field: keyof UserInput, value: string | number | boolean) => {
        const newSamples = [...samples];
        if (newSamples[index]) {
            newSamples[index] = { ...newSamples[index], [field]: value };
             if (field === 'useAI' && value === true) newSamples[index].forcedTemplateId = '';
            setSamples(newSamples);
        }
    };

    const handleSave = () => {
        onUpdateDb(prev => ({ ...prev, randomSamples: samples }));
        alert("✅ 저장되었습니다.");
    };

    const handleAdd = () => setSamples([...samples, { age: '30', job: '직장인', start: '서울', goal: '미국', months: 24, forcedTemplateId: '', isDomestic: false, useAI: false }]);

    const handleRemove = (index: number) => {
        if (confirm('삭제하시겠습니까?')) {
            const newSamples = [...samples];
            newSamples.splice(index, 1);
            setSamples(newSamples);
        }
    };

    return (
        <div className="h-full overflow-y-auto p-4 md:p-6 space-y-4">
             <div className="flex justify-between items-center mb-4">
                <h3 className="text-xl font-bold flex items-center gap-2 text-white">🔀 랜덤 예시 설정 <span className="text-xs bg-purple-500/20 text-purple-300 px-2 py-1 rounded-full">{samples.length}개</span></h3>
                <div className="flex gap-2">
                    <button onClick={handleAdd} className="px-3 py-1.5 bg-white/10 hover:bg-white/20 rounded-lg text-xs">추가</button>
                    <button onClick={handleSave} className="px-4 py-1.5 bg-emerald-600 hover:bg-emerald-500 rounded-lg text-xs font-bold text-white">저장</button>
                </div>
            </div>
            <div className="grid grid-cols-1 gap-4">
                {samples.map((sample, idx) => (
                    <div key={idx} className="bg-white/5 border border-white/10 p-4 rounded-xl text-sm space-y-2">
                         <div className="flex justify-between">
                            <span className="text-xs text-gray-500">#{idx + 1}</span>
                            <button onClick={() => handleRemove(idx)} className="text-red-400 hover:text-red-300">삭제</button>
                         </div>
                         <div className="grid grid-cols-2 md:grid-cols-4 gap-2">
                            <input value={sample.age} onChange={(e) => handleUpdate(idx, 'age', e.target.value)} placeholder="나이" className="bg-black/30 p-2 rounded border border-white/5 text-white" />
                            <input value={sample.job} onChange={(e) => handleUpdate(idx, 'job', e.target.value)} placeholder="직업" className="bg-black/30 p-2 rounded border border-white/5 text-white" />
                            <input value={sample.start} onChange={(e) => handleUpdate(idx, 'start', e.target.value)} placeholder="출발지" className="bg-black/30 p-2 rounded border border-white/5 text-white" />
                            <input value={sample.goal} onChange={(e) => handleUpdate(idx, 'goal', e.target.value)} placeholder="목적지" className="bg-black/30 p-2 rounded border border-white/5 text-white" />
                         </div>
                         <div className="flex items-center gap-4 text-xs text-gray-400">
                             <label className="flex items-center gap-2"><input type="checkbox" checked={!!sample.isDomestic} onChange={(e) => handleUpdate(idx, 'isDomestic', e.target.checked)} /> 국내이동</label>
                             <label className="flex items-center gap-2 text-emerald-400"><input type="checkbox" checked={!!sample.useAI} onChange={(e) => handleUpdate(idx, 'useAI', e.target.checked)} /> AI 생성 강제</label>
                         </div>
                    </div>
                ))}
            </div>
        </div>
    );
};

