const EssayEditor: React.FC<{ db: ScenarioDB, onUpdateDb: React.Dispatch<React.SetStateAction<ScenarioDB>> }> = ({ db, onUpdateDb }) => {
    const [essays, setEssays] = useState<StandaloneEssay[]>(db.essays || []);

