    };

    const handleSave = () => {
        onUpdateDb(prev => ({ ...prev, essays }));
        alert("✅ 저장되었습니다.");
    };

    return (
        <div className="h-full overflow-y-auto p-6 space-y-4">
            <div className="flex justify-between items-center mb-4">
