}

export const AdBanner: React.FC<AdBannerProps> = ({ 
    className = '', 
    format = 'auto',
    clientId = "ca-pub-2826263278655860", // Default provided by user
    slotId = "6505435536"                // Default provided by user
}) => {
    const adRef = useRef<HTMLModElement>(null);

    useEffect(() => {
        if (!clientId) return;

        try {
            // @ts-ignore
            const adsbygoogle = window.adsbygoogle || [];
            // Prevent pushing multiple times for the same slot if React re-renders or StrictMode runs twice
            // We check if the ins element is empty. AdSense fills it with an iframe.
            if (adRef.current && adRef.current.innerHTML === "") {
                // @ts-ignore
                adsbygoogle.push({});
            }
        } catch (e) {
            console.error("AdSense Error:", e);
