    // Fallback UI if no ID provided
    if (!clientId) {
        return (
            <div className={`w-full bg-gray-900/50 border border-dashed border-gray-700 rounded-xl p-4 text-center flex flex-col items-center justify-center min-h-[100px] ${className}`}>
