    }

    return (
        <div className={`w-full overflow-hidden my-4 bg-transparent text-center ${className}`}>
             {/* @ts-ignore */}
            <ins className="adsbygoogle"
                ref={adRef}
                style={{ display: 'block', minWidth: '300px', minHeight: '100px' }}
